local config = {
  ui_story_5032_50320101_1_dialog_content = "<color=#e8d9bb>PlayerName, Vice, dan Carleen, yang merasa tersesat dalam pengejaran kekuasaan, sedang menuju ke pelabuhan Harbour City yang ramai.</color>",
  ui_story_5032_50320101_2_dialog_content = "<color=#e8d9bb>Dalam perjalanan mereka untuk mengunjungi Laird Elvis, Caelestite sekali lagi bertemu Fia, ahli ekstrozoologi.</color>",
  ui_story_5032_50320101_3_dialog_content = "<color=#e8d9bb>Laird Elvis dengan hangat menyambut kelompok itu, tetapi dia tampaknya menyembunyikan sesuatu di bawah tubuhnya yang lemah dan wajahnya yang penuh bekas luka.</color>",
  ui_story_5032_50320101_4_dialog_content = "<color=#e8d9bb>Sebuah putaran nasib membawa kelompok itu ke Emerald, sebuah kapal tempat festival akbar diadakan.</color>",
  ui_story_5032_50320101_5_dialog_content = "<color=#e8d9bb>Di Sini, PlayerName dan yang lainnya bertemu Jeno, biang keladi misterius dan jauh.</color>",
  ui_story_5032_50320101_6_dialog_content = "<color=#e8d9bb>Rainbow yang ceria dan antusias, yang merupakan pembawa acara sirkus, penghubung pelanggan, direktur keamanan, dan magang insinyur kelautan.</color>",
  ui_story_5032_50320101_7_dialog_content = "<color=#e8d9bb>Dan tiga seniman trapeze terbang tinggi yang mendebarkan, Merylt, Subli, dan Frimet.</color>",
  ui_story_5032_50320101_8_dialog_content = "<color=#e8d9bb>Fia yakin bahwa binatang ajaib yang dia cari, a <color=#FFB400>paus awan</color>, ada di suatu tempat di Emerald.</color>",
  ui_story_5032_50320101_9_dialog_content = "<color=#e8d9bb>Untuk mengetahui apakah dia benar, pasukan Caelestite memutuskan untuk mendaftar kompetisi dan membeli lebih banyak waktu untuk menjelajahi sirkus.</color>",
  ui_story_5032_50320101_10_dialog_content = "<color=#e8d9bb>Sementara itu, Carleen, yang masih merasa kehilangan, bertanya pada Vice bagaimana dia bisa menjadi lebih kuat.</color>",
  ui_story_5032_50320101_11_dialog_content = "<color=#e8d9bb>Zamrud dipenuhi dengan kegembiraan dan tawa, tetapi Laird Elvis, yang duduk di antara para juri, tenggelam dalam pikirannya.</color>",
  ui_story_5032_50320101_12_dialog_content = "<color=#e8d9bb>Frustrasi selama kompetisi, Carleen memperoleh beberapa wawasan baru berkat dorongan PlayerName.</color>",
  ui_story_5032_50320101_13_dialog_content = "<color=#e8d9bb>Pada akhirnya, skuad Caelestite menang. Tapi hadiahnya bukan Cloudwhale.</color>",
  ui_story_5032_50320101_14_dialog_content = "<color=#e8d9bb>Sebagai gantinya, hadiahnya adalah Kyllo, pendamping binatang buas Fia yang menakjubkan, yang dia kirim untuk mencari Cloudwhale di perairan terdekat.</color>",
  ui_story_5032_50320101_15_dialog_content = "<color=#e8d9bb>Kecewa, kelompok bersiap untuk mengucapkan selamat tinggal pada Jeno dan melanjutkan pencarian mereka untuk Cloudwhale.</color>",
  ui_story_5032_50320101_16_dialog_content = "<color=#e8d9bb>Tetapi ketika mereka mencari Jeno, mereka menemukannya pingsan di kabin Emerald.</color>",
  ui_story_5032_50320101_17_dialog_content = "<color=#e8d9bb>Saat mereka berhasil membangunkannya, kapal bergetar hebat.</color>",
  ui_story_5032_50320101_18_dialog_content = "<color=#e8d9bb>Jeno memandu tim saat mereka bergegas ke ruang inti Zamrud.</color>",
  ui_story_5032_50320101_19_dialog_content = "<color=#e8d9bb>Namun dalam perjalanan, penjaga yang membawa stempel keluarga Elvis memblokir jalan mereka.</color>",
  ui_story_5032_50320101_20_dialog_content = "<color=#e8d9bb>Setelah mengatasi berbagai rintangan, kelompok Caelestite mencapai ruang inti dan akhirnya menemukan Elvis di sana.</color>",
  ui_story_5032_50320101_21_dialog_content = "<color=#e8d9bb>Dan dia menggunakan beberapa perangkat di stafnya untuk menyerap daya dari inti energi.</color>",
  ui_story_5032_50320101_22_dialog_content = "<color=#e8d9bb>Tindakan tersebut membangunkan mesin besar yang menjaga inti, yang mulai menyerang kelompok.</color>",
  ui_story_5032_50320101_23_dialog_content = "<color=#e8d9bb>Guardian yang kuat mendorong tim Colossus ke jurang kekalahan. Bahkan Carleen dilumpuhkan oleh jebakan Elvis.</color>",
  ui_story_5032_50320101_24_dialog_content = "<color=#e8d9bb>Tetapi pada saat yang menentukan, kekuatan baru muncul di dalam Carleen, mendorong kembali Guardian.</color>",
  ui_story_5032_50320101_25_dialog_content = "<color=#e8d9bb>Kelompok itu mengalahkan Guardian, tetapi Elvis melarikan diri—hanya untuk ditangkap oleh Matthieu, seorang hakim Lumopolis.</color>",
  ui_story_5032_50320101_26_dialog_content = "<color=#e8d9bb>Tapi sepertinya semua ini... masih jauh dari selesai.</color>",
  ui_story_5032_50320101_27_dialog_content = "<color=#e8d9bb>Udara mengaum dalam hujan yang dingin, dan langit menyala dalam angin liar. Badai yang akan menghancurkan Harbour City akan datang!</color>",
  ui_story_5032_50320101_28_dialog_content = "Cepat cepat! Pemandangan dari sini luar biasa!",
  ui_story_5032_50320101_29_dialog_content = "E-Elvis! Anda berlari terlalu cepat!",
  ui_story_5032_50320101_30_dialog_content = "Wow...",
  ui_story_5032_50320101_31_dialog_content = "Bagaimana tentang itu? Anda tidak bisa melihat pemandangan seperti ini tinggal di rumah.",
  ui_story_5032_50320101_32_dialog_content = "Jangan khawatir tentang preman-preman kecil yang membuat masalah itu. Saya bisa menangani mereka dan banyak lagi.",
  ui_story_5032_50320101_33_dialog_content = "Pantai ini, lautan ini—suatu hari nanti semuanya akan menjadi milik Anda dan saya.",
  ui_story_5032_50320101_34_dialog_content = "Ya!",
  ui_story_5032_50320101_35_dialog_content = "Terkadang saya bermimpi melakukan ini. Keluar dari kamarku dan melukis dunia luar.",
  ui_story_5032_50320101_36_dialog_content = "Mungkin... Mungkin aku harus melukis momen kita ini.",
  ui_story_5032_50320101_37_dialog_content = "Betulkah? Anda akan melukis saya?",
  ui_story_5032_50320101_38_dialog_content = "Ya, tapi aku lambat dan juga tidak pandai.",
  ui_story_5032_50320101_39_dialog_content = "Tidak masalah. Gambar Anda adalah yang terbaik untuk saya!",
  ui_story_5032_50320101_40_dialog_content = "Jadi... kenapa kita tidak bertemu besok pagi di pelabuhan?",
  ui_story_5032_50320101_41_dialog_content = "Kita bisa mengumpulkan beberapa makanan laut dari pantai. Lalu kamu bisa melukisku, dan aku akan membuatkanmu sup seafood!",
  ui_story_5032_50320101_42_dialog_content = "Wow, sup seafood Elvis!",
  ui_story_5032_50320101_43_dialog_content = "Luar biasa! Ini kesepakatan, kalau begitu!",
  ui_story_5032_50320101_44_dialog_content = "Setuju!",
  ui_story_5032_50320101_45_dialog_content = "Kami punya kesepakatan...",
  ui_story_5032_50320101_46_dialog_content = "Kami telah sepakat untuk bertemu...",
  ui_story_5032_50320101_47_dialog_content = "Jadi bagaimana Anda bisa pergi tanpa mengucapkan selamat tinggal?",
  ui_story_5032_50320101_48_dialog_content = "Mengapa Anda mengkhianati saya? Mengapa Anda menghancurkan rumah saya? Mengapa Anda melanggar sumpah saya untuk True Order?",
  ui_story_5032_50320101_49_dialog_content = "Dan kenapa kau terlihat... begitu menyakitkan?",
  ui_story_5032_50320101_50_dialog_content = "Bos.",
  ui_story_5032_50320101_51_dialog_content = "Bos!",
  ui_story_5032_50320101_52_dialog_content = "Bos!!",
  ui_story_5032_50320101_53_dialog_content = "Apa?",
  ui_story_5032_50320101_54_dialog_content = "Apa yang Anda lihat? Anda berada bermil-mil jauhnya.",
  ui_story_5032_50320101_55_dialog_content = "Tidak ada apa-apa. Saya hanya berpikir tentang cara memperbaiki Zamrud.",
  ui_story_5032_50320101_56_dialog_content = "Ah, benarkah? Saya pikir Anda telah memberikan tugas itu kepada Ciel dan saya.",
  ui_story_5032_50320101_57_dialog_content = "...",
  ui_story_5032_50320101_58_dialog_content = "Hei, bos.",
  ui_story_5032_50320101_59_dialog_content = "Aku tidak benar-benar tahu apa yang terjadi antara kamu dan Laird Elvis.",
  ui_story_5032_50320101_60_dialog_content = "Tapi aku mendengar Caelestite mengatakan bahwa Elvis meminta untuk bertemu denganmu berkali-kali setelah dia ditahan.",
  ui_story_5032_50320101_61_dialog_content = "Hmph.",
  ui_story_5032_50320101_62_dialog_content = "Saya tidak punya apa-apa untuk dikatakan kepada seseorang yang hampir menghancurkan Zamrud.",
  ui_story_5032_50320101_63_dialog_content = "Oh... Itu saja?",
  ui_story_5032_50320101_64_dialog_content = "Tapi aku agak merasa tidak enak padanya. Kudengar Sindrom Modali-nya semakin parah.",
  ui_story_5032_50320101_65_dialog_content = "Dan dia menolak untuk makan...",
  ui_story_5032_50320101_66_dialog_content = "Jika ini terus berlanjut... Kurasa dia tidak akan bertahan lama dengan tubuh lemahnya itu.",
  ui_story_5032_50320101_67_dialog_content = "Apa kaubilang!?",
  ui_story_5032_50320101_68_dialog_content = "Eh? Bos?",
  ui_story_5032_50320101_69_dialog_content = "Sekarang kemana kamu pergi?",
  ui_story_5032_50320101_70_dialog_content = "Aku baru ingat kita kehabisan balon.",
  ui_story_5032_50320101_71_dialog_content = "Aku akan membeli beberapa.",
  ui_story_5032_50320101_72_dialog_content = "Eh? Apa?",
  ui_story_5032_50320101_73_dialog_content = "Ada peti penuh dari mereka tepat di mana Anda berdiri ...",
  ui_story_5032_50320101_74_dialog_content = "Hakim Matthieu, Asisten Hakim Loewe.",
  ui_story_5032_50320101_75_dialog_content = "Maaf membuatmu menunggu lama.",
  ui_story_5032_50320101_76_dialog_content = "Saya tidak tahu Elvis memiliki begitu banyak tugas yang harus diselesaikan setiap hari.",
  ui_story_5032_50320101_77_dialog_content = "Dan bagaimana dia?",
  ui_story_5032_50320101_78_dialog_content = "Sama. Dia menolak untuk makan atau bahkan minum.",
  ui_story_5032_50320101_79_dialog_content = "Betulkah? Saya harus mengagumi tekadnya.",
  ui_story_5032_50320101_80_dialog_content = "Eh, bolehkah saya bertanya, Yang Mulia, berapa lama Anda berencana untuk melanjutkan ini?",
  ui_story_5032_50320101_81_dialog_content = "Kami telah, seperti yang Anda instruksikan, membuat laporan ke Dewan Penatua. Tapi itu tidak akan memuaskan mereka lama.",
  ui_story_5032_50320101_82_dialog_content = "Kita harus segera mengetahui motif sebenarnya Elvis dan membasmi benih-benih pemberontakan.",
  ui_story_5032_50320101_83_dialog_content = "Kalau tidak, kekacauan di Harbour City mungkin akan menjadi masalah kita untuk diperbaiki.",
  ui_story_5032_50320101_84_dialog_content = "Lord Schwartz sangat marah, dan rakyat jelata telah kehilangan sarang kesayangan mereka. Semua orang gelisah.",
  ui_story_5032_50320101_85_dialog_content = "Akan lebih baik untuk segera kembali ke Lumopolis. Dan biarkan Lord Schwartz mengirim anak buahnya untuk menyelidiki.",
  ui_story_5032_50320101_86_dialog_content = "Tidak. Pertama, saya tidak akan menyerah di tengah jalan.",
  ui_story_5032_50320101_87_dialog_content = "Kedua, saya tidak bisa pergi begitu saja.",
  ui_story_5032_50320101_88_dialog_content = "Jika saya melakukannya, bagaimana saya bisa yakin bahwa Lord Schwartz dan warga Harbour City akan mendapatkan jawaban yang layak mereka dapatkan?",
  ui_story_5032_50320101_89_dialog_content = "Baiklah baiklah. Saya mengerti. Lupakan apa yang saya katakan.",
  ui_story_5032_50320101_90_dialog_content = "Namun demikian, saya berterima kasih, Hakim Matthieu.",
  ui_story_5032_50320101_91_dialog_content = "Itu baru.",
  ui_story_5032_50320101_92_dialog_content = "Hah? Apa itu? Saya dapat mengatakan hal-hal yang berguna sesekali, oke?",
  ui_story_5032_50320101_93_dialog_content = "Tentu.",
  ui_story_5032_50320101_94_dialog_content = "Tunggu sampai saya selesai menulis laporan saya, dan saya akan mengajari Anda mengapa saya menjadi juri, dan Anda adalah asisten saya!",
  ui_story_5032_50320101_95_dialog_content = "Kalau begitu, aku akan menyerahkan tugas menjaga Elvis di tanganmu yang cakap.",
  ui_story_5032_50320101_96_dialog_content = "Siap, laksanakan.",
  ui_story_5032_50320101_97_dialog_content = "Carleen, kami kembali.",
  ui_story_5032_50320101_98_dialog_content = "Bagaimana perasaanmu? Apakah masih sakit?",
  ui_story_5032_50320101_99_dialog_content = "Selamat datang kembali. Luka saya dan Lumina saya pulih lebih cepat dari yang saya perkirakan.",
  ui_story_5032_50320101_100_dialog_content = "Aku sudah cukup sehat untuk menangani pertarungan biasa. Jangan khawatir tentang saya.",
  ui_story_5032_50320101_101_dialog_content = "Bagaimana dengan orang-orang yang memprotes penahanan Elvis? Apakah mereka sudah pergi?",
  ui_story_5032_50320101_102_dialog_content = "Kamu yakin itu akan berhasil?",
  ui_story_5032_50320101_103_dialog_content = "Mayoritas pengunjuk rasa bersedia pergi dengan tenang begitu mereka mendengar Putri Carleen dari Lumopolis memimpin penyelidikan.",
  ui_story_5032_50320101_104_dialog_content = "Tetapi ada beberapa penentang yang tidak mau mendengarkan.",
  ui_story_5032_50320101_105_dialog_content = "Lukamu tampak serius setelah pertempuran, Carleen. Anda memberi saya cukup ketakutan.",
  ui_story_5032_50320101_106_dialog_content = "Tolong, jangan terlalu memaksakan diri di masa depan.",
  ui_story_5032_50320101_107_dialog_content = "Saya tahu. Maaf karena mengkhawatirkan kalian, Vice, dan PlayerName.",
  ui_story_5032_50320101_108_dialog_content = "Oh, dan kami bertemu dengan seorang penjaga dalam perjalanan kembali yang memberi tahu kami tentang penampakan Eclipsites yang tersebar di pantai.",
  ui_story_5032_50320101_109_dialog_content = "gerhana lagi? Ada laporan tentang penampilan akhir-akhir ini.",
  ui_story_5032_50320101_110_dialog_content = "Tapi investigasi lanjutan kami tidak menghasilkan apa-apa.",
  ui_story_5032_50320101_111_dialog_content = "Mungkin Patou akan tahu sesuatu. Dia ahli dalam pertahanan kota.",
  ui_story_5032_50320101_112_dialog_content = "Hmm. Patou dan penjaga Elvis lainnya telah dikurung bersama, tetapi mereka tidak bekerja sama.",
  ui_story_5032_50320101_113_dialog_content = "Elvis telah memperingatkan krisis yang akan segera terjadi. Apakah Anda pikir itu ada hubungannya dengan Eclipsites?",
  ui_story_5032_50320101_114_dialog_content = "Mungkin. Tapi seperti yang terjadi, jumlah mereka tidak cukup tinggi untuk mewakili ancaman.",
  ui_story_5032_50320101_115_dialog_content = "Dan dia menolak untuk mengatakan apa yang akan menjadi krisis. Yang dia lakukan hanyalah meminta untuk bertemu Jeno.",
  ui_story_5032_50320101_116_dialog_content = "Teman masa kecilnya? Nah, itu menyentuh ...",
  ui_story_5032_50320101_117_dialog_content = "PlayerName, bisakah kamu dan Vice pergi mengunjungi Elvis sekali lagi? Lihat apakah Anda dapat menemukan petunjuk dalam apa pun yang dia katakan.",
  ui_story_5032_50320101_118_dialog_content = "Dan berbicara dengan Jeno juga. Jika dia mau berbicara dengan Elvis... Yah, mungkin kita bisa belajar lebih banyak.",
  ui_story_5032_50320101_119_dialog_content = "Tentu saja. Tinggalkan dengan kami.",
  ui_story_5032_50320201_1_dialog_content = "Rainbow, apakah Anda ingin mencoba memulai ulang sistem?",
  ui_story_5032_50320201_2_dialog_content = "Roger. Aku akan mencobanya lagi.",
  ui_story_5032_50320201_3_dialog_content = "<color=#e8d9bb>... Sistem memulai ulang. Memulai pengujian diri.</color>",
  ui_story_5032_50320201_4_dialog_content = "<color=#e8d9bb>Anomali terdeteksi.</color>",
  ui_story_5032_50320201_5_dialog_content = "<color=#e8d9bb>Kesalahan sistem mesin.</color>",
  ui_story_5032_50320201_6_dialog_content = "<color=#e8d9bb>Kesalahan sistem transmisi.</color>",
  ui_story_5032_50320201_7_dialog_content = "Tidak baik. Itu masih tidak akan mulai.",
  ui_story_5032_50320201_8_dialog_content = "Maaf...",
  ui_story_5032_50320201_9_dialog_content = "Berhenti meminta maaf!",
  ui_story_5032_50320201_10_dialog_content = "Aku tahu kamu mencoba yang terbaik. Anda telah membantu saya memperbaiki sistem mesin selama berabad-abad dan saya tidak ingat kapan terakhir kali Anda istirahat.",
  ui_story_5032_50320201_11_dialog_content = "Tidak apa-apa.",
  ui_story_5032_50320201_12_dialog_content = "Anda membantu saya meningkatkan Styx. Jadi sekarang saya perlu membantu Anda mendapatkan Zamrud Anda dan berjalan lagi.",
  ui_story_5032_50320201_13_dialog_content = "Karena itulah gunanya teman, bukan?",
  ui_story_5032_50320201_14_dialog_content = "Ya! Dan kau teman yang sangat baik, Ciel.",
  ui_story_5032_50320201_15_dialog_content = "Saya sangat bersyukur memiliki Anda di sini membantu saya memperbaiki Zamrud.",
  ui_story_5032_50320201_16_dialog_content = "Hei, Anda berdiri terlalu dekat dan saya tidak bisa membaca datanya.",
  ui_story_5032_50320201_17_dialog_content = "Tunggu sebentar. Melihat log ini yang baru saja saya ekstrak... apakah ada mesin yang dikeluarkan dari kapal ini?",
  ui_story_5032_50320201_18_dialog_content = "Bisa jadi. Saya ingat insinyur tua itu memberi tahu saya bahwa kapal itu memiliki sejarah yang panjang dan kompleks.",
  ui_story_5032_50320201_19_dialog_content = "Sayangnya, dia tidak bersama kita lagi. Jika dia—",
  ui_story_5032_50320201_20_dialog_content = "*Menangis* Kalau saja dia masih di sini—",
  ui_story_5032_50320201_21_dialog_content = "Apa yang terjadi? Apakah sesuatu yang buruk terjadi padanya?",
  ui_story_5032_50320201_22_dialog_content = "Tidak. Dia mengatakan bahwa dia akhirnya menemukan penggantinya. Dan kemudian pergi begitu saja saat kami berlabuh tanpa pamit.",
  ui_story_5032_50320201_23_dialog_content = "Kudengar dia sudah menikah dan punya anak sekarang, dan menjalankan barbekyu bersama.",
  ui_story_5032_50320201_24_dialog_content = "Tapi aku masih belum belajar banyak darinya. Jadi saya harus mempelajari semuanya sendiri. Untungnya saya menikmatinya.",
  ui_story_5032_50320201_25_dialog_content = "Dan untungnya, inti tidak memerlukan banyak perawatan dan tidak memiliki masalah sejak saya mengambil alih.",
  ui_story_5032_50320201_26_dialog_content = "Itu sebenarnya sangat bisa diandalkan. Itu membuat saya bertanya-tanya untuk apa kapal itu awalnya digunakan ...",
  ui_story_5032_50320201_27_dialog_content = "Dan dengan Guardian, itu hanya menambah misteri.",
  ui_story_5032_50320201_28_dialog_content = "Sebenarnya, saya pernah bertanya kepada pendahulu saya apa Guardian itu.",
  ui_story_5032_50320201_29_dialog_content = "Tapi dia mengabaikanku, mengatakan itu mungkin hanya hiasan yang terlihat keren.",
  ui_story_5032_50320201_30_dialog_content = "Hah. Sepertinya dia orang yang aneh.",
  ui_story_5032_50320201_31_dialog_content = "Saya tau? Tapi Zamrud masih bekerja, bahkan jika tidak memiliki insinyur terbaik. Itu kapal yang bagus!",
  ui_story_5032_50320201_32_dialog_content = "... Graagh!",
  ui_story_5032_50320201_33_dialog_content = "Tunggu. Apakah Anda mendengar sesuatu di kejauhan?",
  ui_story_5032_50320201_34_dialog_content = "Eh? Merylt, kamu benar-benar menulis PlayerName sebuah surat?",
  ui_story_5032_50320201_35_dialog_content = "Biarkan saya membantu Anda! Aku bisa memberikannya untukmu.",
  ui_story_5032_50320201_36_dialog_content = "Anda tahu, jika Anda terlalu malu untuk menyerahkannya.",
  ui_story_5032_50320201_37_dialog_content = "Tapi... Saya pikir saya harus memberikannya secara pribadi.",
  ui_story_5032_50320201_38_dialog_content = "Tidak tidak! Anda harus membiarkan saya melakukannya, Merylt!",
  ui_story_5032_50320201_39_dialog_content = "Subli pasti akan membukanya dan membacanya! Keingintahuannya melarangnya melakukan sebaliknya.",
  ui_story_5032_50320201_40_dialog_content = "Dia bahkan mungkin menambahkan beberapa hal ke dalamnya.",
  ui_story_5032_50320201_41_dialog_content = "Eh? Dia tidak mau, kan?",
  ui_story_5032_50320201_42_dialog_content = "Maaf, Merylt, tapi Frimet terlalu mengenalku.",
  ui_story_5032_50320201_43_dialog_content = "Ah, kembalikan surat itu padaku!",
  ui_story_5032_50320201_44_dialog_content = "Bica, ambilkan untukku.",
  ui_story_5032_50320201_45_dialog_content = "Hai?",
  ui_story_5032_50320201_46_dialog_content = "Berhenti sekarang juga!",
  ui_story_5032_50320201_47_dialog_content = "Ini suratmu.",
  ui_story_5032_50320201_48_dialog_content = "T-terima kasih, Nona Fia.",
  ui_story_5032_50320201_49_dialog_content = "Betapa sekelompok anak-anak yang gaduh.",
  ui_story_5032_50320201_50_dialog_content = "Tidak bisakah kamu lebih dewasa? Seperti saya.",
  ui_story_5032_50320201_51_dialog_content = "Ah, kamu sudah dewasa? Saya tidak menyadarinya.",
  ui_story_5032_50320201_52_dialog_content = "Dan jika kita berbicara tentang kekuatan, bahkan Merylt mungkin bisa mengalahkanmu.",
  ui_story_5032_50320201_53_dialog_content = "Apa katamu!? Ingin tahu seberapa kuat saya?",
  ui_story_5032_50320201_54_dialog_content = "Subli, Frimet, berhenti menggoda Nona Fia. Dia tamu sirkus, ingat?",
  ui_story_5032_50320201_55_dialog_content = "Baik.",
  ui_story_5032_50320201_56_dialog_content = "Hmph. Hei, kenapa kalian bertiga tidak tinggal di darat seperti kru lainnya?",
  ui_story_5032_50320201_57_dialog_content = "Aku bisa menjaga binatang yang menakjubkan itu sendiri.",
  ui_story_5032_50320201_58_dialog_content = "Bagaimanapun, saya adalah anggota sementara sirkus, dan merawat hewan adalah bidang keahlian saya.",
  ui_story_5032_50320201_59_dialog_content = "Bagaimana kita bisa?",
  ui_story_5032_50320201_60_dialog_content = "Orang-orang di kota mengira kami orang-orang sirkus yang melukai Laird Elvis tercinta mereka.",
  ui_story_5032_50320201_61_dialog_content = "Mereka akan memberi kita sikap dingin yang terbaik dan bahkan mungkin mencoba untuk memulai perkelahian.",
  ui_story_5032_50320201_62_dialog_content = "Lagi pula, kami lebih suka berada di Emerald.",
  ui_story_5032_50320201_63_dialog_content = "Bagaimanapun, ini adalah rumah kita, kau tahu?",
  ui_story_5032_50320201_64_dialog_content = "Ya...",
  ui_story_5032_50320201_65_dialog_content = "Saya pikir saya bisa mengerti bagaimana perasaan Anda.",
  ui_story_5032_50320201_66_dialog_content = "Pekerjaan saya sebagai ahli ekstrozoologi melibatkan jelajah di setiap sudut benua—tetapi terkadang, saya masih merindukan sup daging ibu saya.",
  ui_story_5032_50320201_67_dialog_content = "Dan berbicara tentang hewan yang menakjubkan, saya masih belum mencapai tujuan yang membawa saya ke Harbour City.",
  ui_story_5032_50320201_68_dialog_content = "Tempat apa itu?",
  ui_story_5032_50320201_69_dialog_content = "Ayo, beritahu kami. Kami mungkin bisa membantu.",
  ui_story_5032_50320201_70_dialog_content = "Yah, kurasa tidak ada gunanya menjadi rahasia sekarang.",
  ui_story_5032_50320201_71_dialog_content = "Baiklah.",
  ui_story_5032_50320201_72_dialog_content = "Saya sebenarnya sedang mencari binatang ajaib yang eksotis. Itu <color=#FFB400>paus awan</color>!",
  ui_story_5032_50320201_73_dialog_content = "Apa itu, sejenis paus?",
  ui_story_5032_50320201_74_dialog_content = "Y-Ya, kurasa begitu.",
  ui_story_5032_50320201_75_dialog_content = "Maksudku, bukannya aku tidak tahu. Hanya saja tuanku yang buruk tidak menjelaskan dengan benar.",
  ui_story_5032_50320201_76_dialog_content = "Dia memberi tahu saya bahwa jejak energi Cloudwhale menghilang di suatu tempat di laut dekat sini, lalu mengirim saya untuk menyelidiki.",
  ui_story_5032_50320201_77_dialog_content = "Yang saya tahu adalah bahwa Lumina yang kuat dapat membuat Eclipsites meringkuk ketakutan dan menghilangkan Darkflow yang paling tebal sekalipun.",
  ui_story_5032_50320201_78_dialog_content = "Paus? Saya belum pernah melihatnya, tetapi saya pernah mendengar orang-orang sirkus yang lebih tua membicarakannya.",
  ui_story_5032_50320201_79_dialog_content = "Mereka semua besar dan menghabiskan sebagian besar waktu mereka jauh di dalam laut.",
  ui_story_5032_50320201_80_dialog_content = "Sepertinya mereka akan mudah terdampar jika datang ke perairan dangkal.",
  ui_story_5032_50320201_81_dialog_content = "Ya, dan bukankah semua ikan takut pada kapal? Saya tidak berharap seseorang berenang di dekat sini.",
  ui_story_5032_50320201_82_dialog_content = "Argh! Apakah pria itu mengirim saya untuk mengejar angsa liar?",
  ui_story_5032_50320201_83_dialog_content = "Lalu aku mengalami krisis!",
  ui_story_5032_50320201_84_dialog_content = "Ah!",
  ui_story_5032_50320201_85_dialog_content = "Ups, maaf tiba-tiba berteriak seperti itu. Apakah saya menakut-nakuti Anda?",
  ui_story_5032_50320201_86_dialog_content = "Tidak apa-apa. Saya baru saja menjatuhkan semua barang saya, itu saja.",
  ui_story_5032_50320201_87_dialog_content = "Jangan bergerak, aku akan mengambilnya untukmu.",
  ui_story_5032_50320201_88_dialog_content = "Hah!",
  ui_story_5032_50320201_89_dialog_content = "Hah!!",
  ui_story_5032_50320201_90_dialog_content = "Apakah itu semuanya? Dan apa ini? Beberapa jenis makanan ringan yang enak?",
  ui_story_5032_50320201_91_dialog_content = "Itu benar, sama seperti semua permen lezat yang kamu ambil terakhir kali! Dan itu akan membantu Anda menjadi lebih tinggi.",
  ui_story_5032_50320201_92_dialog_content = "Subli, jangan coba-coba membuat Fia memakan makanan ikan.",
  ui_story_5032_50320201_93_dialog_content = "Sebenarnya itulah makanan ikan yang saya buat sendiri.",
  ui_story_5032_50320201_94_dialog_content = "Tapi jika kamu menyukai permen yang kita miliki terakhir kali... Aku bisa membuatkan untukmu!",
  ui_story_5032_50320201_95_dialog_content = "Apa, aku? Nah, aku terlalu tua untuk hal-hal seperti permen. Saya penasaran!",
  ui_story_5032_50320201_96_dialog_content = "Hei, Merylt, apakah kamu memelihara ikan? Biarkan saya membantu Anda mengidentifikasi ras apa mereka!",
  ui_story_5032_50320201_97_dialog_content = "Itu yang kecil, di sana.",
  ui_story_5032_50320201_98_dialog_content = "Hmm. Hanya pria abu-abu kecil ini. Saya tidak tahu jenis apa itu.",
  ui_story_5032_50320201_99_dialog_content = "Eep!",
  ui_story_5032_50320201_100_dialog_content = "Bisakah itu benar-benar memakan semua itu dalam satu kali makan? Itu luar biasa!",
  ui_story_5032_50320201_101_dialog_content = "Pemimpin sirkus kami menemukan pria kecil ini di pantai...",
  ui_story_5032_50320201_102_dialog_content = "Dia mengatakan itu tampak terluka dan membawanya kembali ke saya untuk menjaganya.",
  ui_story_5032_50320201_103_dialog_content = "Oh, dan dia bilang sudah ada di botol ini saat dia menemukannya.",
  ui_story_5032_50320201_104_dialog_content = "Saya sudah memesan tangki ikan yang tepat, tetapi belum siap. Jadi pria kecil kita terjebak di sana untuk saat ini.",
  ui_story_5032_50320201_105_dialog_content = "Saya tidak pernah berpikir bahwa biang keladi yang galak akan begitu baik kepada binatang.",
  ui_story_5032_50320201_106_dialog_content = "Ya... Dia bahkan memberinya nama: <color=#FFB400>Geedo</color>.",
  ui_story_5032_50320201_107_dialog_content = "Hei, Fia... Mungkinkah ini Cloudwhale yang kamu cari?",
  ui_story_5032_50320201_108_dialog_content = "Eep!",
  ui_story_5032_50320201_109_dialog_content = "Geedo terlalu kecil untuk menjadi Cloudwhale.",
  ui_story_5032_50320201_110_dialog_content = "Ringmaster Jeno mengatakan kepada saya bahwa bahkan bayi paus akan terlalu besar untuk kapal ini.",
  ui_story_5032_50320201_111_dialog_content = "Dan paus tidak mengatakan \"eep eep.\" Mereka pergi \"croak croak.\"",
  ui_story_5032_50320201_112_dialog_content = "Betulkah? Bukankah itu \"sialan.\"",
  ui_story_5032_50320201_113_dialog_content = "Sangat salah. Ini \"woo woo.\"",
  ui_story_5032_50320201_114_dialog_content = "Bukankah itu \"kicau kicau\"?",
  ui_story_5032_50320201_115_dialog_content = "Graagh—",
  ui_story_5032_50320201_116_dialog_content = "Anda semua salah! Bukan seperti itu suara paus. Ini benar-benar...",
  ui_story_5032_50320201_117_dialog_content = "Graagh—",
  ui_story_5032_50320201_118_dialog_content = "gerhana! Bagaimana Eclipsites masuk!?",
  ui_story_5032_50320202_1_dialog_content = "Ha-!",
  ui_story_5032_50320202_2_dialog_content = "Hei!",
  ui_story_5032_50320202_3_dialog_content = "Ada lebih banyak dari mereka!",
  ui_story_5032_50320202_4_dialog_content = "Argh...",
  ui_story_5032_50320202_5_dialog_content = "Hati-hati, Fia!",
  ui_story_5032_50320202_6_dialog_content = "Eclipsites Buruk! Ambil ini!",
  ui_story_5032_50320202_7_dialog_content = "<color=#e8d9bb>Der, der!</color>",
  ui_story_5032_50320202_8_dialog_content = "Graagh—",
  ui_story_5032_50320202_9_dialog_content = "Wow, saya tidak pernah berharap Anda menjadi petarung yang baik, Fia.",
  ui_story_5032_50320202_10_dialog_content = "Heee. Eclipsites yang lemah ini tidak cocok untukku.",
  ui_story_5032_50320202_11_dialog_content = "Mereka jelas sangat lemah.",
  ui_story_5032_50320202_12_dialog_content = "Teman-teman! Apakah Anda semua baik-baik saja?",
  ui_story_5032_50320202_13_dialog_content = "Huff, huff... C-Ciel, kamu tidak bisa terburu-buru seperti itu.",
  ui_story_5032_50320202_14_dialog_content = "Terlalu berbahaya sekarang Anda tidak membawa Styx.",
  ui_story_5032_50320202_15_dialog_content = "Saya minta maaf. Tapi aku tahu kau tepat di belakangku, Rainbow.",
  ui_story_5032_50320202_16_dialog_content = "Yah, itu benar.",
  ui_story_5032_50320202_17_dialog_content = "Tapi itu masih terlalu berbahaya. Jangan lakukan lagi.",
  ui_story_5032_50320202_18_dialog_content = "Baiklah… Aku mengerti.",
  ui_story_5032_50320202_19_dialog_content = "Baiklah, tidak ada yang terluka. Itu yang penting.",
  ui_story_5032_50320202_20_dialog_content = "Tapi dari mana Eclipsites ini berasal?",
  ui_story_5032_50320202_21_dialog_content = "Entahlah.",
  ui_story_5032_50320202_22_dialog_content = "Biasanya, kami dapat memeriksa log sistem Zamrud dan mencari tahu.",
  ui_story_5032_50320202_23_dialog_content = "Tapi sistemnya masih mati, jadi saya khawatir kita harus melakukan pencarian tempat demi tempat.",
  ui_story_5032_50320202_24_dialog_content = "Saya kira itu satu-satunya pilihan kami.",
  ui_story_5032_50320202_25_dialog_content = "Tapi sekelompok enam orang terlalu besar untuk pergi menyerbu di dalam kapal.",
  ui_story_5032_50320202_26_dialog_content = "Dan kelompok yang terlalu kecil bisa berbahaya jika lebih banyak Eclipsites muncul.",
  ui_story_5032_50320202_27_dialog_content = "Jadi mari kita bagi menjadi dua tim.",
  ui_story_5032_50320202_28_dialog_content = "Merylt, kamu dan saudara perempuanmu adalah pejuang yang kuat. Kalian bertiga bisa menjadi satu tim.",
  ui_story_5032_50320202_29_dialog_content = "Diterima!",
  ui_story_5032_50320202_30_dialog_content = "Kami tidak begitu akrab dengan barang-barang di dalam kapal, jadi kami harus naik untuk memeriksa geladak dan sekitarnya.",
  ui_story_5032_50320202_31_dialog_content = "Oke, kami serahkan itu padamu.",
  ui_story_5032_50320202_32_dialog_content = "Kemudian saya akan mengikuti Rainbow dan Ciel untuk memeriksa bagian dalam kapal.",
  ui_story_5032_50320202_33_dialog_content = "Oke. Tapi jangan berkeliaran dan menyentuh hal-hal acak hanya karena Anda penasaran.",
  ui_story_5032_50320202_34_dialog_content = "Mungkin masih ada Eclipsites berkeliaran.",
  ui_story_5032_50320202_35_dialog_content = "Oke, saya tidak akan.",
  ui_story_5032_50320301_1_dialog_content = "Elvis masih tidak mau bicara.",
  ui_story_5032_50320301_2_dialog_content = "Dia terus bergumam ingin bertemu Jeno. Jadi kurasa kita perlu bicara dengan Jeno.",
  ui_story_5032_50320301_3_dialog_content = "Tapi terakhir kali saya mencoba, dia mengurung diri di kabinnya dan menolak untuk keluar.",
  ui_story_5032_50320301_4_dialog_content = "Apa yang terjadi dengan Elvis sangat mempengaruhinya. Sepertinya mereka adalah teman dekat di masa lalu.",
  ui_story_5032_50320301_5_dialog_content = "Ya. Jadi jika kita bisa membujuknya untuk membantu, mungkin dia bisa membuat Elvis bicara.",
  ui_story_5032_50320301_6_dialog_content = "...",
  ui_story_5032_50320301_7_dialog_content = "Hei, pria yang berjalan-jalan terlihat tersesat... mungkinkah itu Jeno?",
  ui_story_5032_50320301_8_dialog_content = "Hai! Jeno!",
  ui_story_5032_50320301_9_dialog_content = "Oh, itu kalian.",
  ui_story_5032_50320301_10_dialog_content = "Itu kamu ya Jeno.",
  ui_story_5032_50320301_11_dialog_content = "Aku datang menemuimu lebih awal, tapi... kau tidak mau keluar.",
  ui_story_5032_50320301_12_dialog_content = "Maaf. Aku sedang tidak dalam suasana hati yang baik.",
  ui_story_5032_50320301_13_dialog_content = "Tidak masalah. Tapi kemana kamu pergi? Anda tampaknya tersesat.",
  ui_story_5032_50320301_14_dialog_content = "Terus terang...",
  ui_story_5032_50320301_15_dialog_content = "Saya ingin berbicara dengan Elvis.",
  ui_story_5032_50320301_16_dialog_content = "Apakah ini tempat mereka menahannya?",
  ui_story_5032_50320301_17_dialog_content = "Bukan itu yang saya harapkan.",
  ui_story_5032_50320301_18_dialog_content = "\"Dia bangsawan dan bangsawan. Kita harus memperlakukannya dengan bermartabat, setidaknya sampai dia dinyatakan bersalah.\"",
  ui_story_5032_50320301_19_dialog_content = "Itulah yang dikatakan Carleen. Jadi kita biarkan dia tinggal di sini.",
  ui_story_5032_50320301_20_dialog_content = "Dia dijaga oleh Matthieu dan Loewe dari Hall of Justice dan beberapa penjaga.",
  ui_story_5032_50320301_21_dialog_content = "Hakim Matthieu, ini orang yang diminta Elvis untuk ditemui.",
  ui_story_5032_50320301_22_dialog_content = "Ck, ini orang biasa? Dia terus menerus membicarakanmu. Jeno ini, Jeno itu. Aku muak mendengarnya.",
  ui_story_5032_50320301_23_dialog_content = "...",
  ui_story_5032_50320301_24_dialog_content = "Saya akan memperingatkan Anda sekarang—tidak ada trik. Jika Anda mencoba sesuatu, kami akan menyerang tanpa peringatan.",
  ui_story_5032_50320301_25_dialog_content = "Hmph.",
  ui_story_5032_50320301_26_dialog_content = "<color=#e8d9bb>Klik</color>",
  ui_story_5032_50320301_27_dialog_content = "Jeno? Itu kamu ya Jeno!?",
  ui_story_5032_50320301_28_dialog_content = "Anda akhirnya datang menemui saya.",
  ui_story_5032_50320301_29_dialog_content = "Hmm.",
  ui_story_5032_50320301_30_dialog_content = "Jangan salah paham. Aku di sini hanya untuk melihat apa yang terjadi pada pengkhianat pengkhianat.",
  ui_story_5032_50320301_31_dialog_content = "Saya tidak menyangka akan menemukan Anda di akomodasi yang begitu nyaman.",
  ui_story_5032_50320301_32_dialog_content = "Tampaknya tidak adil ketika Anda memikirkan semua kerusakan yang Anda lakukan pada Zamrud saya.",
  ui_story_5032_50320301_33_dialog_content = "Apakah Anda tahu seberapa keras setiap orang harus bekerja untuk memperbaikinya?",
  ui_story_5032_50320301_34_dialog_content = "Dan Anda duduk di sini, bersantai di kamar Anda yang bersih dan nyaman.",
  ui_story_5032_50320301_35_dialog_content = "Jeno, aku benar-benar minta maaf.",
  ui_story_5032_50320301_36_dialog_content = "Tolong percaya padaku, dan jika aku punya pilihan lain, aku tidak akan menyakitimu.",
  ui_story_5032_50320301_37_dialog_content = "Tapi Anda melakukannya. bukan?",
  ui_story_5032_50320301_38_dialog_content = "Fakta adalah fakta, dan kita tidak bisa mengubahnya. Jadi apa gunanya meminta maaf?",
  ui_story_5032_50320301_39_dialog_content = "Saya mendengar Anda menolak untuk makan dan minum dan bersikeras melihat saya.",
  ui_story_5032_50320301_40_dialog_content = "Apa yang kamu harapkan? Bahwa saya akan mendengarkan permintaan maaf Anda yang membosankan dan memaafkan Anda atas semua yang telah Anda lakukan?",
  ui_story_5032_50320301_41_dialog_content = "Akankah memberi tahu saya secara pribadi betapa Anda menyesali semuanya itu sedikit meringankan hati nurani Anda?",
  ui_story_5032_50320301_42_dialog_content = "Jeno... Aku tahu betapa aku berhutang padamu.",
  ui_story_5032_50320301_43_dialog_content = "Tapi ada beberapa hal yang hanya bisa saya ceritakan kepada Anda.",
  ui_story_5032_50320301_44_dialog_content = "Hal-hal yang hanya akan signifikan bagi Anda.",
  ui_story_5032_50320301_45_dialog_content = "Saya tidak berharap apa pun yang Anda katakan menjadi signifikan.",
  ui_story_5032_50320301_46_dialog_content = "Lihatlah dirimu, Elvis. Kamu menyedihkan.",
  ui_story_5032_50320301_47_dialog_content = "Ya. Aku tahu seberapa jauh aku telah jatuh.",
  ui_story_5032_50320301_48_dialog_content = "Saya harus terlihat seperti yang saya lakukan <color=#FFB400>waktu itu kaki saya sakit</color>, melawan para preman itu.",
  ui_story_5032_50320301_49_dialog_content = "Saya ingat bagaimana Anda mengejek saya.",
  ui_story_5032_50320301_50_dialog_content = "Saya tidak datang ke sini untuk mengenang.",
  ui_story_5032_50320301_51_dialog_content = "Saya minta maaf. Saya pikir Anda pernah mengatakan bahwa Anda adalah orang yang bernostalgia ... Saya pikir Anda mungkin ingin mengingat masa lalu.",
  ui_story_5032_50320301_52_dialog_content = "Bagaimanapun, setiap orang memiliki rahasia kecil yang tersembunyi dalam ingatan mereka.",
  ui_story_5032_50320301_53_dialog_content = "Aku sedang tidak mood untuk mengingat masa lalu. Dan aku bahkan tidak ingat kau melukai kakimu.",
  ui_story_5032_50320301_54_dialog_content = "Tidak, Anda lakukan. Aku yakin kau melakukannya.",
  ui_story_5032_50320301_55_dialog_content = "Sama seperti Anda tahu arti rahasia.",
  ui_story_5032_50320301_56_dialog_content = "Omong kosong!",
  ui_story_5032_50320301_57_dialog_content = "Ini tidak ada gunanya. Jika hanya ini yang harus Anda katakan, simpan napas Anda. Saya tidak tertarik.",
  ui_story_5032_50320301_58_dialog_content = "Jeno!",
  ui_story_5032_50320301_59_dialog_content = "Jeno baru saja keluar seperti itu?",
  ui_story_5032_50320301_60_dialog_content = "Dia tampak marah...",
  ui_story_5032_50320301_61_dialog_content = "Saya tidak tahu sejarah di antara kalian berdua, tapi mungkin Anda harus mencoba permintaan maaf yang lebih tulus.",
  ui_story_5032_50320301_62_dialog_content = "Ngomong-ngomong, maukah kamu makan sesuatu, sekarang kami membiarkanmu melihat Jeno?",
  ui_story_5032_50320301_63_dialog_content = "Hmm. Terima kasih atas sarannya, PlayerName.",
  ui_story_5032_50320301_64_dialog_content = "Elvis! Apakah kamu baik-baik saja?",
  ui_story_5032_50320301_65_dialog_content = "Jangan khawatir. Ini hanya kakiku. Dan mereka tidak akan menggertak Anda seperti itu lagi.",
  ui_story_5032_50320301_66_dialog_content = "Maaf... Ini semua salahku.",
  ui_story_5032_50320301_67_dialog_content = "Aku bilang jangan khawatir tentang hal itu. Jadi apakah ini markas rahasia yang kamu temukan?",
  ui_story_5032_50320301_68_dialog_content = "Ya. Hampir tidak ada orang di sini dan itu sempurna untuk melukis.",
  ui_story_5032_50320301_69_dialog_content = "Ayo masuk kalau begitu! Itu bisa menjadi tempat yang keren untuk menyembunyikan sesuatu juga. Mungkin aku akan menyimpan buku harianku di sini.",
  ui_story_5032_50320301_70_dialog_content = "Eh? Aku tidak tahu kau punya buku harian.",
  ui_story_5032_50320301_71_dialog_content = "Ya, tapi mungkin aku akan memulainya.",
  ui_story_5032_50320301_72_dialog_content = "Bagaimanapun, pangkalan rahasia sangat cocok untuk menyimpan rahasia.",
  ui_story_5032_50320301_73_dialog_content = "<color=#e8d9bb>Pinggiran Kota Pelabuhan</color>",
  ui_story_5032_50320301_74_dialog_content = "Apa yang Anda tinggalkan di sini sehingga Anda sangat ingin saya temukan?",
  ui_story_5032_50320301_75_dialog_content = "Tentunya itu bukan buku harian bodoh itu...",
  ui_story_5032_50320301_76_dialog_content = "Graagh—!",
  ui_story_5032_50320301_77_dialog_content = "Saya tidak percaya ada Eclipsites di sini.",
  ui_story_5032_50320301_78_dialog_content = "Graagh!!",
  ui_story_5032_50320301_79_dialog_content = "Minggir!",
  ui_story_5032_50320302_1_dialog_content = "Graagh—",
  ui_story_5032_50320302_2_dialog_content = "Saya pikir itu yang terakhir.",
  ui_story_5032_50320302_3_dialog_content = "Pohon yang ditabrak Eclipsite adalah pohon yang sama yang Elvis sandarkan saat kakinya terluka.",
  ui_story_5032_50320302_4_dialog_content = "Itu tumbuh begitu tinggi.",
  ui_story_5032_50320302_5_dialog_content = "Benar-benar ada surat. Bagaimana klise.",
  ui_story_5032_50320302_6_dialog_content = "Dan apakah saya harus membacanya?",
  ui_story_5032_50320302_7_dialog_content = "Plot rahasia harus sedikit lebih kreatif dari ini.",
  ui_story_5032_50320302_8_dialog_content = "Aku harus menghancurkan rencana konyolmu ini...",
  ui_story_5032_50320302_9_dialog_content = "Tidak, mungkin aku harus membacanya. Ini mungkin memberikan tawa yang baik.",
  ui_story_5032_50320302_10_dialog_content = "Karena aku sudah memutuskan untuk tidak memaafkanmu, apa yang akan dilakukan surat untuk mengubahnya?",
  ui_story_5032_50320302_11_dialog_content = "Bahkan sekarang, Jeno, kamu masih ingin tahu alasan menyedihkan apa yang dia miliki, bukan?",
  ui_story_5032_50320302_12_dialog_content = "Kamu sama lucunya dengan dia.",
  ui_story_5032_50320302_13_dialog_content = "Sangat baik. Saya akan melihat apa lagi yang Anda katakan untuk diri sendiri.",
  ui_story_5032_50320302_14_dialog_content = "Untuk sahabatku Jeno",
  ui_story_5032_50320302_15_dialog_content = "Pada saat Anda membaca ini, saya mungkin telah membebaskan orang-orang Harbour City dari kutukan yang mereka derita.",
  ui_story_5032_50320302_16_dialog_content = "Atau, jika rencana saya gagal, saya mungkin telah menjadi tahanan.",
  ui_story_5032_50320302_17_dialog_content = "Tapi apapun masalahnya, saya sangat membutuhkan bantuan Anda.",
  ui_story_5032_50320302_18_dialog_content = "Aku mohon, baca surat ini sampai habis.",
  ui_story_5032_50320302_19_dialog_content = "Anda mungkin sudah tahu bahwa target saya adalah inti energi Zamrud.",
  ui_story_5032_50320302_20_dialog_content = "Saya telah bertanya pada diri sendiri berkali-kali apakah saya harus mengungkapkan rencana saya kepada Anda. Lagi pula, ada saat ketika kami tidak memiliki rahasia satu sama lain.",
  ui_story_5032_50320302_21_dialog_content = "Tapi setelah bertahun-tahun berpisah, kami berdua mungkin tumbuh menjadi orang yang sangat berbeda.",
  ui_story_5032_50320302_22_dialog_content = "Dan bertahun-tahun bermain game politik telah membuat saya waspada untuk mempercayai orang lain.",
  ui_story_5032_50320302_23_dialog_content = "Bahkan ketika kita bertemu sekali lagi, aku masih belum bisa mempercayaimu sepenuhnya.",
  ui_story_5032_50320302_24_dialog_content = "Saat itulah saya melihatnya di mata Anda — Zamrud lebih dari sekadar kapal bagi Anda.",
  ui_story_5032_50320302_25_dialog_content = "Ini telah menjadi rumah. Rumah untuk Anda, untuk keluarga Anda, dan untuk teman-teman Anda.",
  ui_story_5032_50320302_26_dialog_content = "Dan Anda telah menjadi anggota True Order.",
  ui_story_5032_50320302_27_dialog_content = "Saya tidak bisa mengatakan yang sebenarnya, atau menanggung konsekuensinya jika kekuatan lain belajar tentang inti energi.",
  ui_story_5032_50320302_28_dialog_content = "Ini adalah harapan terakhir bagi Harbour City dan jiwa-jiwa terkutuk yang malang yang tinggal di sini.",
  ui_story_5032_50320302_29_dialog_content = "Itu <color=#FFB400>Batu angin</color>segelnya melemah. Jika itu terus berlanjut, Harbour City akan hancur.",
  ui_story_5032_50320302_30_dialog_content = "Saya membutuhkan bantuan Anda dan saya berjanji untuk menjelaskan semuanya secara langsung. Tapi aku harus menyelesaikan ritualnya secepat mungkin.",
  ui_story_5032_50320302_31_dialog_content = "Saya harap Anda akan membantu tempat ini, bekas rumah Anda. Dan aku, mantan temanmu.",
  ui_story_5032_50320302_32_dialog_content = "Apakah ini yang ingin Anda katakan?",
  ui_story_5032_50320302_33_dialog_content = "Anda pikir Anda bisa membodohi saya lagi hanya dengan surat?",
  ui_story_5032_50320302_34_dialog_content = "Apakah Anda pikir saya akan memaafkan Anda sekarang?",
  ui_story_5032_50320302_35_dialog_content = "<color=#e8d9bb>Tzzst—</color>",
  ui_story_5032_50320302_36_dialog_content = "Dasar bodoh, Elvis.",
  ui_story_5032_50320401_1_dialog_content = "Carleen, kami kembali.",
  ui_story_5032_50320401_2_dialog_content = "Selamat datang kembali. Bagaimana hasilnya?",
  ui_story_5032_50320401_3_dialog_content = "Dan dimana Jeno? Aku pikir dia akan bersamamu.",
  ui_story_5032_50320401_4_dialog_content = "Dia bertarung dengan Elvis dan kemudian pergi. Kami tidak bisa menghentikannya.",
  ui_story_5032_50320401_5_dialog_content = "Dikira sebanyak. Dia pasti sedang banyak pikiran sekarang...",
  ui_story_5032_50320401_6_dialog_content = "Setelah semua yang terjadi, dia mungkin perlu waktu sendiri untuk memikirkan semuanya.",
  ui_story_5032_50320401_7_dialog_content = "Kita harus memberinya ruang itu.",
  ui_story_5032_50320401_8_dialog_content = "Saya masih berpikir Elvis menyembunyikan sesuatu yang penting dari kami.",
  ui_story_5032_50320401_9_dialog_content = "Tapi kita tidak tahu apa yang terjadi di dalam kepalanya.",
  ui_story_5032_50320401_10_dialog_content = "Ya...",
  ui_story_5032_50320401_11_dialog_content = "Carleen, apakah Anda punya ide?",
  ui_story_5032_50320401_12_dialog_content = "Hal terpenting saat ini adalah mencari tahu apa yang Elvis lakukan, dan mengapa Eclipsites mulai muncul.",
  ui_story_5032_50320401_13_dialog_content = "Ini tebakannya. Peningkatan Eclipsites mungkin terkait dengan segel yang disebutkan Elvis.",
  ui_story_5032_50320401_14_dialog_content = "Yah, karena dia tidak akan memberi tahu kita apa pun, kita harus mencari cara lain untuk menyelesaikan ini.",
  ui_story_5032_50320401_15_dialog_content = "Tapi di mana kita mulai?",
  ui_story_5032_50320401_16_dialog_content = "Aku ingat sesuatu yang Elvis pernah katakan—",
  ui_story_5032_50320401_17_dialog_content = "Anda akan menemukan informasi yang Anda butuhkan juga, setelah Anda membaca setiap buku di dunia ini.",
  ui_story_5032_50320401_18_dialog_content = "Jadi apa yang harus kita lakukan? Baca semua buku di Astra?",
  ui_story_5032_50320401_19_dialog_content = "Tidak. Hanya semua buku yang pernah dibaca Elvis.",
  ui_story_5032_50320401_20_dialog_content = "Saya ingat ada perpustakaan kecil di rumahnya. Kita harus dapat menemukan beberapa petunjuk di sana.",
  ui_story_5032_50320401_21_dialog_content = "Aku akan datang dan membantu. Sepasang mata ekstra akan mempercepat segalanya.",
  ui_story_5032_50320401_22_dialog_content = "Iya, aku juga.",
  ui_story_5032_50320401_23_dialog_content = "<color=#e8d9bb>Perpustakaan, rumah besar Elvis</color>",
  ui_story_5032_50320401_24_dialog_content = "Kamu... Kamu menyebut ini perpustakaan kecil!?",
  ui_story_5032_50320401_25_dialog_content = "Maksudku, ruangannya tidak terlalu besar...",
  ui_story_5032_50320401_26_dialog_content = "Tapi itu penuh dengan rak buku. Dan rak buku penuh dengan buku.",
  ui_story_5032_50320401_27_dialog_content = "Ini akan membawa kita satu tahun untuk membaca semua ini. Tidak, minimal dua tahun!",
  ui_story_5032_50320401_28_dialog_content = "Dan lihat, semua buku berantakan. Elvis pasti sudah membacanya berulang-ulang.",
  ui_story_5032_50320401_29_dialog_content = "Apa yang dia harapkan untuk dipelajari dari ini?",
  ui_story_5032_50320401_30_option_content = "Mungkin dia sedang belajar sejarah?",
  ui_story_5032_50320401_31_dialog_content = "Elvis ingin menyembuhkan Sindrom Modali, jadi dia mungkin mencari petunjuk tentang Garis Darah Pahlawan.",
  ui_story_5032_50320401_32_dialog_content = "Garis Darah Pahlawan memiliki akar yang dalam dalam sejarah Harbour City.",
  ui_story_5032_50320401_33_dialog_content = "Jika saya ingin belajar tentang Sindrom Modali, saya akan mulai dengan sejarah Harbour City.",
  ui_story_5032_50320401_34_dialog_content = "Itu benar. Ini adalah sejarah yang penuh dengan misteri yang belum terpecahkan.",
  ui_story_5032_50320401_35_dialog_content = "Mungkin salah satu misteri itu ada hubungannya dengan Sindrom Modali?",
  ui_story_5032_50320401_36_option_content = "Mungkin dia sedang meneliti Sindrom Modali?",
  ui_story_5032_50320401_37_dialog_content = "Dia lebih peduli tentang itu daripada apa pun, bukan?",
  ui_story_5032_50320401_38_dialog_content = "Penyakit yang dia, serta siapa yang tahu berapa banyak warga Harbour City, menderita.",
  ui_story_5032_50320401_39_dialog_content = "Tetapi para ahli telah mencoba mencari tahu apa penyebabnya selama berabad-abad dan masih belum berhasil.",
  ui_story_5032_50320401_40_dialog_content = "Di mana Elvis akan mulai mencari?",
  ui_story_5032_50320401_41_dialog_content = "Nah, itu penyakit lokal. Jadi pendekatan terbaik mungkin dengan melihat sejarah lokal.",
  ui_story_5032_50320401_42_dialog_content = "Kalau begitu mari kita mulai dengan buku-buku sejarah.",
  ui_story_5032_50320401_43_dialog_content = "Oke. Aku akan mengumpulkan semua buku sejarah, dan kalian bisa mulai membacanya!",
  ui_story_5032_50320401_44_dialog_content = "Serahkan pada kami!",
  ui_story_5032_50320401_45_dialog_content = "The Chronicles of Astra, The Encyclopedia of History, The Secret History of Lumopolis...",
  ui_story_5032_50320401_46_dialog_content = "Hah? Dan mengapa ada salinan Pahlawan Legendaris Kota Pelabuhan di rak sejarah?",
  ui_story_5032_50320401_47_dialog_content = "Bukankah ini lebih dari sebuah buku mitologi? Apapun, aku akan membawanya.",
  ui_story_5032_50320401_48_dialog_content = "Vice, Carleen, ini buku-bukunya.",
  ui_story_5032_50320401_49_dialog_content = "Oke, letakkan di sini dan kita akan mulai membaca.",
  ui_story_5032_50320401_50_dialog_content = "Terima kasih, PlayerName.",
  ui_story_5032_50320401_51_dialog_content = "Tidak masalah. Saya pikir ada beberapa buku sejarah lagi di sana. Aku akan pergi dan memeriksa.",
  ui_story_5032_50320401_52_dialog_content = "<color=#e8d9bb>Beberapa waktu kemudian</color>",
  ui_story_5032_50320401_53_dialog_content = "Fiuh. Oke, ini semua buku dengan kata \"sejarah\" di judulnya dan apa saja yang terlihat... kau tahu, sejarah.",
  ui_story_5032_50320401_54_dialog_content = "Bagaimana jalannya? Sudah menemukan sesuatu?",
  ui_story_5032_50320401_55_dialog_content = "Ada yang aneh dengan buku-buku ini. Yang tentang Harbour City semuanya setuju dengan sejarah awalnya.",
  ui_story_5032_50320401_56_dialog_content = "Tetapi segera setelah kita membaca bagian-bagian yang lebih baru, semuanya berbeda.",
  ui_story_5032_50320401_57_dialog_content = "Dan itu bahkan tidak dibaca seperti sejarah. Ini lebih seperti cerita yang dibuat-buat.",
  ui_story_5032_50320401_58_dialog_content = "Ya. Seperti yang ini, The Chronicles of Astra, mengatakan ini:",
  ui_story_5032_50320401_59_dialog_content = "\"Pernah ada pertempuran berdarah antara para pahlawan kuno dan Eclipsites di dekat Harbour City.\"",
  ui_story_5032_50320401_60_dialog_content = "\"Roh-roh kebencian dari Eclipsites menjadi kutukan yang menyiksa keturunan para pahlawan.\"",
  ui_story_5032_50320401_61_dialog_content = "Bukankah itu legenda yang kita dengar pada awalnya?",
  ui_story_5032_50320401_62_dialog_content = "Tapi itu hanya legenda, kan? Jika kutukan benar-benar ada, seluruh dunia akan jatuh ke dalam kekacauan...",
  ui_story_5032_50320401_63_dialog_content = "Yang itu setidaknya terdengar setengah bisa dipercaya. Yang ini, The Legendary Heroes of Harbour City, bahkan lebih aneh lagi.",
  ui_story_5032_50320401_64_dialog_content = "\"Harbour City dilindungi oleh para pahlawan zaman dulu dan tidak diganggu oleh Eclipsites.\"",
  ui_story_5032_50320401_65_dialog_content = "\"Meskipun Eclipsites mungkin mendekati kota, mereka segera diam-diam dibuang oleh para pahlawan.\"",
  ui_story_5032_50320401_66_dialog_content = "Itu aneh!",
  ui_story_5032_50320401_67_dialog_content = "Ya, 'kan?!",
  ui_story_5032_50320401_68_dialog_content = "Eh? Buku ini mengatakan...",
  ui_story_5032_50320401_69_dialog_content = "Vice, apa yang kamu punya?",
  ui_story_5032_50320401_70_dialog_content = "Ini Sejarah Rahasia Lumopolis. Dikatakan penduduk Harbour City pernah menggali situs reruntuhan kuno.",
  ui_story_5032_50320401_71_dialog_content = "Dan di reruntuhan, mereka menemukan batu aneh. Dan jika batu itu diresapi dengan Lumina, itu bisa <color=#FFB400>tolak Eclipsites terdekat</color>.",
  ui_story_5032_50320401_72_dialog_content = "Itu terdengar akrab. Itu akan seperti versi miniatur dari penghalang Lumopolis.",
  ui_story_5032_50320401_73_dialog_content = "Jangan mengganggu, PlayerName. saya belum selesai.",
  ui_story_5032_50320401_74_dialog_content = "Oh maaf. Apa yang terjadi selanjutnya?",
  ui_story_5032_50320401_75_dialog_content = "Inilah yang dikatakan—",
  ui_story_5032_50320401_76_dialog_content = "\"Tapi seperti yang dibutuhkan batu <color=#FFB400>terlalu banyak Lumina</color> berfungsi, tidak ada sumber yang bisa membuatnya terus berjalan.\"",
  ui_story_5032_50320401_77_dialog_content = "\"Jadi itu dianggap tidak berharga dan kemudian hilang.\"",
  ui_story_5032_50320401_78_dialog_content = "Kedengarannya seperti legenda yang tidak berguna. Tetap mencari.",
  ui_story_5032_50320401_79_dialog_content = "Meskipun... Kekuatan yang mengusir Eclipsites? Itu mengingatkan saya pada sesuatu yang saya baca di sebuah buku di Lumopolis.",
  ui_story_5032_50320401_80_dialog_content = "Di beberapa titik di masa lalu, segerombolan Eclipsites berkumpul di area Harbour City. Penduduk berjuang dan menderita selama bertahun-tahun.",
  ui_story_5032_50320401_81_dialog_content = "Kemudian suatu hari, Eclipsites tiba-tiba menghilang begitu saja dan kota itu bebas makmur.",
  ui_story_5032_50320401_82_dialog_content = "Lalu apa yang membuat mereka menghilang?",
  ui_story_5032_50320401_83_dialog_content = "Tidak ada ide. Saya kira itu hanya salah satu misteri Harbour City yang belum terpecahkan.",
  ui_story_5032_50320401_84_dialog_content = "Aduh, leherku. Saya telah membaca begitu lama, itu menjadi kaku.",
  ui_story_5032_50320401_85_dialog_content = "Istirahat. Saya akan membacakan sisanya untuk Anda.",
  ui_story_5032_50320401_86_dialog_content = "Oh terima kasih, PlayerName.",
  ui_story_5032_50320401_87_dialog_content = "Saya akan tidur siang dengan buku ini cas—woah!!",
  ui_story_5032_50320401_88_dialog_content = "Apa yang salah? Apakah Anda menabrak sesuatu?",
  ui_story_5032_50320401_89_dialog_content = "T-tidak. Saya tidak sengaja mendorong salah satu buku ini.",
  ui_story_5032_50320401_90_dialog_content = "Itu gempa, ya?",
  ui_story_5032_50320401_91_dialog_content = "Bukan.",
  ui_story_5032_50320401_92_dialog_content = "Lihat, itu tembok di sana. Ini bergerak!",
  ui_story_5032_50320401_93_dialog_content = "Dan lihat, ada sesuatu di balik dinding. Nya...",
  ui_story_5032_50320401_94_dialog_content = "Sebuah meja, ditumpuk dengan dokumen tulisan tangan?",
  ui_story_5032_50320401_95_dialog_content = "Jika Elvis menyembunyikan ini dengan sangat hati-hati, itu pasti penting.",
  ui_story_5032_50320401_96_dialog_content = "Dan kami tidak akan pernah menemukan ruang rahasia jika bukan karena keberuntungan Vice.",
  ui_story_5032_50320401_97_dialog_content = "Mari kita lihat apa yang dikatakan dokumen-dokumen ini.",
  ui_story_5032_50320401_98_dialog_content = "Halaman di atas sudah menguning. Mereka pasti lebih tua.",
  ui_story_5032_50320401_99_dialog_content = "Dengan ini saya memulai penelitian saya tentang Windstone. Tidak hanya untuk diri saya sendiri tetapi untuk masa depan warga Harbour City.",
  ui_story_5032_50320401_100_dialog_content = "Itu tulisan tangan Elvis. Dia benar-benar melakukan penelitian rahasia. Tapi apa Batu Angin itu?",
  ui_story_5032_50320401_101_dialog_content = "Aku tidak tahu. Tetapi jika dia mempelajarinya, harus ada informasi lebih lanjut nanti!",
  ui_story_5032_50320401_102_dialog_content = "Penelitian saya menemukan bahwa Windstone berisi perangkat yang dapat menyimpan energi.",
  ui_story_5032_50320401_103_dialog_content = "Cadangan energinya dan pasokan Lumina yang terputus-putus dari Auroria telah berhasil membuatnya tetap beroperasi hingga saat ini.",
  ui_story_5032_50320401_104_dialog_content = "Tetapi ia mengkonsumsi lebih banyak energi daripada yang dapat dipasok, dan cadangan energinya hampir habis.",
  ui_story_5032_50320401_105_dialog_content = "Aku bisa merasakan kekuatan Windstone melemah, dan kami mulai melihat Eclipsites muncul di dekat Harbour City.",
  ui_story_5032_50320401_106_dialog_content = "Jika ini terus berlanjut, tidak lama lagi kota ini akan kembali diganggu oleh Eclipsites.",
  ui_story_5032_50320401_107_dialog_content = "Waktu terus berjalan. Aku harus memikirkan sesuatu.",
  ui_story_5032_50320401_108_dialog_content = "Jadi sepertinya Windstone adalah semacam peralatan dengan kekuatan khusus.",
  ui_story_5032_50320401_109_dialog_content = "Jadi mungkinkah ini sebabnya Harbour City aman dari Eclipsites begitu lama?",
  ui_story_5032_50320401_110_dialog_content = "Apa yang dijelaskan di sini tentu cocok dengan situasi sebenarnya di Harbour City.",
  ui_story_5032_50320401_111_dialog_content = "Di masa lalu, tidak ada Eclipsites yang pernah menginjakkan kaki di Harbour City. Namun baru-baru ini, ada banyak laporan tentang Eclipsites yang menyerang Aurorian.",
  ui_story_5032_50320401_112_dialog_content = "Apakah melemahnya apa yang disebut Windstone adalah penyebabnya, fenomena ini bukanlah pertanda baik.",
  ui_story_5032_50320401_113_dialog_content = "Mari terus membaca. Makalah di bawah ini tampak lebih baru, jadi penulisannya harus lebih baru.",
  ui_story_5032_50320401_114_dialog_content = "Saya membolak-balik semua buku sejarah yang bisa saya temukan, mencari asal-usul Batu Angin.",
  ui_story_5032_50320401_115_dialog_content = "Nenek moyang saya menggali Windstone di reruntuhan dan menemukan bahwa itu memiliki kekuatan besar, cukup untuk menyegel Eclipsites.",
  ui_story_5032_50320401_116_dialog_content = "Untuk melindungi tanah air, mereka membuat perjanjian darah dengan Windstone dan memasok Lumina yang dibutuhkan untuk beroperasi.",
  ui_story_5032_50320401_117_dialog_content = "Dan dengan demikian, kekuatan Windstone membuat Eclipsites yang mengganggu Harbour City tertidur lelap.",
  ui_story_5032_50320401_118_dialog_content = "Tetapi jika Windstone berhenti bekerja, Eclipsites akan bangun dan menjarah Harbour City lagi.",
  ui_story_5032_50320401_119_dialog_content = "Segel dan perjanjian darah... Kedengarannya seperti kekuatan yang disebutkan dalam buku itu.",
  ui_story_5032_50320401_120_dialog_content = "Bukankah itu rumor yang tidak berdasar?",
  ui_story_5032_50320401_121_dialog_content = "Dan konon, Windstone membutuhkan Lumina besar untuk bekerja, jadi mereka menyerah.",
  ui_story_5032_50320401_122_dialog_content = "Mari kita pergi ke depan.",
  ui_story_5032_50320401_123_dialog_content = "Penelitian itu akhirnya membuat kemajuan.",
  ui_story_5032_50320401_124_dialog_content = "Windstone mampu mengidentifikasi kontraktor dan kerabat darah mereka, serta secara otomatis menyerap Lumina dari Aurorian tersebut.",
  ui_story_5032_50320401_125_dialog_content = "Sekarang batu itu hampir habis, ia mulai menyerap Lumina tanpa menahan diri.",
  ui_story_5032_50320401_126_dialog_content = "Tetapi bahkan jika itu bisa mengambil segalanya dari para Aurorian itu, Lumina tetap tidak akan cukup.",
  ui_story_5032_50320401_127_dialog_content = "Ketika persediaan akhirnya habis, setiap Aurorian yang lahir dari garis keturunan itu akan mati karena kehilangan Lumina.",
  ui_story_5032_50320401_128_dialog_content = "Eh... Jangan bilang...",
  ui_story_5032_50320401_129_dialog_content = "Itu mungkin akar dari Sindrom Modali.",
  ui_story_5032_50320401_130_dialog_content = "Elvis... dan klannya menggunakan Lumina mereka dan bahkan hidup untuk menyalakan Windstone.",
  ui_story_5032_50320401_131_dialog_content = "Tapi kenapa? Apakah tidak ada cara yang lebih baik?",
  ui_story_5032_50320401_132_dialog_content = "Elvis tidak pernah melaporkannya ke Lumopolis sebagai laird of Harbour City.",
  ui_story_5032_50320401_133_dialog_content = "Mengapa dia melakukan itu?",
  ui_story_5032_50320401_134_dialog_content = "Windstone semakin lemah. Lebih buruk lagi, Lumopolis telah meluncurkan penyelidikan rahasia Harbour City.",
  ui_story_5032_50320401_135_dialog_content = "Windstone mungkin hanya mainan yang menarik bagi bangsawan Lumo.",
  ui_story_5032_50320401_136_dialog_content = "Hal yang sama berlaku untuk para ilmuwan di Illumina. Begitu keberadaan Windstone diketahui, mereka pasti akan mengirim orang untuk merebutnya.",
  ui_story_5032_50320401_137_dialog_content = "Bagi Harbour City, batu adalah fondasi keberadaannya, hal penting yang mencegah orang terlantar.",
  ui_story_5032_50320401_138_dialog_content = "Saya harus menyimpannya di tempat yang benar-benar aman dan tidak terduga sehingga orang luar tidak akan mengetahuinya.",
  ui_story_5032_50320401_139_dialog_content = "Kabar baiknya adalah bahwa ada terobosan dalam penelitian ini.",
  ui_story_5032_50320401_140_dialog_content = "Setelah kegagalan yang tak terhitung jumlahnya, saya akhirnya menemukan cara agar batu itu ditenagai oleh sumber lain.",
  ui_story_5032_50320401_141_dialog_content = "Yang tersisa sekarang adalah pergi ke tanah tertutup untuk memulai kembali.",
  ui_story_5032_50320401_142_dialog_content = "Itu bagian terakhir, ditulis dengan terburu-buru.",
  ui_story_5032_50320401_143_dialog_content = "Di suatu tempat yang benar-benar aman... Bisakah batu aneh di tongkat kerajaan Elvis itu adalah Windstone yang sebenarnya?",
  ui_story_5032_50320401_144_dialog_content = "Apakah Lumopolis tidak bisa dipercaya untukmu, Elvis?",
  ui_story_5032_50320401_145_dialog_content = "Carleen…",
  ui_story_5032_50320401_146_dialog_content = "Jelaskan kepada Elvis ketika Anda mendapat kesempatan.",
  ui_story_5032_50320401_147_dialog_content = "Vice dan saya bisa membuktikan bahwa Anda adalah orang yang dapat dipercaya!",
  ui_story_5032_50320401_148_dialog_content = "Baiklah... Terima kasih.",
  ui_story_5032_50320401_149_dialog_content = "Naskah berakhir dengan Elvis mengatakan dia menemukan cara bagi Windstone untuk menggunakan sumber daya lain.",
  ui_story_5032_50320401_150_dialog_content = "Windstone, Lumina, energi besar...",
  ui_story_5032_50320401_151_dialog_content = "Saya mendapatkannya. Dia ingin inti energi di kapal sirkus memberi daya pada batu itu.",
  ui_story_5032_50320401_152_dialog_content = "Itu sebabnya dia mencari inti bahkan dengan biaya putus dengan teman ...",
  ui_story_5032_50320401_153_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5032_50320401_154_dialog_content = "Cepat, di sana!",
  ui_story_5032_50320401_155_dialog_content = "Apa yang sedang terjadi? Mengapa semua kebisingan?",
  ui_story_5032_50320401_156_dialog_content = "Hentikan pria itu! Dia keluar dari penjara!",
  ui_story_5032_50320401_157_dialog_content = "Sebuah istirahat penjara?!",
  ui_story_5032_50320401_158_dialog_content = "Jangan bilang itu Elvis?!",
  ui_story_5032_50320401_159_dialog_content = "Yuk, cek!",
  ui_story_5032_50320501_1_dialog_content = "Tolong perhatikan tersangka.",
  ui_story_5032_50320501_2_dialog_content = "Saya harus pergi selama setengah jam.",
  ui_story_5032_50320501_3_dialog_content = "Mandi lagi?",
  ui_story_5032_50320501_4_dialog_content = "Harbour City sangat lembab dan pengap sekarang.",
  ui_story_5032_50320501_5_dialog_content = "Anda akan berkeringat lengket setelah mandi.",
  ui_story_5032_50320501_6_dialog_content = "Keempat kalinya? Untuk hari ini?",
  ui_story_5032_50320501_7_dialog_content = "Saya tidak keberatan Anda mengambil satu dan menambahkannya ke hitungan saya.",
  ui_story_5032_50320501_8_dialog_content = "Saya seorang asisten hakim.",
  ui_story_5032_50320501_9_dialog_content = "Tidak tidak. Secara teknis, Anda adalah asisten hakim yang agak bau.",
  ui_story_5032_50320501_10_dialog_content = "!!",
  ui_story_5032_50320501_11_dialog_content = "Hah? Apakah Anda bingung?",
  ui_story_5032_50320501_12_dialog_content = "Sudahlah. Saya mandi apakah Anda suka atau tidak.",
  ui_story_5032_50320501_13_dialog_content = "Jauhkan mata Anda terpaku pada sarang.",
  ui_story_5032_50320501_14_dialog_content = "Namun itu mungkin diperdebatkan. Dia bahkan memiliki masalah berdiri tanpa tongkatnya.",
  ui_story_5032_50320501_15_dialog_content = "Siapa tahu dia bisa sampai ke pengadilan ...",
  ui_story_5032_50320501_16_dialog_content = "...",
  ui_story_5032_50320501_17_dialog_content = "Akankah Jeno mengambil surat yang kutinggalkan untuknya?",
  ui_story_5032_50320501_18_dialog_content = "Atau tidak sama sekali, atau mungkin masih tidak akan memaafkan saya setelah membacanya.",
  ui_story_5032_50320501_19_dialog_content = "Aku tahu aku terus mengkhianati kepercayaanmu, jadi aku tidak perlu berharap.",
  ui_story_5032_50320501_20_dialog_content = "Maaf, Jeno... Tapi hanya kau yang bisa membantu orang-orang Harbour City dan aku.",
  ui_story_5032_50320501_21_dialog_content = "<color=#e8d9bb>Klik.</color>",
  ui_story_5032_50320501_22_dialog_content = "Anda selesai bergumam?",
  ui_story_5032_50320501_23_dialog_content = "Kalau begitu, ikut aku.",
  ui_story_5032_50320501_24_dialog_content = "Jeno!",
  ui_story_5032_50320501_25_dialog_content = "Jangan terlalu bersemangat di sana.",
  ui_story_5032_50320501_26_dialog_content = "Anda harus memberi tahu saya semuanya, ditambah apa yang Anda rencanakan selanjutnya.",
  ui_story_5032_50320501_27_dialog_content = "Atau aku akan melemparkanmu kembali ke sini sendiri.",
  ui_story_5032_50320501_28_dialog_content = "...",
  ui_story_5032_50320501_29_dialog_content = "Mengapa para penjaga tidak menyerang atau membunyikan alarm?",
  ui_story_5032_50320501_30_dialog_content = "Mereka bahkan tidak melihat kita, seperti tidak terjadi apa-apa.",
  ui_story_5032_50320501_31_dialog_content = "Begitulah kekuatan Origin Deck. Itu membuat mereka berhalusinasi.",
  ui_story_5032_50320501_32_dialog_content = "Tetapi para penjaga tetap terlalu berpuas diri, dan itu memberi saya celah.",
  ui_story_5032_50320501_33_dialog_content = "Hanya juri dari Lumopolis yang membuatku bekerja sedikit.",
  ui_story_5032_50320501_34_dialog_content = "Saya kira mereka tidak mengharapkan siapa pun untuk menghancurkan Anda.",
  ui_story_5032_50320501_35_dialog_content = "Haha, sayang sekali mereka salah.",
  ui_story_5032_50320501_36_dialog_content = "Halusinasi, katamu. Jadi hal menarik apa lagi yang bisa kamu lakukan dengan kekuatan \"Origin\"?",
  ui_story_5032_50320501_37_dialog_content = "Berhenti membuatku kesal. Aku masih ingin penjelasan darimu.",
  ui_story_5032_50320501_38_dialog_content = "Aku bahkan belum yakin akan memaafkanmu.",
  ui_story_5032_50320501_39_dialog_content = "Tapi dari apa yang dikatakan Lady Victoria...",
  ui_story_5032_50320501_40_dialog_content = "Origin Deck serba guna dalam hal <color=#FFB400>konversi energi</color>.",
  ui_story_5032_50320501_41_dialog_content = "Saya belum menguasai banyak kegunaan. Ini benar-benar alat yang bagus untuk pesulap.",
  ui_story_5032_50320501_42_dialog_content = "Tetapi para penjaga akan segera keluar dari situ dan menyadari bahwa Anda telah pergi.",
  ui_story_5032_50320501_43_dialog_content = "Sangat menarik. Saya benar-benar ingin melihat pertunjukan kapan-kapan.",
  ui_story_5032_50320501_44_dialog_content = "Cukup yakin saya akan mendapatkan kesempatan di masa depan.",
  ui_story_5032_50320501_45_dialog_content = "Yakinlah, saya telah memutuskan untuk berterus terang kepada Anda.",
  ui_story_5032_50320501_46_dialog_content = "Hanya mengetahui bahwa saya tidak perlu menyembunyikan apa pun ketika saya berbicara dengan Anda mulai sekarang membuat saya sangat bahagia.",
  ui_story_5032_50320501_47_dialog_content = "Anda harus tahu bahwa Anda masih laird dan kami memiliki kekacauan besar untuk dibersihkan.",
  ui_story_5032_50320501_48_dialog_content = "Jadi berhentilah mencoba memecahkan masalah dengan paksa seperti ketika Anda masih kecil.",
  ui_story_5032_50320501_49_dialog_content = "Tentu saja. Aku sudah bilang aku akan memberitahumu semuanya!",
  ui_story_5032_50320501_50_dialog_content = "Hai! Bangun, Loew!",
  ui_story_5032_50320501_51_dialog_content = "Huh, dia tidak bangun.",
  ui_story_5032_50320501_52_dialog_content = "Elvis Jahat... Badut Jeno itu pasti yang melakukan ini!",
  ui_story_5032_50320501_53_dialog_content = "Mempermalukanku seperti ini... Tidak akan bisa lolos bahkan jika kamu adalah laird!",
  ui_story_5032_50320501_54_dialog_content = "Aku akan menangkapnya dan kemudian mencabik-cabiknya.",
  ui_story_5032_50320501_55_dialog_content = "Lalu bersihkan sepatuku dengan wajahnya yang menyebalkan itu!",
  ui_story_5032_50320501_56_dialog_content = "Semua penjaga, jemput Loewe dan ikut denganku untuk memburu buronan!",
  ui_story_5032_50320501_57_dialog_content = "Siap, Pak!",
  ui_story_5032_50320501_58_dialog_content = "Hakim Mattieu!",
  ui_story_5032_50320501_59_dialog_content = "Ada apa?",
  ui_story_5032_50320501_60_dialog_content = "Apa yang terjadi, Anda bertanya?",
  ui_story_5032_50320501_61_dialog_content = "Tidak menghukum penjahat tetapi memperlakukannya seperti tamu terhormat.",
  ui_story_5032_50320501_62_dialog_content = "Apakah ada yang lebih buruk daripada membiarkannya melarikan diri?",
  ui_story_5032_50320501_63_dialog_content = "Anda mengatakan...",
  ui_story_5032_50320501_64_dialog_content = "Ya, Elvis melarikan diri.",
  ui_story_5032_50320501_65_dialog_content = "Dan kemungkinan besar Jeno membantu!",
  ui_story_5032_50320501_66_dialog_content = "Saya mengingatkan Anda, Yang Mulia, untuk memindahkan penjahat ke Lumopolis sesegera mungkin.",
  ui_story_5032_50320501_67_dialog_content = "Permisi, tapi kita punya buronan untuk ditangkap, jadi tolong menjauhlah dariku!",
  ui_story_5032_50320501_68_dialog_content = "Hakim Matthieu tampak marah.",
  ui_story_5032_50320501_69_dialog_content = "Itu bisa dimengerti. Dia juga mengambil banyak tanggung jawab untuk mendukung penyelidikanku terhadap Elvis.",
  ui_story_5032_50320501_70_dialog_content = "Kita harus bertindak sekarang dan menangkap Elvis.",
  ui_story_5032_50320501_71_dialog_content = "Dari petunjuk yang kami miliki, Elvis harus mencari untuk memulai kembali Windstone.",
  ui_story_5032_50320501_72_dialog_content = "Ya, karena itulah mengapa dia mengejar inti energi sebelum dia digagalkan.",
  ui_story_5032_50320501_73_dialog_content = "Sekarang dia bebas, dia harus menuju ke tanah tertutup.",
  ui_story_5032_50320501_74_dialog_content = "Itu tidak pasti, dia bisa bersembunyi karena dia pikir kita tahu tentang rencananya.",
  ui_story_5032_50320501_75_dialog_content = "Bagaimanapun, kita harus pergi ke sana juga.",
  ui_story_5032_50320501_76_dialog_content = "Apakah Anda siap untuk ini, Carleen?",
  ui_story_5032_50320501_77_dialog_content = "Aku baik-baik saja, jangan khawatir.",
  ui_story_5032_50320501_78_dialog_content = "Belum lagi kami punya hal-hal untuk diberitahukan kepadanya secara langsung.",
  ui_story_5032_50320502_1_dialog_content = "Awas!",
  ui_story_5032_50320502_2_dialog_content = "Graaah!",
  ui_story_5032_50320502_3_dialog_content = "Kami mendapat lebih banyak Eclipsites dari sebelumnya.",
  ui_story_5032_50320502_4_dialog_content = "Padahal kita tidak terlalu jauh dari Harbour City.",
  ui_story_5032_50320502_5_dialog_content = "Eclipsites ini... Mungkinkah Windstone melemah?",
  ui_story_5032_50320502_6_dialog_content = "Fokus! Kita hampir sampai <color=#FFB400>tanah tertutup</color> ditandai dalam catatan Elvis!",
  ui_story_5032_50320502_7_dialog_content = "Siap!",
  ui_story_5032_50320502_8_dialog_content = "Semua misteri akan terpecahkan di sana.",
  ui_story_5032_50320502_9_dialog_content = "Diakah itu?",
  ui_story_5032_50320502_10_dialog_content = "Ya. Nenek moyang memulai Windstone di sini untuk menyegel Eclipsites.",
  ui_story_5032_50320502_11_dialog_content = "Saya yakin tentang memulai ulang batu melalui perangkat di sini.",
  ui_story_5032_50320502_12_dialog_content = "Tapi saya tidak akan diganggu selama proses berlangsung, jadi saya butuh bantuan Anda.",
  ui_story_5032_50320502_13_dialog_content = "Aku paham.",
  ui_story_5032_50320502_14_dialog_content = "Saya percaya Anda melakukan ini untuk kebaikan orang-orang di Harbour City, untuk saat ini.",
  ui_story_5032_50320502_15_dialog_content = "<size=30>Setidaknya itu sesuai dengan apa yang selalu kupikirkan tentangmu dalam pikiranku.</size>",
  ui_story_5032_50320502_16_dialog_content = "Apa itu, Jeno?",
  ui_story_5032_50320502_17_dialog_content = "Tidak ada apa-apa. Jika apa yang Anda katakan itu benar, saya akan membantu demi Anda dan Harbour City.",
  ui_story_5032_50320502_18_dialog_content = "Aku tidak menyembunyikan apapun darimu sekarang, jadi percayalah padaku, Jeno.",
  ui_story_5032_50320502_19_dialog_content = "Juga, terima kasih, Jeno.",
  ui_story_5032_50320502_20_dialog_content = "Elvis! Jeno!",
  ui_story_5032_50320502_21_dialog_content = "Itu dia, Yang Mulia.",
  ui_story_5032_50320502_22_dialog_content = "Lagipula, kamu memang datang ke sini, Elvis.",
  ui_story_5032_50320502_23_dialog_content = "Saya melihat Vice dan PlayerName telah datang juga, semua wajah yang akrab dan meyakinkan.",
  ui_story_5032_50320502_24_dialog_content = "Anda tidak harus bergerak dalam kondisi Anda, Elvis.",
  ui_story_5032_50320502_25_dialog_content = "Saya tahu itu, Nona Vice. Saya menghargai perhatian Anda untuk penjahat seperti saya.",
  ui_story_5032_50320502_26_dialog_content = "Tapi saya punya sesuatu yang harus saya lakukan.",
  ui_story_5032_50320502_27_dialog_content = "Karena Anda di sini, saya kira Anda telah membaca catatan saya di perpustakaan.",
  ui_story_5032_50320502_28_dialog_content = "Ya.",
  ui_story_5032_50320502_29_dialog_content = "Kami tahu niat Anda untuk menggunakan inti energi Zamrud untuk memberi daya pada Windstone.",
  ui_story_5032_50320502_30_dialog_content = "Kita juga tahu kegunaan batu itu, khususnya betapa pentingnya batu itu bagi Harbour City.",
  ui_story_5032_50320502_31_dialog_content = "Tapi niat baikmu tidak bisa menutupi rasa bersalahmu.",
  ui_story_5032_50320502_32_dialog_content = "Aku tahu aku tidak bisa merahasiakannya darimu.",
  ui_story_5032_50320502_33_dialog_content = "Namun, karena Anda sudah mengetahui rencana saya, saya tidak punya apa-apa lagi untuk disembunyikan.",
  ui_story_5032_50320502_34_dialog_content = "Kamu benar. aku seorang kriminal.",
  ui_story_5032_50320502_35_dialog_content = "Tapi saya tidak punya banyak pilihan untuk melindungi orang-orang di Harbour City, fondasi kota, dan Windstone.",
  ui_story_5032_50320502_36_dialog_content = "Jika bukan karena kekuatan garis keturunan yang semakin berkurang dan Windstone yang mengeluarkan asap...",
  ui_story_5032_50320502_37_dialog_content = "Mungkin saya bisa menemukan cara lain yang lebih baik.",
  ui_story_5032_50320502_38_dialog_content = "Tapi aku kehabisan waktu dengan tubuhku sendiri, juga dengan Eclipsites.",
  ui_story_5032_50320502_39_dialog_content = "Saya tidak bisa mengambil risiko apakah saya akan menemukan solusi optimal atau mati karena Sindrom Modali terlebih dahulu.",
  ui_story_5032_50320502_40_dialog_content = "Satu-satunya hal yang saya tahu adalah menukar saat-saat terakhir saya untuk masa depan Harbour City.",
  ui_story_5032_50320502_41_dialog_content = "Anda dan Caelestite adalah variabel terbesar dalam rencana saya, Yang Mulia.",
  ui_story_5032_50320502_42_dialog_content = "Saya berharap untuk menunda Anda sebelum datang ke sini untuk mengisi ulang batu itu.",
  ui_story_5032_50320502_43_dialog_content = "Tapi bahkan tidak <color=#FFB400>Lumothread</color> khusus dirancang untuk Anda bisa menghentikan Anda.",
  ui_story_5032_50320502_44_dialog_content = "...",
  ui_story_5032_50320502_45_dialog_content = "Maaf, tapi apakah Anda masih memakai gaun itu?",
  ui_story_5032_50320502_46_dialog_content = "Seharusnya masih menyerap Lumina Anda.",
  ui_story_5032_50320502_47_dialog_content = "Ya, itu mungkin mencapai batas terakhir kali.",
  ui_story_5032_50320502_48_dialog_content = "PlayerName bisa merasakan Lumina di dalam gaun itu menghilang sebagian setiap hari sebelum menyerap lebih banyak dariku.",
  ui_story_5032_50320502_49_dialog_content = "Saya benar-benar memperlakukan penyerapan lemah seperti itu sebagai sarana untuk melakukan kontrol atas Lumina sekarang.",
  ui_story_5032_50320502_50_dialog_content = "Jadi Lumothread sekarang hanya bagian dari pelatihan untuk mengontrol Lumina untuk Anda...?",
  ui_story_5032_50320502_51_dialog_content = "Betapa menakjubkan...",
  ui_story_5032_50320502_52_dialog_content = "Saya tahu saya tidak berhak mengajukan permintaan apa pun karena apa yang telah saya lakukan, Yang Mulia.",
  ui_story_5032_50320502_53_dialog_content = "Tapi aku tetap mohon...",
  ui_story_5032_50320502_54_dialog_content = "Izinkan saya untuk mengisi ulang Windstone sebelum membawa saya masuk.",
  ui_story_5032_50320502_55_dialog_content = "Saya percaya Anda dan Hall of Justice akan memberi saya pengadilan yang adil.",
  ui_story_5032_50320502_56_dialog_content = "Tapi saya punya misi yang harus saya, Elvis Modali, penuhi.",
  ui_story_5032_50320502_57_dialog_content = "Dan itu adalah permintaan terakhirku sebagai laird of Harbour City.",
  ui_story_5032_50320502_58_dialog_content = "Aku mengerti.",
  ui_story_5032_50320502_59_dialog_content = "Mempertimbangkan rekam jejak Anda dalam menjalankan Harbour City dan melindungi orang-orangnya...",
  ui_story_5032_50320502_60_dialog_content = "Saya akan membantu Anda sampai Windstone berfungsi kembali dan kota ini aman sekali lagi.",
  ui_story_5032_50320502_61_dialog_content = "Saya sangat berterima kasih, Yang Mulia.",
  ui_story_5032_50320502_62_dialog_content = "Saya mungkin buronan, tapi izinkan saya untuk berterima kasih sebagai laird of Harbour City.",
  ui_story_5032_50320502_63_dialog_content = "Mari kita singkirkan formalitas. Tolong isi ulang batu itu sesegera mungkin.",
  ui_story_5032_50320502_64_dialog_content = "Yakinlah, saya telah bekerja untuk membangunkan tanah yang disegel.",
  ui_story_5032_50320502_65_dialog_content = "Saya senang saya tidak salah tentang Anda. Ketika saya mengenal Anda, saya bisa merasakan Anda berbeda dari bangsawan lainnya.",
  ui_story_5032_50320502_66_dialog_content = "Maafkan saya karena tidak sepenuhnya mempercayai orang baru dari Lumopolis.",
  ui_story_5032_50320502_67_dialog_content = "Karena aku yakin banyak orang di Dewan Penatua menginginkan kekuatan yang melindungi Harbour City.",
  ui_story_5032_50320502_68_dialog_content = "Sayangnya, andai saja aku lebih mempercayaimu sejak awal dan tidak mencurigaimu egois seperti para bangsawan itu...",
  ui_story_5032_50320502_69_dialog_content = "Mungkin semuanya akan menjadi lebih baik, kalau begitu.",
  ui_story_5032_50320502_70_dialog_content = "Tapi masih ada kesempatan.",
  ui_story_5032_50320502_71_dialog_content = "Saya mengerti bagaimana perasaan Anda tentang apa yang mungkin dipikirkan Dewan Penatua terhadap inti energi atau Windstone.",
  ui_story_5032_50320502_72_dialog_content = "Saya, bagaimanapun, tidak akan pernah mencoba untuk merusak apa yang menjadi dasar dari Harbour City.",
  ui_story_5032_50320502_73_dialog_content = "Bagaimanapun, Eclipsites adalah musuh bersama, dan Anda akan menerima pengadilan yang adil untuk kesalahan langkah Anda.",
  ui_story_5032_50320502_74_dialog_content = "Tetapi untuk saat ini, saya dapat berjanji bahwa tidak ada Eclipsites yang akan mendekati Anda.",
  ui_story_5032_50320502_75_dialog_content = "Terima kasih, Yang Mulia.",
  ui_story_5032_50320502_76_dialog_content = "Mari kita mulai, kalau begitu.",
  ui_story_5032_50320502_77_dialog_content = "Buka halaman baru dalam sejarah Harbour City.",
  ui_story_5032_50320601_1_dialog_content = "Restart Windstone, sekarang dimulai.",
  ui_story_5032_50320601_2_dialog_content = "Memulai ulang...",
  ui_story_5032_50320601_3_dialog_content = "Gen Aurorian yang sesuai terdeteksi... Memulai ekstraksi Lumina.",
  ui_story_5032_50320601_4_dialog_content = "Ya, inilah tempatnya. Ikuti apa yang ada di buku... Batuk... Dan arahkan aliran energi.",
  ui_story_5032_50320601_5_dialog_content = "Hanya... gunakan perangkat di tanah tertutup.",
  ui_story_5032_50320601_6_dialog_content = "Permintaan pengalihan terdeteksi. Arahkan kembali sumber energi.",
  ui_story_5032_50320601_7_dialog_content = "Menghubungkan...",
  ui_story_5032_50320601_8_dialog_content = "1%... 7%... 19%...",
  ui_story_5032_50320601_9_dialog_content = "Kita tunggu saja prosesnya selesai sekarang?",
  ui_story_5032_50320601_10_dialog_content = "Benar sekali.",
  ui_story_5032_50320601_11_dialog_content = "Jika restart berhasil, Windstone akan mengadopsi <color=#FFB400>energi yang diserap</color> dari inti sebagai sumber baru.",
  ui_story_5032_50320601_12_dialog_content = "Kemudian, mereka yang secara kronis terganggu oleh <color=#FFB400>Sindrom Modali</color> akhirnya akan bebas... *batuk*",
  ui_story_5032_50320601_13_dialog_content = "Ya... Itu juga akan memperbaiki kondisimu, kan?",
  ui_story_5032_50320601_14_dialog_content = "Haha, mungkin.",
  ui_story_5032_50320601_15_dialog_content = "Tidak tahu seberapa baik saya nantinya, tapi pasti lebih baik dari saya sekarang.",
  ui_story_5032_50320601_16_dialog_content = "Setelah kekacauan yang saya sebabkan, saya tidak bisa memimpin Harbour City lagi.",
  ui_story_5032_50320601_17_dialog_content = "Memang benar bahwa tindakan Anda sangat melanggar kewajiban Anda sebagai laird, tetapi pada dasarnya untuk kebaikan rakyat.",
  ui_story_5032_50320601_18_dialog_content = "Saya akan menjelaskannya kepada Tuan Kota untuk memberi Anda penilaian yang adil.",
  ui_story_5032_50320601_19_dialog_content = "Heh, Anda memang berbeda, Yang Mulia. Izinkan saya untuk mengungkapkan rasa terima kasih saya lagi.",
  ui_story_5032_50320601_20_dialog_content = "Jika kamu tidak punya tempat untuk pergi, Elvis... kamu bisa mempertimbangkan untuk naik ke Emerald.",
  ui_story_5032_50320601_21_dialog_content = "Oh? Tapi aku bukan pemain sirkus, Jeno.",
  ui_story_5032_50320601_22_dialog_content = "Itu keren. Kamu bisa belajar.",
  ui_story_5032_50320601_23_dialog_content = "Bagaimanapun, kita hanya perlu penjinak alternatif.",
  ui_story_5032_50320601_24_dialog_content = "Itu berarti saya harus bekerja sangat keras, kalau begitu.",
  ui_story_5032_50320601_25_dialog_content = "(Elvis terlihat jauh lebih santai. Kurasa mereka sudah berbaikan.)",
  ui_story_5032_50320601_26_dialog_content = "<color=#e8d9bb>Ngungg!</color>",
  ui_story_5032_50320601_27_dialog_content = "Mengapa Windstone membuat semua kebisingan itu?",
  ui_story_5032_50320601_28_dialog_content = "Ada apa?",
  ui_story_5032_50320601_29_dialog_content = "Peringatan. Kesalahan pengalihan energi.",
  ui_story_5032_50320601_30_dialog_content = "Kode Kesalahan 102. Energi tidak sesuai dengan <color=#FFB400>Batu angin</color>.",
  ui_story_5032_50320601_31_dialog_content = "Mustahil! Penelitian saya menunjukkan energi dari inti energi adalah yang paling cocok dengan batu!",
  ui_story_5032_50320601_32_dialog_content = "Jangan panik, Elvis!",
  ui_story_5032_50320601_33_dialog_content = "Periksa batunya dan lihat apakah ada yang bisa kita lakukan.",
  ui_story_5032_50320601_34_dialog_content = "Aku akan... Apa ini?!",
  ui_story_5032_50320601_35_dialog_content = "Ada apa?",
  ui_story_5032_50320601_36_dialog_content = "Tingkat keluaran inti energi berfluktuasi... dan semakin intens!",
  ui_story_5032_50320601_37_dialog_content = "Itu hanya terjadi ketika energinya tidak cukup murni!",
  ui_story_5032_50320601_38_dialog_content = "Peringatan. Kesalahan kritis dalam pengalihan energi.",
  ui_story_5032_50320601_39_dialog_content = "Kode Kesalahan 600. Aliran energi melebihi <color=#FFB400>Batu angin</color> kapasitas.",
  ui_story_5032_50320601_40_dialog_content = "Hentikan masukan energi segera untuk menghindari dampak yang parah.",
  ui_story_5032_50320601_41_dialog_content = "Matikan, Elvis, atau akan meledak!",
  ui_story_5032_50320601_42_dialog_content = "Saya mencoba...",
  ui_story_5032_50320601_43_dialog_content = "Ugh!!!",
  ui_story_5032_50320601_44_dialog_content = "Vice, lindungi PlayerName!",
  ui_story_5032_50320601_45_dialog_content = "Dapatkan di belakang kami, PlayerName!",
  ui_story_5032_50320601_46_dialog_content = "Elvis!",
  ui_story_5032_50320601_47_dialog_content = "Jangan mendekat... Energinya... mulai bocor!",
  ui_story_5032_50320601_48_dialog_content = "Aku tidak bisa menghentikannya!",
  ui_story_5032_50320601_49_dialog_content = "Jangankan tongkatnya, jatuhkan saja!",
  ui_story_5032_50320601_50_dialog_content = "<color=#e8d9bb>DUARR!!!</color>",
  ui_story_5032_50320601_51_dialog_content = "Uh!",
  ui_story_5032_50320601_52_dialog_content = "*Batuk-batuk*",
  ui_story_5032_50320601_53_dialog_content = "Kamu baik-baik saja, Jeno?!",
  ui_story_5032_50320601_54_dialog_content = "*Batuk*... Aku baik-baik saja, masih hidup.",
  ui_story_5032_50320601_55_dialog_content = "Jika saya lebih lambat, Anda akan mati.",
  ui_story_5032_50320601_56_dialog_content = "Windstone... di luar kendali...!",
  ui_story_5032_50320601_57_dialog_content = "Batu Angin! Apakah Windstone baik-baik saja?!",
  ui_story_5032_50320601_58_dialog_content = "Elvis!",
  ui_story_5032_50320601_59_dialog_content = "Ini dia... Untungnya, tidak rusak, namun semua energinya telah hilang.",
  ui_story_5032_50320601_60_dialog_content = "Mungkin masih bisa di restart!",
  ui_story_5032_50320601_61_dialog_content = "Mulai ulang?",
  ui_story_5032_50320601_62_dialog_content = "Lihat, Elvis, tanah yang disegel telah hancur tak bisa dikenali oleh ledakan.",
  ui_story_5032_50320601_63_dialog_content = "Perangkat kuno rusak. Bagaimana kita akan memulai kembali?",
  ui_story_5032_50320601_64_dialog_content = "Aku... Beri aku lebih banyak waktu dan aku akan mencari cara!",
  ui_story_5032_50320601_65_dialog_content = "Tolong tolong! gerhana!",
  ui_story_5032_50320601_66_dialog_content = "Eclipsite?!",
  ui_story_5032_50320601_67_dialog_content = "Suara itu sepertinya berasal dari kota.",
  ui_story_5032_50320601_68_dialog_content = "*Batuk*... Oh tidak, Eclipsites pasti telah merusak segelnya karena Windstone kehilangan semua energinya!",
  ui_story_5032_50320601_69_dialog_content = "<color=#e8d9bb>Sementara itu, di Harbour City</color>",
  ui_story_5032_50320601_70_dialog_content = "Mengapa begitu banyak Eclipsites keluar dari lautan?!",
  ui_story_5032_50320601_71_dialog_content = "Cepat, pergi ke pantai! Siapkan pertahanan dan evakuasi orang-orang!",
  ui_story_5032_50320601_72_dialog_content = "Siap, Pak!",
  ui_story_5032_50320601_73_dialog_content = "Gerhana muncul di sepanjang pantai?",
  ui_story_5032_50320601_74_dialog_content = "Dan suara ledakan yang datang dari tanah tertutup tadi... Apakah Laird Elvis gagal?",
  ui_story_5032_50320601_75_dialog_content = "Aku harus melindungi sarangnya. Dengan semua prajurit pergi untuk melawan Eclipsites, sekaranglah waktunya.",
  ui_story_5032_50320601_76_dialog_content = "Ikuti saya, semuanya!",
  ui_story_5032_50320601_77_dialog_content = "Ya!!!",
  ui_story_5032_50320601_78_dialog_content = "Laird Elvis!",
  ui_story_5032_50320601_79_dialog_content = "Patou? Apa yang kamu lakukan di sini?",
  ui_story_5032_50320601_80_dialog_content = "Huft, huft...",
  ui_story_5032_50320601_81_dialog_content = "Anda benar-benar tidak memudahkan saya untuk menemukan, Elvis, dan Patou.",
  ui_story_5032_50320601_82_dialog_content = "Wajahmu memelintir.",
  ui_story_5032_50320601_83_dialog_content = "Bahkan tidak mencoba bersembunyi?",
  ui_story_5032_50320601_84_dialog_content = "Sekarang bukan waktunya untuk snark Anda!",
  ui_story_5032_50320601_85_dialog_content = "Tidak bisakah kamu melihat itu mendesak sekarang? Jangan menghalangi!",
  ui_story_5032_50320601_86_dialog_content = "Jeno benar. Harbour City dalam bahaya.",
  ui_story_5032_50320601_87_dialog_content = "Tunggu... Mengapa Anda di sini, Yang Mulia?",
  ui_story_5032_50320601_88_dialog_content = "Saya akan membahasnya nanti. Kami memiliki masalah yang jauh lebih penting.",
  ui_story_5032_50320601_89_dialog_content = "*Batuk*... Bagaimana Harbour City, Patou?",
  ui_story_5032_50320601_90_dialog_content = "Tak terhitung banyaknya gerhana yang keluar dari laut, pak. Windstone mungkin tidak efektif sekarang.",
  ui_story_5032_50320601_91_dialog_content = "aku takut itu...",
  ui_story_5032_50320601_92_dialog_content = "Keburukan, PlayerName, ayo kembali ke kota.",
  ui_story_5032_50320601_93_dialog_content = "Ada begitu banyak warga yang tidak bersenjata. Kita tidak bisa duduk diam!",
  ui_story_5032_50320601_94_dialog_content = "Ya, mengerti!",
  ui_story_5032_50320601_95_dialog_content = "Tentu!",
  ui_story_5032_50320601_96_dialog_content = "Tapi tunggu... Bagaimana dengan pelarian penjara?",
  ui_story_5032_50320601_97_dialog_content = "Jeno, tolong... Pergilah dengan Yang Mulia.",
  ui_story_5032_50320601_98_dialog_content = "Dan tolong... lindungi penduduk Harbour City.",
  ui_story_5032_50320601_99_dialog_content = "Tidak, aku tinggal di sini bersamamu.",
  ui_story_5032_50320601_100_dialog_content = "Tidakkah Anda menyadari bahwa Anda berada di kaki terakhir Anda?",
  ui_story_5032_50320601_101_dialog_content = "Jangan khawatir, Jeno, aku masih bisa pergi.",
  ui_story_5032_50320601_102_dialog_content = "*Batuk* Aku... harus kembali. Seharusnya ada petunjuk tentang memulai ulang Windstone di file.",
  ui_story_5032_50320601_103_dialog_content = "Jika saya dapat memulai kembali, Eclipsites akan hilang.",
  ui_story_5032_50320601_104_dialog_content = "Anda lebih baik menemukan sesuatu untuk menyingkirkan Eclipsites.",
  ui_story_5032_50320601_105_dialog_content = "Aku tidak akan membiarkan buronan bergerak bebas. Loewe dan aku akan mengawasimu!",
  ui_story_5032_50320601_106_dialog_content = "Hehe, terima kasih atas pemikirannya.",
  ui_story_5032_50320601_107_dialog_content = "Elvis...",
  ui_story_5032_50320601_108_dialog_content = "Tidak apa-apa, Jeno. Aku akan baik-baik saja dengan Patou dan orang lain di sekitarnya.",
  ui_story_5032_50320601_109_dialog_content = "Tolong jaga orang-orang di Harbour City untukku.",
  ui_story_5032_50320601_110_dialog_content = "...",
  ui_story_5032_50320601_111_dialog_content = "Anda pasti tahu cara memberi saya kentang panas.",
  ui_story_5032_50320601_112_dialog_content = "Maaf... Aku akan menebusnya saat ini selesai.",
  ui_story_5032_50320601_113_dialog_content = "Selama itu dalam kemampuan saya.",
  ui_story_5032_50320601_114_dialog_content = "Baiklah, aku akan menunggumu.",
  ui_story_5032_50320601_115_dialog_content = "Oke.",
  ui_story_5032_50320601_116_dialog_content = "Um... Mengapa kita mendapatkan begitu banyak Eclipsites?",
  ui_story_5032_50320601_117_dialog_content = "Lihat ke sana!",
  ui_story_5032_50320601_118_dialog_content = "Mereka bertambah jumlahnya!",
  ui_story_5032_50320601_119_dialog_content = "Bagaimana mungkin...",
  ui_story_5032_50320601_120_dialog_content = "Laut penuh dengan Eclipsites!",
  ui_story_5032_50320601_121_dialog_content = "Berhentilah berpikir dan mulailah berjuang!",
  ui_story_5032_50320601_122_dialog_content = "Apakah mungkin untuk melawan mereka semua?",
  ui_story_5032_50320601_123_dialog_content = "Kami tidak punya pilihan selain bertarung.",
  ui_story_5032_50320601_124_dialog_content = "Kita harus berdiri tegak dan melindungi orang-orang di Harbour City.",
  ui_story_5032_50320601_125_dialog_content = "Aku tidak akan mundur sampai warga sipil dievakuasi!",
  ui_story_5032_50320601_126_dialog_content = "... Elvis benar. Anda berbeda dari bangsawan lainnya.",
  ui_story_5032_50320601_127_dialog_content = "Biarkan saya membantu. Bagaimanapun, ini pernah menjadi rumah kita.",
  ui_story_5032_50320602_1_dialog_content = "Ugh... Pooh! Ini asin!",
  ui_story_5032_50320602_2_dialog_content = "Harus diwaspadai tidak hanya untuk Eclipsites tetapi juga laut yang mengamuk ...",
  ui_story_5032_50320602_3_dialog_content = "Aku ingin tahu apakah Fia dan yang lainnya akan baik-baik saja di <color=#FFB400>Zamrud</color>.",
  ui_story_5032_50320602_4_dialog_content = "Seharusnya baik-baik saja dengan Rainbow dan Ciel di sana, kurasa.",
  ui_story_5032_50320602_5_dialog_content = "Tidak juga... Zamrud itu seperti pulau tunggal dengan semua gerhana di dalam air.",
  ui_story_5032_50320602_6_dialog_content = "Orang-orang di pantai masih bisa mundur, tetapi Zamrud tidak punya tempat untuk pergi.",
  ui_story_5032_50320602_7_dialog_content = "Kita harus pergi membantu mereka!",
  ui_story_5032_50320602_8_dialog_content = "Tapi bagaimana di sini...?",
  ui_story_5032_50320602_9_dialog_content = "Saya mengerti. Dengan bantuan Jeno, itu akan baik-baik saja!",
  ui_story_5032_50320602_10_dialog_content = "Anda pergi membantu Fia!",
  ui_story_5032_50320602_11_dialog_content = "OK mengerti!",
  ui_story_5032_50320602_12_dialog_content = "Anda yakin mereka berdua bisa mengatasinya?",
  ui_story_5032_50320602_13_dialog_content = "Ya.",
  ui_story_5032_50320602_14_dialog_content = "Sebagai teman mereka, saya tahu betapa tangguhnya mereka, lebih baik dari siapa pun.",
  ui_story_5032_50320602_15_dialog_content = "Percayalah padaku. Mereka akan membawa kru Anda ke tempat yang aman.",
  ui_story_5032_50320602_16_dialog_content = "Karena Anda mengatakannya seperti itu ...",
  ui_story_5032_50320602_17_dialog_content = "Gahhhh!!!",
  ui_story_5032_50320602_18_dialog_content = "Cih...",
  ui_story_5032_50320602_19_dialog_content = "Mengapa ada begitu banyak Eclipsites? Sudah tak ada habisnya.",
  ui_story_5032_50320602_20_dialog_content = "Mereka telah terperangkap di bawah laut begitu lama. Mereka pasti akan merajalela sekarang setelah segelnya rusak.",
  ui_story_5032_50320602_21_dialog_content = "Anda bisa membayangkan berapa banyak energi yang dibutuhkan Windstone untuk mempertahankan segel yang begitu kuat.",
  ui_story_5032_50320602_22_dialog_content = "Sekarang bukan waktunya untuk spekulasi. Kami punya pertarungan di tangan kami!",
  ui_story_5032_50320602_23_dialog_content = "Tentu.",
  ui_story_5032_50320602_24_dialog_content = "Grah...",
  ui_story_5032_50320602_25_dialog_content = "Yang mulia!",
  ui_story_5032_50320602_26_dialog_content = "Ada terlalu banyak Eclipsites, dan garis pantainya terlalu panjang bagi kita untuk membuat garis pertahanan yang efektif!",
  ui_story_5032_50320602_27_dialog_content = "Kita kalah jumlah, tapi kita mungkin masih punya kesempatan jika kita memusatkan kekuatan kita di kota.",
  ui_story_5032_50320602_28_dialog_content = "Tidak bisa. Kami belum mengevakuasi semua orang!",
  ui_story_5032_50320602_29_dialog_content = "Yah, sepertinya tidak ada pilihan... Dapatkan penjaga untuk melindungi gerbang dan warga sipil. Kami akan meninggalkan area pertahanan pesisir lainnya secara berurutan!",
  ui_story_5032_50320602_30_dialog_content = "Apapun, tahan sampai semua orang dievakuasi.",
  ui_story_5032_50320602_31_dialog_content = "Siap, laksanakan!",
  ui_story_5032_50320701_1_dialog_content = "Graagh!",
  ui_story_5032_50320701_2_dialog_content = "Ahhh, mereka benar-benar memecahkan jendela ini juga!",
  ui_story_5032_50320701_3_dialog_content = "Air dan pecahan kaca ada di mana-mana. Ini tidak bisa lebih buruk...",
  ui_story_5032_50320701_4_dialog_content = "Saya tidak mampu menyewa petugas kebersihan, saya juga tidak bisa membersihkannya sendiri!",
  ui_story_5032_50320701_5_dialog_content = "Graaaah!",
  ui_story_5032_50320701_6_dialog_content = "T-Tenang saja, Rainbow. Saya akan membantu Anda dengan kekacauan nanti.",
  ui_story_5032_50320701_7_dialog_content = "Ada semakin banyak Eclipsites, jadi mari kita berhati-hati.",
  ui_story_5032_50320701_8_dialog_content = "Ciel, Fia, tolong naik ke atas jendela seperti yang kamu lakukan sebelumnya.",
  ui_story_5032_50320701_9_dialog_content = "Aku akan menyingkirkan bajingan ini!",
  ui_story_5032_50320701_10_dialog_content = "Grrrr!",
  ui_story_5032_50320701_11_dialog_content = "R-Rainbow!",
  ui_story_5032_50320701_12_dialog_content = "... Dia menyerbu ke pertempuran seperti biasa.",
  ui_story_5032_50320701_13_dialog_content = "Gerhana adalah satu-satunya hal yang ada di pikirannya ketika dia melihatnya.",
  ui_story_5032_50320701_14_dialog_content = "Akankah Rainbow baik-baik saja?",
  ui_story_5032_50320701_15_dialog_content = "Dia sudah mengalahkan banyak dari mereka, dan dia terluka.",
  ui_story_5032_50320701_16_dialog_content = "Meskipun itu semua ditimbulkan sendiri dalam kegembiraannya ...",
  ui_story_5032_50320701_17_dialog_content = "Saya agak khawatir juga.",
  ui_story_5032_50320701_18_dialog_content = "Hmm, saya menyalahkan saya yang tidak mengoperasikan Styx dengan benar sebelumnya.",
  ui_story_5032_50320701_19_dialog_content = "Atau aku tidak akan berdiri begitu saja tanpa daya...",
  ui_story_5032_50320701_20_dialog_content = "Iya, aku juga.",
  ui_story_5032_50320701_21_dialog_content = "Andai saja aku tidak melemparkan Kyllo ke laut.",
  ui_story_5032_50320701_22_dialog_content = "Dengan Kyllo di sekitar, Eclipsites ini akan menjadi pilihan yang mudah!",
  ui_story_5032_50320701_23_dialog_content = "Sayang. Setidaknya ini akan menjadi jendela terakhir, dan kita bisa segera mengunci Eclipsites.",
  ui_story_5032_50320701_24_dialog_content = "Baiklah, aku menaiki sisi ini. Bantu aku, Fia...",
  ui_story_5032_50320701_25_dialog_content = "Grrr!",
  ui_story_5032_50320701_26_dialog_content = "Ugh! A-Eklipsite Lain!",
  ui_story_5032_50320701_27_dialog_content = "Pergi, Fia!",
  ui_story_5032_50320701_28_dialog_content = "Gahh!",
  ui_story_5032_50320701_29_dialog_content = "<size=45>Aaaah!</size>",
  ui_story_5032_50320701_30_dialog_content = "Fi!",
  ui_story_5032_50320701_31_dialog_content = "Oh tidak, Eclipsite terlalu dekat dengannya untukku menggunakan Aqua Blaster!",
  ui_story_5032_50320701_32_dialog_content = "Kalau begitu…",
  ui_story_5032_50320701_33_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_5032_50320701_34_dialog_content = "Grrr!",
  ui_story_5032_50320701_35_dialog_content = "Uh!",
  ui_story_5032_50320701_36_dialog_content = "Rainbow! Fi! Apakah kalian baik-baik saja?",
  ui_story_5032_50320701_37_dialog_content = "Um…",
  ui_story_5032_50320701_38_dialog_content = "Aku baik-baik saja. Kepalaku hanya sedikit sakit.",
  ui_story_5032_50320701_39_dialog_content = "Dimana Rainbow? Saya pikir saya melihatnya datang ke arah saya.",
  ui_story_5032_50320701_40_dialog_content = "...",
  ui_story_5032_50320701_41_dialog_content = "Oh tidak, Rainbow pingsan!",
  ui_story_5032_50320701_42_dialog_content = "Punggungnya berdarah!",
  ui_story_5032_50320701_43_dialog_content = "Apakah dia dikejutkan oleh Eclipsite?",
  ui_story_5032_50320701_44_dialog_content = "Dia... Dia terluka saat mencoba menyelamatkanku...",
  ui_story_5032_50320701_45_dialog_content = "C-Ce, kita tidak punya apa-apa untuk menghentikan pendarahan. A-Apa yang harus dilakukan...",
  ui_story_5032_50320701_46_dialog_content = "Saya tidak bisa membantu PlayerName dan teman-teman saya ketika mereka melawan robot besar.",
  ui_story_5032_50320701_47_dialog_content = "Sekarang aku tidak bisa membantu Rainbow dan Ciel, dan aku bahkan membuat Rainbow terluka...",
  ui_story_5032_50320701_48_dialog_content = "<anim type=Shake>Bo-hoo... aku... aku...</anim>",
  ui_story_5032_50320701_49_dialog_content = "Grrr!",
  ui_story_5032_50320701_50_dialog_content = "Tidak, sekarang bukan waktunya untuk menangis!",
  ui_story_5032_50320701_51_dialog_content = "Aku harus melindungi Rainbow!",
  ui_story_5032_50320701_52_dialog_content = "Menjauhlah, kamu Eclipsites bodoh!",
  ui_story_5032_50320701_53_dialog_content = "<color=#e8d9bb>Dor, dor, dor!</color>",
  ui_story_5032_50320701_54_dialog_content = "Graagh!",
  ui_story_5032_50320701_55_dialog_content = "Wow! Itu berhasil!",
  ui_story_5032_50320701_56_dialog_content = "Saya tahu itu tidak berhasil terakhir kali karena robotnya terlalu tangguh ...",
  ui_story_5032_50320701_57_dialog_content = "Gan! Gan!",
  ui_story_5032_50320701_58_dialog_content = "Awas, Fia, mereka datang lagi!",
  ui_story_5032_50320701_59_dialog_content = "Ahhhh... Kenapa banyak sekali Eclipsites?!",
  ui_story_5032_50320701_60_dialog_content = "Apakah mereka bermigrasi melalui laut atau sesuatu yang tiba-tiba?",
  ui_story_5032_50320701_61_dialog_content = "Tiga tembakan tersisa, dengan klip cadangan...",
  ui_story_5032_50320701_62_dialog_content = "*Menangis* Ini tidak cukup!",
  ui_story_5032_50320701_63_dialog_content = "Grrr!",
  ui_story_5032_50320701_64_dialog_content = "<color=#e8d9bb>Dor, dor, dor!</color>",
  ui_story_5032_50320701_65_dialog_content = "Andai saja Kyllo ada di sini...",
  ui_story_5032_50320701_66_dialog_content = "Kyllo!",
  ui_story_5032_50320701_67_dialog_content = "Lo, lo, lo!",
  ui_story_5032_50320701_68_dialog_content = "Raawr!",
  ui_story_5032_50320701_69_dialog_content = "Kyllo? K-Kamu di sini?!",
  ui_story_5032_50320701_70_dialog_content = "A-Binatang ajaib macam apa ini?",
  ui_story_5032_50320701_71_dialog_content = "Ini teman saya. Namanya Kylo!",
  ui_story_5032_50320701_72_dialog_content = "A-Luar biasa! Ini mengalahkan Eclipsites.",
  ui_story_5032_50320701_73_dialog_content = "Hehe, tentu saja!",
  ui_story_5032_50320701_74_dialog_content = "Kyllo adalah eksotik yang berevolusi!",
  ui_story_5032_50320701_75_dialog_content = "Itu sepotong kue untuk itu!",
  ui_story_5032_50320701_76_dialog_content = "Grrr!",
  ui_story_5032_50320701_77_dialog_content = "Hati-hati, Kylo. Eclipsites datang di belakang Anda!",
  ui_story_5032_50320701_78_dialog_content = "Lo, lo!",
  ui_story_5032_50320701_79_dialog_content = "A-Apa? Anda tidak bisa berbalik?",
  ui_story_5032_50320701_80_dialog_content = "Apakah terlalu besar untuk bermanuver di ruang sempit?",
  ui_story_5032_50320701_81_dialog_content = "Hah—",
  ui_story_5032_50320701_82_dialog_content = "Ah, aku harus memuat ulang!",
  ui_story_5032_50320701_83_dialog_content = "<color=#e8d9bb>Dentang-</color>",
  ui_story_5032_50320701_84_dialog_content = "Ups, saya menjatuhkan semua peluru!",
  ui_story_5032_50320701_85_dialog_content = "Oh tidak, Kylo!",
  ui_story_5032_50320701_86_dialog_content = "Lihat!",
  ui_story_5032_50320701_87_dialog_content = "Rapid Torrent!",
  ui_story_5032_50320701_88_dialog_content = "Grrr!",
  ui_story_5032_50320701_89_dialog_content = "Hah? I-Itu terdengar seperti...",
  ui_story_5032_50320701_90_dialog_content = "Apakah semua orang baik-baik saja?",
  ui_story_5032_50320701_91_dialog_content = "Maaf, kami datang terlambat. Terlalu banyak Eclipsites di jalan.",
  ui_story_5032_50320701_92_dialog_content = "Ini Vice dan PlayerName!",
  ui_story_5032_50320701_93_dialog_content = "Huh, kurasa kita hanya latar belakang Fia.",
  ui_story_5032_50320701_94_dialog_content = "Ya, ya, saya merasa sangat sedih!",
  ui_story_5032_50320701_95_dialog_content = "Si kembar tiga! Mengapa Anda turun dari dek?",
  ui_story_5032_50320701_96_dialog_content = "Kami bertemu Caelestite dan Vice di atas sana!",
  ui_story_5032_50320701_97_dialog_content = "Mereka bilang di luar sangat berbahaya. Beberapa jenis segel rusak.",
  ui_story_5032_50320701_98_dialog_content = "Dan semua Eclipsites yang tidur di bawah laut terbangun!",
  ui_story_5032_50320701_99_dialog_content = "Jadi kami memblokir akses dari dek dan datang untuk memberi tahu—",
  ui_story_5032_50320701_100_dialog_content = "Eh? Tunggu, apakah Rainbow itu tergeletak di sana?",
  ui_story_5032_50320701_101_dialog_content = "I-Itu!",
  ui_story_5032_50320701_102_dialog_content = "Apa yang terjadi dengannya?",
  ui_story_5032_50320701_103_dialog_content = "D-Dia melindungiku...",
  ui_story_5032_50320701_104_dialog_content = "Aku benar-benar minta maaf.",
  ui_story_5032_50320701_105_dialog_content = "Gan! Gan!",
  ui_story_5032_50320701_106_dialog_content = "... Kami akan mengambil ini nanti.",
  ui_story_5032_50320701_107_dialog_content = "Harus menghilangkan Eclipsites ini terlebih dahulu!",
  ui_story_5032_50320701_X107_dialog_content = "<color=#e8d9bb>Beberapa waktu kemudian...</color>",
  ui_story_5032_50320701_108_dialog_content = "J-Jadi mereka benar-benar keluar dari dasar laut?",
  ui_story_5032_50320701_109_dialog_content = "Ya. Kami menyaksikan Elvis gagal dalam usahanya dan gelombang Eclipsites memenuhi pantai.",
  ui_story_5032_50320701_110_dialog_content = "Bukankah itu akan menempatkan Harbour City dalam bahaya besar?",
  ui_story_5032_50320701_111_dialog_content = "Carleen dan Jeno memimpin pasukan yang mempertahankan garis pantai.",
  ui_story_5032_50320701_112_dialog_content = "Dan Elvis sedang mencoba mencari cara lain untuk membuka kembali segelnya.",
  ui_story_5032_50320701_113_dialog_content = "Satu-satunya hal yang bisa kita lakukan adalah memastikan semua orang aman dan mengulur waktu Elvis.",
  ui_story_5032_50320701_114_dialog_content = "Terima kasih telah mempertaruhkan hidup Anda untuk datang ke sini untuk kami.",
  ui_story_5032_50320701_115_dialog_content = "Aku terlalu ceroboh dan menempatkan Ciel dan Fia dalam bahaya.",
  ui_story_5032_50320701_116_dialog_content = "Jika Anda tidak berhasil tepat waktu ...",
  ui_story_5032_50320701_117_dialog_content = "Tidak masalah. Anda akan melakukan hal yang sama untuk kami jika kami berada di posisi Anda.",
  ui_story_5032_50320701_118_dialog_content = "Dan Fia akan berada dalam masalah besar jika bukan kamu.",
  ui_story_5032_50320701_119_dialog_content = "Terima kasih, Rainbow.",
  ui_story_5032_50320701_120_dialog_content = "Seharusnya aku berterima kasih padamu dan Kyllo karena telah menyelamatkan kita semua!",
  ui_story_5032_50320701_121_dialog_content = "Lihat!",
  ui_story_5032_50320701_122_dialog_content = "Oh, kenapa Kyllo ada di sini?",
  ui_story_5032_50320701_123_dialog_content = "Bukankah kamu membiarkannya kembali ke laut, Fia?",
  ui_story_5032_50320701_124_dialog_content = "Lo, lo, lo.",
  ui_story_5032_50320701_125_dialog_content = "Um, Kyllo mengatakan itu masuk dari jendela yang Eclipsites pecah.",
  ui_story_5032_50320701_126_dialog_content = "Itu telah tinggal di perairan terdekat sebelum tiba-tiba mendapat perasaan aneh ketika mendekati Zamrud.",
  ui_story_5032_50320701_127_dialog_content = "Perasaan yang aneh? Apa itu?",
  ui_story_5032_50320701_128_dialog_content = "Lo, lo.",
  ui_story_5032_50320701_129_dialog_content = "Anda merasa saya dalam bahaya dan mengikuti Lumina saya?",
  ui_story_5032_50320701_130_dialog_content = "Lihat!",
  ui_story_5032_50320701_131_dialog_content = "Merasa Fia dalam bahaya?",
  ui_story_5032_50320701_132_dialog_content = "Apakah itu kemampuan khusus untuk Kyllo?",
  ui_story_5032_50320701_133_dialog_content = "Mungkin karena Kyllo dan Fia memiliki ikatan yang dalam.",
  ui_story_5032_50320701_134_dialog_content = "Jadi ada hubungan psikis di antara mereka.",
  ui_story_5032_50320701_135_dialog_content = "Lihat!",
  ui_story_5032_50320701_136_dialog_content = "Aku tahu.",
  ui_story_5032_50320701_137_dialog_content = "Sejak kau kembali, Kyllo, apakah itu berarti kau tahu di mana Cloudwhale berada?",
  ui_story_5032_50320701_138_dialog_content = "Lo, lo...",
  ui_story_5032_50320701_139_dialog_content = "Eh... Apa itu?",
  ui_story_5032_50320701_140_dialog_content = "Anda telah mengembara karena Anda tidak dapat menemukan petunjuk?",
  ui_story_5032_50320701_141_dialog_content = "Kamu tidak ingin melihatku karena aku akan meneriakimu... Hei, aku tidak jahat!",
  ui_story_5032_50320701_142_dialog_content = "Lihat!",
  ui_story_5032_50320701_143_dialog_content = "Kamu terdengar sangat jahat sekarang, Fia.",
  ui_story_5032_50320701_144_dialog_content = "Kyllo sangat menyukaimu, jadi kamu harus bersikap lebih baik padanya.",
  ui_story_5032_50320701_145_dialog_content = "Ya, dan Kyllo pantas menerima ucapan terima kasih yang tulus karena telah menyelamatkan semua orang juga.",
  ui_story_5032_50320701_146_dialog_content = "Lo, lo!",
  ui_story_5032_50320701_147_dialog_content = "A-Untuk apa kamu mengangguk?",
  ui_story_5032_50320701_148_dialog_content = "Bukankah aku sudah baik padamu?",
  ui_story_5032_50320701_149_dialog_content = "lihat...",
  ui_story_5032_50320701_150_dialog_content = "... Oke, oke, saya mengerti. J-Berhentilah menangis!",
  ui_story_5032_50320701_151_dialog_content = "Lo, lo!",
  ui_story_5032_50320701_152_dialog_content = "K-Kamu menginginkannya sekarang? Tidak perlu terburu-buru...",
  ui_story_5032_50320701_153_dialog_content = "Yah, oke, terima kasih... Ahem.",
  ui_story_5032_50320701_154_dialog_content = "lihat?",
  ui_story_5032_50320701_155_dialog_content = "Terima kasih!",
  ui_story_5032_50320701_156_dialog_content = "<size=45>Terima kasih telah menyelamatkan kami!</size>",
  ui_story_5032_50320701_157_dialog_content = "Lihat!",
  ui_story_5032_50320701_158_dialog_content = "Dan... Aku akan mencoba untuk tidak jahat padamu lagi, oke?",
  ui_story_5032_50320701_159_dialog_content = "Lo, lo!",
  ui_story_5032_50320701_160_dialog_content = "J-Jangan memaksakan keberuntunganmu!",
  ui_story_5032_50320701_161_dialog_content = "Lo, lo, lo!",
  ui_story_5032_50320701_162_dialog_content = "Oke, oke, mengerti!",
  ui_story_5032_50320701_163_dialog_content = "Lima kantong kue hewan, hanya untuk Anda!",
  ui_story_5032_50320701_164_dialog_content = "Lihat!",
  ui_story_5032_50320701_165_dialog_content = "Mengapa ini terasa seperti deja vu?",
  ui_story_5032_50320701_166_dialog_content = "Ada apa dengan semua binatang yang menakjubkan ini? Mereka benar-benar tahu cara menawar.",
  ui_story_5032_50320701_167_dialog_content = "Oh, binatang yang menakjubkan!",
  ui_story_5032_50320701_168_dialog_content = "Merylt, Firmet! Bica dan yang lainnya masih di kamar!",
  ui_story_5032_50320701_169_dialog_content = "Oh tidak, Eclipsites akan menakuti mereka!",
  ui_story_5032_50320701_170_dialog_content = "Jangan bangun dulu, Rainbow!",
  ui_story_5032_50320701_171_dialog_content = "Saya baik-baik saja. Merylt menggunakan peralatan medis untukku. Saya merasa lebih baik sekarang!",
  ui_story_5032_50320701_172_dialog_content = "Harus menyelamatkan hewan sekarang!",
  ui_story_5032_50320701_173_dialog_content = "Hah—",
  ui_story_5032_50320701_174_dialog_content = "... Mereka benar-benar memilih waktu yang tepat, bukan?",
  ui_story_5032_50320701_175_dialog_content = "L-Serahkan pada kami, Rainbow.",
  ui_story_5032_50320701_176_dialog_content = "Merylt, Subli, apakah kamu siap?",
  ui_story_5032_50320701_177_dialog_content = "Ya! Mari kita lakukan!",
  ui_story_5032_50320702_1_dialog_content = "Ini sudah berakhir sekarang, Bica, kamu akan baik-baik saja.",
  ui_story_5032_50320702_2_dialog_content = "Aku telah melenyapkan semua orang jahat itu!",
  ui_story_5032_50320702_3_dialog_content = "Hai hai...",
  ui_story_5032_50320702_4_dialog_content = "Yang malang masih gemetar.",
  ui_story_5032_50320702_5_dialog_content = "Kenapa aku merasa bukan Eclipsite yang membuat Bica takut...",
  ui_story_5032_50320702_6_dialog_content = "Ada Glooey di sini, Rainbow!",
  ui_story_5032_50320702_7_dialog_content = "Hallo!",
  ui_story_5032_50320702_8_dialog_content = "Dan dua lagi di sini!",
  ui_story_5032_50320702_9_dialog_content = "Hallo... Hallo!",
  ui_story_5032_50320702_10_dialog_content = "Bagus, Glooey juga baik-baik saja.",
  ui_story_5032_50320702_11_dialog_content = "Jadi itu hanya meninggalkan ...",
  ui_story_5032_50320702_12_dialog_content = "Eh? Ada apa, Merylt?",
  ui_story_5032_50320702_13_dialog_content = "G-Geedo hilang, Rainbow!",
  ui_story_5032_50320702_14_dialog_content = "Geedo?",
  ui_story_5032_50320702_15_dialog_content = "Itu disimpan dalam botol, jadi tidak bisa bergerak, kan?",
  ui_story_5032_50320702_16_dialog_content = "Ya... J-Jadi Eclipsites pasti punya...",
  ui_story_5032_50320702_17_dialog_content = "Jangan khawatir. Ciel, Fia, dan aku akan mencari di depan.",
  ui_story_5032_50320702_18_dialog_content = "Anda dapat terus mencari hewan lain yang lolos.",
  ui_story_5032_50320702_19_dialog_content = "B-baiklah.",
  ui_story_5032_50320702_20_dialog_content = "Tetap semangat, Merylt. Kami masih punya banyak hewan yang hilang untuk ditemukan!",
  ui_story_5032_50320702_21_dialog_content = "Miniphant, Kucing berekor tiga, Melompat...",
  ui_story_5032_50320702_22_dialog_content = "Mari kita periksa kamar-kamar yang hancur itu. Kita perlu memeriksa gudang secara menyeluruh!",
  ui_story_5032_50320702_23_dialog_content = "Kucing berekor tiga suka bersembunyi di sudut-sudut gelap saat mereka ketakutan.",
  ui_story_5032_50320702_24_dialog_content = "Aku paham.",
  ui_story_5032_50320702_25_dialog_content = "Emerald menampung begitu banyak binatang yang menakjubkan, begitu.",
  ui_story_5032_50320702_26_dialog_content = "Pantas saja Fia tidak mau pergi.",
  ui_story_5032_50320702_27_dialog_content = "Memang... Oh, Merylt.",
  ui_story_5032_50320702_28_dialog_content = "Binatang ajaib macam apa Geedo itu? Kami dapat membantu Anda menemukannya.",
  ui_story_5032_50320702_29_dialog_content = "Anu…",
  ui_story_5032_50320702_30_dialog_content = "itu... eh...",
  ui_story_5032_50320702_31_dialog_content = "Makhluk air mirip ikan yang dibawa kembali oleh Ringmaster Jeno, tapi kami tidak tahu nama pastinya.",
  ui_story_5032_50320702_32_dialog_content = "Jadi kami hanya menamakannya Geedo.",
  ui_story_5032_50320702_33_dialog_content = "<size=30>Wow, Merylt berhasil menyelesaikan percakapan lengkap dengan PlayerName!</size>",
  ui_story_5032_50320702_34_dialog_content = "<size=30>Itu kemajuan!</size>",
  ui_story_5032_50320702_35_dialog_content = "<size=30>Mungkin karena Merylt sangat peduli dengan Geedo.</size>",
  ui_story_5032_50320702_36_dialog_content = "<size=30>Mari kita tinggalkan Merylt dan Caelestite untuk tugas itu!</size>",
  ui_story_5032_50320702_37_dialog_content = "(... Kenapa Frimet dan Subli menyeringai padaku?)",
  ui_story_5032_50320702_38_dialog_content = "Maka kita harus...",
  ui_story_5032_50320702_39_dialog_content = "Ugh!",
  ui_story_5032_50320702_40_dialog_content = "Grrr!",
  ui_story_5032_50320702_41_dialog_content = "Rainbow!",
  ui_story_5032_50320702_42_dialog_content = "Rainbow!",
  ui_story_5032_50320702_43_dialog_content = "Itu datang dari tempat Rainbow berada!",
  ui_story_5032_50320702_44_dialog_content = "Ah, Merylt dan saudara perempuannya sedang menuju ke sana!",
  ui_story_5032_50320702_45_dialog_content = "Ayo pergi juga, PlayerName!",
  ui_story_5032_50320702_46_dialog_content = "Tentu!",
  ui_story_5032_50320702_47_dialog_content = "Fia, Ciel, kamu baik-baik saja?",
  ui_story_5032_50320702_48_dialog_content = "Fia, dimana Rainbow?",
  ui_story_5032_50320702_49_dialog_content = "Um... Aku di sini.",
  ui_story_5032_50320702_50_dialog_content = "... Hah? A-Apa mata yang besar!",
  ui_story_5032_50320702_51_dialog_content = "Apa itu?",
  ui_story_5032_50320702_52_dialog_content = "Yah, kurasa itu Geedo.",
  ui_story_5032_50320702_53_dialog_content = "Eh? Geedo?",
  ui_story_5032_50320702_54_dialog_content = "Orang ini jauh lebih besar. Bagaimana bisa Geedo?",
  ui_story_5032_50320702_55_dialog_content = "Seperti ini... Aku melihat Eclipsite mengangkat botol dan menatap Geedo melaluinya di ruangan ini.",
  ui_story_5032_50320702_56_dialog_content = "Aku datang untuk menghajarnya, tapi pengecut ini hanya membuang dan menghancurkan botolnya karena takut.",
  ui_story_5032_50320702_57_dialog_content = "Kemudian kilatan muncul dari Geedo, dan inilah yang saya lihat ketika saya bisa melihat lagi...",
  ui_story_5032_50320702_58_dialog_content = "H-Bagaimana bisa?",
  ui_story_5032_50320702_59_dialog_content = "Ahh...",
  ui_story_5032_50320702_60_dialog_content = "Hei, berhenti bergerak! Anda memadati saya!",
  ui_story_5032_50320702_61_dialog_content = "...",
  ui_story_5032_50320702_62_dialog_content = "Hah? Itu berhenti! Apakah Eclipsite ini mengerti apa yang dikatakan Rainbow?",
  ui_story_5032_50320702_63_dialog_content = "I-Sepertinya pingsan?",
  ui_story_5032_50320702_64_dialog_content = "Um, aku bertanya-tanya mengapa Eclipsite ini sepertinya menderita.",
  ui_story_5032_50320702_65_dialog_content = "Itu memegang kepalanya dan mengerang, membuat ruang kecil itu semakin sempit.",
  ui_story_5032_50320702_66_dialog_content = "Tapi aku agak terikat saat ini juga. Kalau tidak, saya akan dengan senang hati menyingkirkannya dari kesengsaraannya segera.",
  ui_story_5032_50320702_67_dialog_content = "Er... Aku senang kau selamat, Rainbow.",
  ui_story_5032_50320702_68_dialog_content = "Bagaimanapun, kita perlu mencari cara untuk mengeluarkannya dari sini dan cepat.",
  ui_story_5032_50320702_69_dialog_content = "Betul sekali. Punggung Rainbow masih terluka...",
  ui_story_5032_50320702_70_dialog_content = "*Menangis* Tolong cepat! Ini semakin ketat dan ketat di sini!",
  ui_story_5032_50320702_71_dialog_content = "B-Tidak bisakah kamu mencoba berkomunikasi dengan Geedo, Fia?",
  ui_story_5032_50320702_72_dialog_content = "Hah?",
  ui_story_5032_50320702_73_dialog_content = "Oh ya! Anda dapat memberitahu Geedo untuk berhenti tumbuh, bukan Fia?",
  ui_story_5032_50320702_74_dialog_content = "Cepat, sebelum Rainbow diratakan menjadi pancake!",
  ui_story_5032_50320702_75_dialog_content = "Tidak, tunggu, ada Eclipsite di sana juga... Jadi mungkin sandwich Rainbow-and-Eclipsite, bukannya pancake?",
  ui_story_5032_50320702_76_dialog_content = "Argh... Kedengarannya tidak menggugah selera sama sekali.",
  ui_story_5032_50320702_77_dialog_content = "Oke, saya akan mencobanya!",
  ui_story_5032_50320702_78_dialog_content = "Um... H-Halo, Geedo.",
  ui_story_5032_50320702_79_dialog_content = "Bisakah kamu, uh... Kembali ke ukuran semula?",
  ui_story_5032_50320702_80_dialog_content = "Eep! Eep!",
  ui_story_5032_50320702_81_dialog_content = "T-Tidak?",
  ui_story_5032_50320702_82_dialog_content = "Tapi kenapa?!",
  ui_story_5032_50320702_83_dialog_content = "Eep-eep-eep!",
  ui_story_5032_50320702_84_dialog_content = "Begitu... Jadi kamu ingin sedikit meregangkan tubuh karena terus-menerus mempertahankan bentuk tubuhmu yang lebih kecil tidak nyaman?",
  ui_story_5032_50320702_85_dialog_content = "Tapi tahukah Anda bahwa jika Anda tidak berhenti tumbuh, Anda akan menyakiti orang yang menyelamatkan Anda?",
  ui_story_5032_50320702_86_dialog_content = "Eep?",
  ui_story_5032_50320702_87_dialog_content = "Betul sekali! Rainbow di sini tidak bisa mengubah ukuran tubuhnya semampumu!",
  ui_story_5032_50320702_88_dialog_content = "... Eep-eep.",
  ui_story_5032_50320702_89_dialog_content = "Ah! Jadi Anda bersedia bekerja sama?",
  ui_story_5032_50320702_90_dialog_content = "Teman-teman! Carikan aku botol kosong dan isi dengan air!",
  ui_story_5032_50320702_91_dialog_content = "Jenis seperti yang digunakan untuk memegang Geedo sebelumnya!",
  ui_story_5032_50320702_92_dialog_content = "Siap!",
  ui_story_5032_50320702_93_dialog_content = "Untung kita belum memilah dan membuang sampah dari festival, ya?",
  ui_story_5032_50320702_94_dialog_content = "Itu hanya karena kau malas, Subli! Pemimpin sirkus menugaskan ANDA untuk mengurus sampah tiga hari yang lalu!",
  ui_story_5032_50320702_95_dialog_content = "Heee! Semuanya berhasil pada akhirnya!",
  ui_story_5032_50320702_96_dialog_content = "Apakah ini akan berhasil, Fia?",
  ui_story_5032_50320702_97_dialog_content = "Eep! Eep!",
  ui_story_5032_50320702_98_dialog_content = "Geedo bilang iya! Apa yang kita lakukan selanjutnya?",
  ui_story_5032_50320702_99_dialog_content = "Eep.",
  ui_story_5032_50320702_100_dialog_content = "Arahkan botol ke Anda?",
  ui_story_5032_50320702_101_dialog_content = "Begini?",
  ui_story_5032_50320702_102_dialog_content = "Eep!",
  ui_story_5032_50320702_103_dialog_content = "Ahh!",
  ui_story_5032_50320702_104_dialog_content = "Geedo benar-benar pas di botol!",
  ui_story_5032_50320702_105_dialog_content = "I-Itu luar biasa!",
  ui_story_5032_50320702_106_dialog_content = "Fiuh... aku terselamatkan!",
  ui_story_5032_50320702_107_dialog_content = "Terima kasih, Fia. Kamu adalah pahlawan ku!",
  ui_story_5032_50320702_108_dialog_content = "Graagh!",
  ui_story_5032_50320702_109_dialog_content = "Ups! Hampir melupakanmu...",
  ui_story_5032_50320702_110_dialog_content = "Graagh?",
  ui_story_5032_50320702_111_dialog_content = "Kita melewati masa-masa sulit bersama, temanku... Tapi sepertinya di sinilah persahabatan kita berakhir.",
  ui_story_5032_50320702_112_dialog_content = "Sekarang mati!",
  ui_story_5032_50320702_113_dialog_content = "Graagh!",
  ui_story_5032_50320702_114_dialog_content = "Orang ini mendapatkan gigitannya kembali segera setelah Geedo kembali ke botol, ya?",
  ui_story_5032_50320702_115_dialog_content = "Tunggu ... Sekarang setelah Anda menyebutkannya ...",
  ui_story_5032_50320702_116_dialog_content = "<size=45>Oh! PlayerName, semuanya, dengarkan!</size>",
  ui_story_5032_50320702_117_dialog_content = "Ahhhh! J-Jangan mulai berteriak seperti itu! Kami di sini!",
  ui_story_5032_50320702_118_dialog_content = "Tiba-tiba aku teringat sesuatu yang dikatakan tuanku tentang Cloudwhale...",
  ui_story_5032_50320702_119_dialog_content = "\"Kekuatannya menyebabkan Eclipsites meringkuk ketakutan, dan Lumina-nya dapat menghalau Aliran Gelap yang paling tebal sekalipun!\"",
  ui_story_5032_50320702_120_dialog_content = "Mungkinkah Geedo itu...",
  ui_story_5032_50320702_121_dialog_content = "Apakah Cloudwhale yang kita cari selama ini?",
  ui_story_5032_50320702_122_dialog_content = "Itu mungkin! Lumina Geedo menjadi jauh lebih sulit untuk dideteksi setelah menyusut ke ukurannya saat ini.",
  ui_story_5032_50320702_123_dialog_content = "Ini mungkin alasan tuanmu kehilangan jejak Cloudwhale dan mengira itu dalam bahaya, Fia!",
  ui_story_5032_50320702_124_dialog_content = "Jika Geedo benar-benar Cloudwhale...",
  ui_story_5032_50320702_125_dialog_content = "Kemudian menurut tuanku, itu mungkin bisa menyelamatkan kita!",
  ui_story_5032_50320702_126_dialog_content = "Kekuatan Geedo mampu memperlambat pergerakan Eclipsite tadi, menjadikannya sasaran empuk!",
  ui_story_5032_50320702_127_dialog_content = "Itu berarti mungkin bisa melakukan hal yang sama pada Eclipsites lainnya!",
  ui_story_5032_50320702_128_dialog_content = "Jika kita bisa membawa Geedo ke suatu tempat yang cukup besar untuk mengubahnya kembali ke ukuran normalnya... Kekuatannya mungkin akan menekan Eclipsites di area yang lebih luas lagi!",
  ui_story_5032_50320702_129_dialog_content = "Geedo datang dari laut, kan? Bagaimana jika kita membawanya kembali ke sana?",
  ui_story_5032_50320702_130_dialog_content = "Kamu benar, PlayerName! Melihat? Bahkan Anda bisa mendapatkan ide bagus sesekali!",
  ui_story_5032_50320702_131_dialog_content = "Tapi kita sudah menutup setiap jendela di sini...",
  ui_story_5032_50320702_132_dialog_content = "Untuk membukanya kembali, kita harus menunggu sampai sistem mesin Emerald diperbaiki.",
  ui_story_5032_50320702_133_dialog_content = "Dan menurut Subli, dek masih merangkak dengan Eclipsites. Memaksa kami melewati mereka akan sangat berbahaya.",
  ui_story_5032_50320702_134_dialog_content = "Bisa minta konfirmasi ke Geedo, Fia? Kita perlu tahu apakah itu benar-benar Cloudwhale dan memiliki kekuatan seperti ini.",
  ui_story_5032_50320702_135_dialog_content = "Aku... Aku tidak punya cara untuk memastikannya. Maaf...",
  ui_story_5032_50320702_136_dialog_content = "T-Tapi intuisiku memberitahuku bahwa Geedo benar-benar Cloudwhale!",
  ui_story_5032_50320702_137_dialog_content = "Itu sebabnya... Itu sebabnya saya pikir kita masih harus mencobanya!",
  ui_story_5032_50320702_138_dialog_content = "Hmm... Bagaimana menurutmu, PlayerName?",
  ui_story_5032_50320702_139_dialog_content = "Aku…",
  ui_story_5032_50320702_140_dialog_content = "Saya setuju. Mari kita coba.",
  ui_story_5032_50320702_141_dialog_content = "Meski Fia bisa jadi tidak dewasa... Dan keras kepala... Dan bahkan terkadang tidak bisa diandalkan...",
  ui_story_5032_50320702_142_dialog_content = "H-Hei! Apakah ini caramu untuk membalasku, PlayerName?!",
  ui_story_5032_50320702_143_dialog_content = "Terlepas dari semua itu, Fia dan saya telah melalui banyak situasi berbahaya bersama, dan saya memiliki keyakinan penuh pada keterampilan dan keahliannya sebagai seorang ahli ekstrozoologi.",
  ui_story_5032_50320702_144_dialog_content = "Itu sebabnya aku bersedia mempercayai intuisinya kali ini.",
  ui_story_5032_50320702_145_dialog_content = "Pergi ke dek akan menjadi hukuman mati... Tapi jika Geedo benar-benar Cloudwhale, maka kita mungkin bisa membalikkan keadaan!",
  ui_story_5032_50320702_146_dialog_content = "PlayerName…",
  ui_story_5032_50320702_147_dialog_content = "Sehat,PlayerName, jika Anda memercayai penilaian Fia, maka saya juga.",
  ui_story_5032_50320702_148_dialog_content = "Aku akan naik ke geladak bersama kalian berdua.",
  ui_story_5032_50320702_149_dialog_content = "Vice!",
  ui_story_5032_50320702_150_dialog_content = "Kalian membuat beberapa argumen yang meyakinkan, kau tahu?",
  ui_story_5032_50320702_151_dialog_content = "Daripada menaruh semua harapan kita pada orang lain... Lebih baik masuk ke dalam permainan sendiri dan meningkatkan peluang sukses semua orang!",
  ui_story_5032_50320702_152_dialog_content = "Selain itu, duduk di sekitar sini tidak akan menghentikan Emerald dari kehancuran dalam waktu dekat.",
  ui_story_5032_50320702_153_dialog_content = "Rainbow... Terima kasih! Terima kasih semua untuk percaya padaku!",
  ui_story_5032_50320702_154_dialog_content = "Haha, tidak perlu banyak untuk membuat Anda merasa emosional, bukan Fia?",
  ui_story_5032_50320702_155_dialog_content = "Baiklah, itu sudah cukup... Mari kita mulai merencanakan langkah kita selanjutnya!",
  ui_story_5032_50320702_156_dialog_content = "Saya yakin akan ada lebih banyak Eclipsites di geladak daripada yang bisa kita bayangkan...",
  ui_story_5032_50320801_1_dialog_content = "Putri Carleen! Eclipsite level tinggi telah muncul di dekat posisi pertahanan sisi kiri ketiga kita! Mereka meminta bala bantuan!",
  ui_story_5032_50320801_2_dialog_content = "Kirim skuadron gerilya kelima untuk membantu mereka.",
  ui_story_5032_50320801_3_dialog_content = "The Eclipsites tampaknya menurun jumlahnya dari posisi pertahanan sisi kiri ketujuh dan seterusnya.",
  ui_story_5032_50320801_4_dialog_content = "Beritahu mereka untuk mengirim pengintai untuk menilai situasi, dan menugaskan bala bantuan apa pun yang bisa mereka berikan ke titik pertahanan pusat.",
  ui_story_5032_50320801_5_dialog_content = "Paham!",
  ui_story_5032_50320801_6_dialog_content = "Bagaimana proses evakuasi kota?",
  ui_story_5032_50320801_7_dialog_content = "Kelompok warga sipil pertama telah dikawal dengan aman ke tempat penampungan, Putri Carleen.",
  ui_story_5032_50320801_8_dialog_content = "Kami masih dalam proses mengevakuasi warga lainnya.",
  ui_story_5032_50320801_9_dialog_content = "Kami juga telah memeriksa tempat penampungan, dan semuanya tampak beres.",
  ui_story_5032_50320801_10_dialog_content = "Oke. Saya mengerti.",
  ui_story_5032_50320801_11_dialog_content = "Lanjutkan memegang garis! Kami baru saja menerima komunikasi dari Lumopolis yang mengatakan bahwa bala bantuan akan segera tiba!",
  ui_story_5032_50320801_12_dialog_content = "Paham!",
  ui_story_5032_50320801_13_dialog_content = "Saya harus mengatakan, sejujurnya saya terkejut melihat betapa lancarnya evakuasi ini. Kelompok pengungsi pertama mencapai tempat penampungan dalam waktu yang singkat...",
  ui_story_5032_50320801_14_dialog_content = "Pada tingkat ini, jumlah korban harus jauh lebih rendah dari yang saya perkirakan.",
  ui_story_5032_50320801_15_dialog_content = "Memang. Dan kami harus berterima kasih kepada Laird Elvis untuk ini.",
  ui_story_5032_50320801_16_dialog_content = "Laird melakukan latihan evakuasi reguler, sehingga orang tahu persis bagaimana harus bereaksi selama keadaan darurat.",
  ui_story_5032_50320801_17_dialog_content = "Saya tidak pernah berpikir saya akan melihat hari ketika latihan akhirnya digunakan.",
  ui_story_5032_50320801_18_dialog_content = "Latihan evakuasi?",
  ui_story_5032_50320801_19_dialog_content = "Ya, Yang Mulia. Laird Elvis bersiap menghadapi bahaya bahkan di masa damai, dan memberikan perhatian khusus pada pemeliharaan sistem dan fasilitas ini.",
  ui_story_5032_50320801_20_dialog_content = "Meskipun tempat perlindungan tersebut tidak digunakan selama bertahun-tahun, kami melakukan pemeliharaan setidaknya setahun sekali atas instruksi Laird Elvis.",
  ui_story_5032_50320801_21_dialog_content = "<size=30>Apakah ini bagian dari rencanamu juga, Elvis?</size>",
  ui_story_5032_50320801_22_dialog_content = "Saya mohon maaf, Anda ...",
  ui_story_5032_50320801_23_dialog_content = "A-Hati-hati, Putri Carleen! Sebuah Eclipsite sedang menyerang Anda!",
  ui_story_5032_50320801_24_dialog_content = "Aahhhh!",
  ui_story_5032_50320801_25_dialog_content = "Ahhhh!",
  ui_story_5032_50320801_26_dialog_content = "Semuanya tetap tenang! Jangan panik!",
  ui_story_5032_50320801_27_dialog_content = "M... Saya minta maaf, Yang Mulia!",
  ui_story_5032_50320801_28_dialog_content = "Anda berada dalam bahaya karena kami tidak dapat menghentikannya...",
  ui_story_5032_50320801_29_dialog_content = "Saya baik-baik saja. Sekarang kembali ke posting Anda.",
  ui_story_5032_50320801_30_dialog_content = "Jangan biarkan formalitas seperti ini mengalihkan perhatian Anda di medan perang.",
  ui_story_5032_50320801_31_dialog_content = "Paham!",
  ui_story_5032_50320801_32_dialog_content = "Ah! B-Bantuan! Bala bantuan!",
  ui_story_5032_50320801_33_dialog_content = "Beberapa Eclipsites telah menembus garis pertahanan kita, dan menuju ke kota!",
  ui_story_5032_50320801_34_dialog_content = "Graagh!!",
  ui_story_5032_50320801_35_dialog_content = "Itu buruk. Kami tidak memiliki tentara untuk cadangan ...",
  ui_story_5032_50320801_36_dialog_content = "Ikutlah denganku!",
  ui_story_5032_50320801_37_dialog_content = "Y-Ya, Yang Mulia!",
  ui_story_5032_50320801_38_dialog_content = "Ice Blossom!",
  ui_story_5032_50320801_39_dialog_content = "Graagh!",
  ui_story_5032_50320801_40_dialog_content = "*Batuk*...",
  ui_story_5032_50320801_41_dialog_content = "Putri Carleen! Apa kau terluka?!",
  ui_story_5032_50320801_42_dialog_content = "Tidak, aku baik-baik saja. Hanya saja... Aliran Gelap di udara menjadi sangat padat bahkan indraku mulai terpengaruh.",
  ui_story_5032_50320801_43_dialog_content = "Mengingat keadaan pasukan kita, pertempuran yang berlarut-larut sangat tidak menguntungkan.",
  ui_story_5032_50320801_44_dialog_content = "Graagh!",
  ui_story_5032_50320801_45_dialog_content = "Lebih banyak Eclipsites menerobos!",
  ui_story_5032_50320801_46_dialog_content = "Pasukan garis depan kita mulai berkurang, juga...",
  ui_story_5032_50320801_47_dialog_content = "J-Jangan menyerah! Masih ada warga sipil di belakang kita!",
  ui_story_5032_50320801_48_dialog_content = "K-Kita tidak bisa membiarkan mereka menerobos garis pertahanan ini!",
  ui_story_5032_50320801_49_dialog_content = "Siap!",
  ui_story_5032_50320801_50_dialog_content = "Aahhhh!",
  ui_story_5032_50320801_51_dialog_content = "A-Apa ini?!",
  ui_story_5032_50320801_52_dialog_content = "Sebuah Eclipsite tingkat tinggi! Eclipsite tingkat tinggi lainnya telah muncul!",
  ui_story_5032_50320801_53_dialog_content = "Jangan merusak formasi, semuanya! Fokus pada-!",
  ui_story_5032_50320801_54_dialog_content = "Aduh!",
  ui_story_5032_50320801_55_dialog_content = "C-Kapten!",
  ui_story_5032_50320801_56_dialog_content = "gerhana ini...",
  ui_story_5032_50320801_57_dialog_content = "Tidak berguna. Prajurit normal tidak memiliki kesempatan untuk melawannya.",
  ui_story_5032_50320801_58_dialog_content = "Tarik kembali untuk saat ini, dan berurusan dengan Eclipsites lainnya! Jangan biarkan satu pun memasuki kota sampai evakuasi selesai!",
  ui_story_5032_50320801_59_dialog_content = "Serahkan Eclipsite ini padaku!",
  ui_story_5032_50320801_60_dialog_content = "Lady Carleen!",
  ui_story_5032_50320801_61_dialog_content = "Aahhhhhh!",
  ui_story_5032_50320802_1_dialog_content = "Ugh!",
  ui_story_5032_50320802_2_dialog_content = "Tubuhku masih belum pulih sepenuhnya. Kekuatan saya tidak bisa mengikuti ...",
  ui_story_5032_50320802_3_dialog_content = "Belum lagi, Darkflow begitu padat, bahkan tubuhku terasa berat.",
  ui_story_5032_50320802_4_dialog_content = "Aahhhh!",
  ui_story_5032_50320802_5_dialog_content = "Bahkan jika aku tidak bisa menghentikan Darkflow menguasai kota... Aku tidak bisa membiarkan Eclipsite ini melewati sini!",
  ui_story_5032_50320802_6_dialog_content = "Saya tidak punya pilihan. Aku tahu aku berjanji pada Vice...",
  ui_story_5032_50320802_7_dialog_content = "Anda harus tenang untuk sementara waktu, Carleen. Jangan terburu-buru pemulihan Anda.",
  ui_story_5032_50320802_8_dialog_content = "Pingsan karena Lumina terkuras bisa terjadi jika Anda belum terbiasa.",
  ui_story_5032_50320802_9_dialog_content = "Jadi jangan memaksakan diri dengan kekuatan barumu sampai kamu pulih, oke?",
  ui_story_5032_50320802_10_dialog_content = "Itu terdengar seperti sesuatu Carleen akan melakukan.",
  ui_story_5032_50320802_11_dialog_content = "Oh, begitu rupanya.",
  ui_story_5032_50320802_12_dialog_content = "Aku akan menjaga diriku sendiri. Yakinlah.",
  ui_story_5032_50320802_13_dialog_content = "Maafkan aku, Vice.",
  ui_story_5032_50320802_14_dialog_content = "Tetapi jika saya mundur sekarang, lebih banyak orang hanya akan terluka.",
  ui_story_5032_50320802_15_dialog_content = "*Tarik napas* Konsentrasi dan tarik napas dalam-dalam...",
  ui_story_5032_50320802_16_dialog_content = "Aahhhh!",
  ui_story_5032_50320802_17_dialog_content = "Cahaya Indah!",
  ui_story_5032_50320802_18_dialog_content = "Aahhhhhh!",
  ui_story_5032_50320802_19_dialog_content = "Voila!",
  ui_story_5032_50320802_20_dialog_content = "Ugh!",
  ui_story_5032_50320802_21_dialog_content = "Seharusnya aku tahu kekuatan baruku tidak akan mudah dikendalikan...",
  ui_story_5032_50320802_22_dialog_content = "Apakah masih sulit bagi saya untuk memaksanya?",
  ui_story_5032_50320802_23_dialog_content = "Aahhhh!",
  ui_story_5032_50320802_24_dialog_content = "Tidak bisa sepenuhnya menghindari yang satu ini!",
  ui_story_5032_50320802_25_dialog_content = "Tapi aku masih bisa bertarung hanya dengan kaki terluka!",
  ui_story_5032_50320802_26_dialog_content = "<color=#e8d9bb>Pranggg...</color>",
  ui_story_5032_50320802_27_dialog_content = "Fiuh... Untung aku berhasil tepat waktu, kalau tidak aku harus menjelaskan semua ini pada Schwartz dan para bangsawan lainnya. Itu tidak akan menyenangkan, sama sekali ...",
  ui_story_5032_50320802_28_dialog_content = "Maafkan aku, Putri Carleen! Gaya bertarung macam apa itu?",
  ui_story_5032_50320802_29_dialog_content = "Apakah kamu tidak khawatir tentang kami? Kami akan berada dalam masalah besar jika sesuatu terjadi pada Anda, Anda tahu!",
  ui_story_5032_50320802_30_dialog_content = "Hah?",
  ui_story_5032_50320802_31_dialog_content = "I-Ini kamu!",
  ui_story_5032_50320802_32_dialog_content = "Tanggapan macam apa itu?",
  ui_story_5032_50320802_33_dialog_content = "Aku baru saja menyelamatkan hidupmu! Anda bisa melakukan lebih baik dari itu!",
  ui_story_5032_50320802_34_dialog_content = "Ayolah, setidaknya \"terima kasih\" akan menyenangkan.",
  ui_story_5032_50320802_35_dialog_content = "… Terima kasih.",
  ui_story_5032_50320802_36_dialog_content = "Apakah Anda terluka, Putri Carleen?",
  ui_story_5032_50320802_37_dialog_content = "Aku baik-baik saja, Tn. Loewe.",
  ui_story_5032_50320802_38_dialog_content = "Meskipun, jika kalian berdua bisa mencapai tempat ini, maka itu berarti...",
  ui_story_5032_50320802_39_dialog_content = "Benar, Putri Carleen. Saya telah menemukan cara untuk mengaktifkan kembali Windstone.",
  ui_story_5032_50320802_40_dialog_content = "Atas nama semua Harbour City dan orang-orangnya, izinkan saya mengucapkan terima kasih yang tulus.",
  ui_story_5032_50320802_41_dialog_content = "Terima kasih telah membela tentara kami, rakyat kami, dan rumah kami.",
  ui_story_5032_50320802_42_dialog_content = "Tidak perlu formalitas seperti itu. Saya hanya menjalankan tugas saya.",
  ui_story_5032_50320802_43_dialog_content = "Anda tanpa pamrih mempertaruhkan hidup Anda demi Harbour City dan warganya.",
  ui_story_5032_50320802_44_dialog_content = "Ketika saya memikirkan ketidakpercayaan saya sebelumnya pada Anda, itu memenuhi saya dengan rasa malu yang mendalam.",
  ui_story_5032_50320802_45_dialog_content = "Setidaknya, terimalah terima kasihku yang tulus.",
  ui_story_5032_50320802_46_dialog_content = "Hei, Loew! Berhenti berdiri di sekitar sudah!",
  ui_story_5032_50320802_47_dialog_content = "Mengapa saya satu-satunya yang melakukan semua pekerjaan sekarang?",
  ui_story_5032_50320802_48_dialog_content = "Dapatkan di sini dan bantu saya membersihkan sisa Eclipsites kotor ini!",
  ui_story_5032_50320802_49_dialog_content = "Aku bukan satu-satunya yang ditugaskan untuk melindungi putri kecil, lho!",
  ui_story_5032_50320802_50_dialog_content = "...",
  ui_story_5032_50320802_51_dialog_content = "... Anda tidak perlu berteriak.",
  ui_story_5032_50320802_52_dialog_content = "Laird Elvis, situasinya telah memburuk jauh di luar dugaanku.",
  ui_story_5032_50320802_53_dialog_content = "Saya telah mengirim kabar ke Lumopolis, tetapi saya tidak tahu kapan bala bantuan mereka akan tiba.",
  ui_story_5032_50320802_54_dialog_content = "Aliran Gelap di udara juga menjadi sangat padat. Pada tingkat ini, kehidupan semua orang akan dalam bahaya.",
  ui_story_5032_50320802_55_dialog_content = "Terlepas dari sejumlah Eclipsites yang telah kami kalahkan, Darkflow masih menggantung di udara di atas Harbour City...",
  ui_story_5032_50320802_56_dialog_content = "Kita tidak punya banyak waktu lagi. Aku serahkan Windstone dan segelnya padamu, Elvis.",
  ui_story_5032_50320802_57_dialog_content = "Saya mengerti, Putri Carleen. Anda membuat keputusan yang tepat.",
  ui_story_5032_50320802_58_dialog_content = "Tapi yakinlah, sekarang aku telah menemukan cara untuk mengaktifkan Windstone... Semuanya akan segera berakhir.",
  ui_story_5032_50320802_59_dialog_content = "Apa sebenarnya metode yang Anda bicarakan ini? Apakah ada yang bisa saya lakukan untuk membantu?",
  ui_story_5032_50320802_60_dialog_content = "Serahkan saja sisanya padaku, Yang Mulia.",
  ui_story_5032_50320802_61_dialog_content = "Yang saya minta hanyalah Anda terus memimpin pertahanan kami untuk waktu yang lama.",
  ui_story_5032_50320802_62_dialog_content = "Saya mengerti. Saya akan terus memimpin para prajurit dari sini, dan memberi Anda waktu sebanyak yang Anda butuhkan.",
  ui_story_5032_50320802_63_dialog_content = "Saya berterima kasih atas kepercayaan Anda, dan semua yang telah Anda lakukan untuk Harbour City, Yang Mulia.",
  ui_story_5032_50320802_64_dialog_content = "Ada satu hal lagi, meskipun mungkin terdengar tidak adil, mengingat situasinya... Saya dengan rendah hati meminta Anda mengingat sumpah Anda sebelumnya.",
  ui_story_5032_50320802_65_dialog_content = "Bahwa Anda akan menjaga rahasia saya dan Harbour City aman, begitu bala bantuan dari Lumopolis tiba.",
  ui_story_5032_50320802_66_dialog_content = "Saya telah berjanji kepada Anda bahwa saya akan merahasiakan informasi apa pun mengenai Windstone, dan saya tidak berniat melanggar janji itu.",
  ui_story_5032_50320802_67_dialog_content = "Terima kasih, Yang Mulia. Dengan karakter mulia dan dapat dipercaya Anda, saya sepenuhnya yakin bahwa Anda akan menjadi penguasa yang luar biasa suatu hari nanti.",
  ui_story_5032_50320802_68_dialog_content = "Nah, bolehkah saya bertanya apakah Anda tahu di mana Jeno sekarang?",
  ui_story_5032_50320802_69_dialog_content = "Jeno? Dia harus berada di posisi pertahanan kelima tepat di depan.",
  ui_story_5032_50320802_70_dialog_content = "Apakah Anda membutuhkan dia untuk sesuatu?",
  ui_story_5032_50320802_71_dialog_content = "Memang. Bisakah Anda mengirim pasukan tambahan untuk memperkuat posisinya saat ini? Saya khawatir saya perlu menariknya dari garis depan untuk beberapa waktu.",
  ui_story_5032_50320802_72_dialog_content = "Aku tahu.",
  ui_story_5032_50320802_73_dialog_content = "Baiklah, izinkan saya untuk mengucapkan terima kasih yang tulus lagi.",
  ui_story_5032_50320802_74_dialog_content = "Selain itu, saya ingin meminta maaf atas cedera atau korban yang mungkin Anda dan sekutu Anda derita.",
  ui_story_5032_50320802_75_dialog_content = "Mengenalmu adalah salah satu kehormatan terbesar dalam hidupku, Putri Carleen. Anda akan selamanya dikenal sebagai teman baik Harbour City.",
  ui_story_5032_50320802_76_dialog_content = "<size=30>Dan sekarang, saya akhirnya bisa mulai... untuk menebus kesalahan yang telah saya buat.</size>",
  ui_story_5032_50320802_77_dialog_content = "Permisi.",
  ui_story_5032_50320802_78_dialog_content = "... Elvis.",
  ui_story_5032_50320802_79_dialog_content = "Hmm? Apakah ada hal lain di pikiran Anda, Yang Mulia?",
  ui_story_5032_50320802_80_dialog_content = "... Tidak, tidak ada.",
  ui_story_5032_50320802_81_dialog_content = "Tolong hati-hati.",
  ui_story_5032_50320802_82_dialog_content = "Perhatian Anda sangat kami hargai, Putri Carleen.",
  ui_story_5032_50320802_83_dialog_content = "Saya akan tetap waspada.",
  ui_story_5032_50320901_1_dialog_content = "Baiklah, mari kita bahas rencananya untuk terakhir kalinya!",
  ui_story_5032_50320901_2_dialog_content = "Dalam beberapa menit, Subli akan membuka kunci pintu ke geladak. Ketika dia melakukannya, \"Geedo Squad\" akan menyerang.",
  ui_story_5032_50320901_3_dialog_content = "PlayerName dan Fia akan berada di pusat kami, dan bertanggung jawab untuk memerintah dan melindungi Geedo.",
  ui_story_5032_50320901_4_dialog_content = "Kyllo, Vice, Merylt, dan aku akan mengepung mereka dan menangkis semua penyerang.",
  ui_story_5032_50320901_5_dialog_content = "Sementara itu, Ciel, Frimet, dan Subli akan tetap berada di bawah dek untuk mengunci pintu di belakang kami dan melanjutkan pencarian hewan lain.",
  ui_story_5032_50320901_6_dialog_content = "Ada pertanyaan?",
  ui_story_5032_50320901_7_dialog_content = "Tidak!",
  ui_story_5032_50320901_8_dialog_content = "T-Tidak ada pertanyaan di sini.",
  ui_story_5032_50320901_9_dialog_content = "*Meneguk*",
  ui_story_5032_50320901_10_dialog_content = "Suara yang familiar... Apa kamu merasa gugup, Fia?",
  ui_story_5032_50320901_11_dialog_content = "NNN-Tidak sama sekali!!",
  ui_story_5032_50320901_12_dialog_content = "I-Itu barusan Kyllo menelan, t-bukan aku!",
  ui_story_5032_50320901_13_dialog_content = "lihat?",
  ui_story_5032_50320901_14_dialog_content = "Semuanya akan baik-baik saja, Fia! Anggap saja seperti permainan karnaval itu dan Anda akan baik-baik saja!",
  ui_story_5032_50320901_15_dialog_content = "Bagaimanapun, itu hanya beberapa Eclipsites. Tidak ada yang perlu dikhawatirkan untuk orang-orang seperti kita!",
  ui_story_5032_50320901_16_dialog_content = "Lo, lo!",
  ui_story_5032_50320901_17_dialog_content = "Eh... Oke!",
  ui_story_5032_50320901_18_dialog_content = "<size=30>Kecuali Carleen dan Vice yang melakukan semua pertarungan selama kompetisi...</size>",
  ui_story_5032_50320901_19_dialog_content = "Akankah... akankah aku benar-benar baik-baik saja? Aku sangat gugup...",
  ui_story_5032_50320901_20_dialog_content = "Dan sekarang, tanpa basa-basi lagi... Biarkan putaran permainan berikutnya dimulai!",
  ui_story_5032_50320901_21_dialog_content = "Buka pintunya, Subli!",
  ui_story_5032_50320901_22_dialog_content = "Siap!",
  ui_story_5032_50320902_1_dialog_content = "Bisakah kita benar-benar mengalahkan semua Eclipsites ini?",
  ui_story_5032_50320902_2_dialog_content = "Sepertinya semakin banyak yang muncul di pantai!",
  ui_story_5032_50320902_3_dialog_content = "Aahhhh!",
  ui_story_5032_50320902_4_dialog_content = "Argh! T-Ada lebih banyak lagi yang datang dari sisi kami!",
  ui_story_5032_50320902_5_dialog_content = "Ini sudah berakhir bagi kita, bukan...?",
  ui_story_5032_50320902_6_dialog_content = "Apakah ini bagaimana Harbour City akan jatuh? Aku masih belum memberitahunya kasih sayangku...",
  ui_story_5032_50320902_7_dialog_content = "Jika Anda memiliki kekuatan yang cukup untuk merengek dan mengerang seperti ini, maka Anda masih harus memiliki beberapa perjuangan tersisa di dalam diri Anda.",
  ui_story_5032_50320902_8_dialog_content = "Hah? S-Siapa kamu?!",
  ui_story_5032_50320902_9_dialog_content = "Pergilah, makhluk keji dari kedalaman.",
  ui_story_5032_50320902_10_dialog_content = "Biarkan Kebenaran membimbing Anda menuju kematian yang ditakdirkan!",
  ui_story_5032_50320902_11_dialog_content = "Aahhhhhh!",
  ui_story_5032_50320902_12_dialog_content = "Hai! Itu pemimpin sirkus dari sirkus!",
  ui_story_5032_50320902_13_dialog_content = "Ini Jeno! Dia salah satu teman dekat Laird Elvis!",
  ui_story_5032_50320902_14_dialog_content = "Saya melihat dia bertarung di salah satu posisi bertahan kami sebelumnya. Apakah dia datang untuk membantu kami setelah melihat betapa sedikit dari kami yang tersisa?",
  ui_story_5032_50320902_15_dialog_content = "Kami diselamatkan!",
  ui_story_5032_50320902_16_dialog_content = "Wow, pemimpin sirkus itu sangat kuat! Dia merobek semua Eclipsites itu dalam sekejap mata!",
  ui_story_5032_50320902_17_dialog_content = "Hmph... Menyedihkan.",
  ui_story_5032_50320902_18_dialog_content = "Membiarkan Eclipsites lemah seperti ini membuat Anda takut untuk menyerah, Anda seharusnya malu menyebut diri Anda penjaga Kota Pelabuhan.",
  ui_story_5032_50320902_19_dialog_content = "Jangan lupa semua wajah tersenyum penduduk kota yang mengandalkan Anda untuk melindungi mereka.",
  ui_story_5032_50320902_20_dialog_content = "Orang tuamu, anak-anakmu, teman-temanmu, dan keluargamu... Semuanya dalam bahaya.",
  ui_story_5032_50320902_21_dialog_content = "Temukan keberanian Anda dan kumpulkan diri Anda. Jangan pernah menunjukkan kelemahan semacam ini di depan musuh.",
  ui_story_5032_50320902_22_dialog_content = "Kata-kata bisa sama menghancurkannya dengan senjata dan dapat mengubah arah takdir Anda, serta nasib rekan seperjuangan Anda. Sekarang diam dan fokus pada pertarungan!",
  ui_story_5032_50320902_23_dialog_content = "Paham!",
  ui_story_5032_50320902_24_dialog_content = "Ke yang berikutnya...",
  ui_story_5032_50320902_25_dialog_content = "Pak Jeno!",
  ui_story_5032_50320902_26_dialog_content = "Hmm? Itu kamu...",
  ui_story_5032_50320902_27_dialog_content = "Saya akhirnya menemukan Anda, Pak Jeno!",
  ui_story_5032_50320902_28_dialog_content = "Apa yang kamu lakukan di sini? Dimana Elvis?",
  ui_story_5032_50320902_29_dialog_content = "Aku di sini juga, Jeno.",
  ui_story_5032_50320902_30_dialog_content = "Elvis! Apa kamu baik baik saja?",
  ui_story_5032_50320902_31_dialog_content = "Terlalu berbahaya di sini. Anda harus kembali ke pos komando dan menemukan Carleen.",
  ui_story_5032_50320902_32_dialog_content = "Dia yang bertanggung jawab di sana, jadi seharusnya lebih aman di sisinya...",
  ui_story_5032_50320902_33_dialog_content = "Saya baru saja di pos komando menanyakan Yang Mulia tentang keberadaan Anda Jeno. Itu sebabnya aku datang mencarimu.",
  ui_story_5032_50320902_34_dialog_content = "Mencari saya? Mengapa?",
  ui_story_5032_50320902_35_dialog_content = "Ini ada hubungannya dengan mengaktifkan kembali Windstone.",
  ui_story_5032_50320902_36_dialog_content = "Saya menemukan cara untuk melakukannya, tetapi saya membutuhkan bantuan Anda.",
  ui_story_5032_50320902_37_dialog_content = "Dipahami. Apa yang Anda perlu saya lakukan?",
  ui_story_5032_50320902_38_dialog_content = "Pertama-tama kita harus mundur ke lokasi yang lebih aman, jauh dari kemungkinan gangguan Eclipsite. Saya akan menjelaskan semuanya di jalan.",
  ui_story_5032_50320902_39_dialog_content = "Hmm…",
  ui_story_5032_50320902_40_dialog_content = "Sayangnya, tidak.",
  ui_story_5032_50320902_41_dialog_content = "Jeno...",
  ui_story_5032_50320902_42_dialog_content = "Simpan itu. Ini adalah satu-satunya hal yang saya tolak untuk membantu Anda.",
  ui_story_5032_50320902_43_dialog_content = "Saya tidak tahu dari mana Anda mendapatkan ide untuk melakukan ini ...",
  ui_story_5032_50320902_44_dialog_content = "Tapi siapa pun yang memaksakan Lumina mereka seperti ini kemungkinan besar akan mati.",
  ui_story_5032_50320902_45_dialog_content = "Saya dengan senang hati akan membantu Anda menemukan cara lain, atau bahkan berdiri di sisi Anda dan berjuang sampai napas terakhir saya ...",
  ui_story_5032_50320902_46_dialog_content = "Tapi aku menolak untuk membawamu ke kematianmu seperti ini.",
  ui_story_5032_50320902_47_dialog_content = "Aku tidak meragukan kekuatan persahabatan kita atau keberanianmu, Jeno.",
  ui_story_5032_50320902_48_dialog_content = "Tetapi dalam keadaan yang mengerikan ini, saya khawatir tidak ada pilihan lain yang tersisa bagi kita.",
  ui_story_5032_50320902_49_dialog_content = "Rencana ini akan menghasilkan pengorbanan sekecil mungkin. Sebagai laird dari Harbour City, adalah tugasku untuk membebaskan orang-orangku dari bahaya.",
  ui_story_5032_50320902_50_dialog_content = "Anda pikir kematian Anda akan menjadi \"pengorbanan kecil\"? Apa kepalamu tertembak oleh salah satu mesin yang meledak di lahan tertutup itu?!",
  ui_story_5032_50320902_51_dialog_content = "Apakah Anda tahu betapa berbahayanya jika saya mentransfer sisa Lumina Anda dalam kondisi Anda saat ini?",
  ui_story_5032_50320902_52_dialog_content = "Salah langkah kecil dan Lumina Anda akan benar-benar ditarik!",
  ui_story_5032_50320902_53_dialog_content = "Resikonya memang besar, tapi peluang suksesnya masih kecil, kan?",
  ui_story_5032_50320902_54_dialog_content = "Tolong, Jeno.",
  ui_story_5032_50320902_55_dialog_content = "Saya sangat percaya pada kemampuan Anda untuk mengendalikannya dengan benar.",
  ui_story_5032_50320902_56_dialog_content = "Bagaimanapun, Anda adalah salah satu pesulap dan seniman terhebat.",
  ui_story_5032_50320902_57_dialog_content = "Itu terlalu berbahaya. Saya tidak punya cara untuk menjamin keselamatan Anda.",
  ui_story_5032_50320902_58_dialog_content = "Laird Elvis.",
  ui_story_5032_50320902_59_dialog_content = "Permisi sebentar, Jeno.",
  ui_story_5032_50320902_60_dialog_content = "Ada apa, Pato?",
  ui_story_5032_50320902_61_dialog_content = "Saya sangat menyesal mengganggu percakapan Anda.",
  ui_story_5032_50320902_62_dialog_content = "Tapi Eclipsite tingkat tinggi lain telah muncul. Silakan mundur ke lokasi yang aman untuk saat ini!",
  ui_story_5032_50320902_63_dialog_content = "Tidak ada yang perlu ditakuti, Patou. Selama Jeno ada di sini, aku tidak akan menyakiti.",
  ui_story_5032_50320902_64_dialog_content = "Sekarang ambil tentara apa yang bisa Anda temukan dan perkuat pertahanan kami.",
  ui_story_5032_50320902_65_dialog_content = "Kekuatan Eclipsite tingkat tinggi bisa sangat tidak terduga. Saya akan merasa lebih aman jika Anda berada di garis depan pertahanan kami.",
  ui_story_5032_50320902_66_dialog_content = "Namun…",
  ui_story_5032_50320902_67_dialog_content = "Cepat, Patou. Orang-orang kami membutuhkanmu di garis depan.",
  ui_story_5032_50320902_68_dialog_content = "... Ya, Laird Elvis.",
  ui_story_5032_50320902_69_dialog_content = "Apakah Anda melihat sekarang, Jeno?",
  ui_story_5032_50320902_70_dialog_content = "Banjir Eclipsites yang tak berujung ini akan menenggelamkan pasukan kita yang tersisa lebih cepat daripada nanti.",
  ui_story_5032_50320902_71_dialog_content = "Dan itu belum lagi tentang Aliran Gelap yang semakin intensif ini, yang mengancam akan mencekik siapa pun yang selamat dari serangan gencar.",
  ui_story_5032_50320902_72_dialog_content = "Bala bantuan Putri Carleen sudah habis, dan posisi pertahanan kita jatuh ke Eclipsites satu per satu.",
  ui_story_5032_50320902_73_dialog_content = "Untuk setiap detik yang kita habiskan untuk berdebat, prajurit lain dicabik-cabik oleh Eclipsites.",
  ui_story_5032_50320902_74_dialog_content = "Dan semua penderitaan ini... disebabkan oleh tanganku sendiri.",
  ui_story_5032_50320902_75_dialog_content = "Tetapi Anda tidak tahu bahwa itu akan menjadi seperti ini! Ini bukan salahmu!",
  ui_story_5032_50320902_76_dialog_content = "Hehe. Kesalahan adalah kesalahan, dan seseorang harus bertanggung jawab untuk itu. Bukankah ini salah satu pelajaran pertama yang diajarkan kepada anak bungsu kita?",
  ui_story_5032_50320902_77_dialog_content = "Selain itu, saya masih laird dari Harbour City. Lebih dari segalanya, saya ingin melindunginya, dan orang-orang saya.",
  ui_story_5032_50320902_78_dialog_content = "...",
  ui_story_5032_50320902_79_dialog_content = "Anda pernah berkata bahwa Anda ingin melindungi saya. Ingat?",
  ui_story_5032_50320902_80_dialog_content = "... Iya.",
  ui_story_5032_50320902_81_dialog_content = "Melindungi seseorang tidak hanya berarti menjaga orang itu tetap hidup, Jeno... Terkadang, itu berarti menjaga mimpinya tetap hidup. Tidakkah Anda setuju?",
  ui_story_5032_50320902_82_dialog_content = "Impian saya adalah agar orang-orang di Harbour City kembali ke kehidupan damai dan bahagia yang pernah mereka kenal.",
  ui_story_5032_50320902_83_dialog_content = "Mereka mungkin mengalami lebih banyak rasa sakit di sepanjang jalan dan menulis lebih banyak cerita sedih di halaman sejarah kita.",
  ui_story_5032_50320902_84_dialog_content = "Tapi paling tidak, mereka akan punya tempat untuk disebut rumah... Tempat dimana senyum mereka bisa mekar sekali lagi.",
  ui_story_5032_50320902_85_dialog_content = "Untuk melihat senyum di setiap wajah mereka selalu menjadi impian saya.",
  ui_story_5032_50320902_86_dialog_content = "Jadi saya bertanya sekali lagi, Jeno. Maukah Anda membantu saya menjaga mimpi saya tetap hidup?",
  ui_story_5032_50320902_87_dialog_content = "... Bagaimana Anda bisa melakukan ini padaku?",
  ui_story_5032_50320902_88_dialog_content = "Apa?",
  ui_story_5032_50320902_89_dialog_content = "Kau memaksaku... untuk menodongkan pisau ke tenggorokanmu dan menggunakan semua pembicaraan tentang mimpi dan kebenaran ini untuk membenarkannya.",
  ui_story_5032_50320902_90_dialog_content = "Aku... Maafkan aku, Jeno.",
  ui_story_5032_50320902_91_dialog_content = "Untuk hal-hal yang terjadi bertahun-tahun yang lalu, di Zamrud, dan sekarang juga...",
  ui_story_5032_50320902_92_dialog_content = "Aku benar-benar minta maaf, Jeno... untuk semuanya.",
  ui_story_5032_50320902_93_dialog_content = "Aku tahu aku tidak layak disebut temanmu, apalagi laird Harbour City.",
  ui_story_5032_50320902_94_dialog_content = "Keras kepala dan paranoia sayalah yang menyebabkan semuanya menjadi seperti ini.",
  ui_story_5032_50320902_95_dialog_content = "Anda terseret ke dalam masalah saya juga dan untuk itu... Saya hanya bisa meminta maaf sekali lagi.",
  ui_story_5032_50320902_96_dialog_content = "Tetapi jika saya membiarkan kesempatan ini lolos dari tangan saya dan membiarkan Eclipsites memasuki rumah saya...",
  ui_story_5032_50320902_97_dialog_content = "Saya tidak akan pernah memaafkan diri saya sendiri selama sisa hidup saya yang tidak berharga.",
  ui_story_5032_50320902_98_dialog_content = "Jadi panggil aku egois, panggil aku bodoh, panggil aku sesukamu... Tapi aku mohon... Tolong bantu aku.",
  ui_story_5032_50320902_99_dialog_content = "...",
  ui_story_5032_50320902_100_dialog_content = "*Sigh* Sejak kita masih kecil, aku tidak pernah bisa mengubah pikiranmu... atau menolakmu, dalam hal ini.",
  ui_story_5032_50320902_101_dialog_content = "Saya akan melakukannya, tetapi segera setelah saya mendeteksi sedikit pun bahaya, saya menghentikan seluruh ritual.",
  ui_story_5032_50320902_102_dialog_content = "Heheh... Saya tidak keberatan.",
  ui_story_5032_50320902_103_dialog_content = "Sekarang bagaimana kita harus memulai?",
  ui_story_5032_50321001_1_dialog_content = "Tanah yang disegel telah dihancurkan. Untuk mengaktifkan kembali Windstone, kami hanya memiliki satu metode terakhir.",
  ui_story_5032_50321001_2_dialog_content = "Yaitu, metode yang digunakan oleh nenek moyang kita untuk mengaktifkan Windstone di masa lalu... Sebuah perjanjian baru harus dibuat dengan Windstone.",
  ui_story_5032_50321001_3_dialog_content = "Tapi bagaimana kita akan kekuatan itu?",
  ui_story_5032_50321001_4_dialog_content = "Cadangan daya Windstone hampir seluruhnya habis, itu benar.",
  ui_story_5032_50321001_5_dialog_content = "Mungkin itu hanya bisa dilakukan seperti sebelumnya: dengan menggunakan Lumina dari Aurorian untuk terus mempertahankannya...",
  ui_story_5032_50321001_6_dialog_content = "Kalau dipikir-pikir, aku benar-benar gagal...",
  ui_story_5032_50321001_7_dialog_content = "Tidak... Anda telah melakukan semua yang Anda bisa, Elvis. Ini bukan salahmu.",
  ui_story_5032_50321001_8_dialog_content = "Meski begitu, membicarakan hal ini tidak akan membantu situasi kita. Kita harus menjaga pikiran kita pada Windstone.",
  ui_story_5032_50321001_9_dialog_content = "Untuk mengaktifkan Windstone, leluhur saya menciptakan tanah yang disegel.",
  ui_story_5032_50321001_10_dialog_content = "Melalui tanah yang disegel, Windstone dapat membangun semacam hubungan dengan Aurorian, memungkinkannya untuk mengumpulkan Lumina mereka.",
  ui_story_5032_50321001_11_dialog_content = "* Batuk, batuk * Kemampuan tanah yang disegel ... tidak sepenuhnya berbeda dengan <color=#FFB400>kekuasaan</color> Anda perintah.",
  ui_story_5032_50321001_12_dialog_content = "Anda ingin menggunakan kekuatan saya untuk mensimulasikan efek tanah yang disegel dan mengaktifkan kembali Windstone dengan aman. Itu saja?",
  ui_story_5032_50321001_13_dialog_content = "Benar.",
  ui_story_5032_50321001_14_dialog_content = "... Baiklah, saya akan mengikuti rencana Anda.",
  ui_story_5032_50321001_15_dialog_content = "Tapi seperti yang saya katakan sebelumnya: begitu saya merasakan bahaya sekecil apa pun, saya memutuskan hubungan antara Anda dan Windstone.",
  ui_story_5032_50321001_16_dialog_content = "Baiklah... Aku serahkan sisanya padamu, temanku.",
  ui_story_5032_50321001_17_dialog_content = "Demi Harbour City dan penduduknya, ritual itu harus berhasil!",
  ui_story_5032_50321001_18_dialog_content = "Tutup mata Anda, dan bayangkan diri Anda memegang Batu Angin di tangan Anda...",
  ui_story_5032_50321001_19_dialog_content = "Hmm…",
  ui_story_5032_50321001_20_dialog_content = "Ya, begitu saja. Saya akan memulai transfer, jadi cobalah untuk tidak menolak.",
  ui_story_5032_50321001_21_dialog_content = "Heheh... Aku tidak akan memimpikannya.",
  ui_story_5032_50321001_22_dialog_content = "Membuat koneksi antara Lumina Anda dan Windstone...",
  ui_story_5032_50321001_23_dialog_content = "Ugh... *Batuk, batuk*",
  ui_story_5032_50321001_24_dialog_content = "Baiklah, saya sudah melakukan apa yang Anda minta.",
  ui_story_5032_50321001_25_dialog_content = "Pergilah, Elvis!",
  ui_story_5032_50321001_26_dialog_content = "Batu angin! Mulai reaktivasi!",
  ui_story_5032_50321001_27_dialog_content = "Mendeteksi <color=#FFB400>energi</color> memasukkan...",
  ui_story_5032_50321001_28_dialog_content = "Genotipe Aurorian terdeteksi... Koneksi terjalin. Memulai ekstraksi Lumina...",
  ui_story_5032_50321001_29_dialog_content = "Sekarang yang harus aku lakukan... adalah...",
  ui_story_5032_50321001_30_dialog_content = "Aahhhhhh!",
  ui_story_5032_50321001_31_dialog_content = "Mereka berkumpul di sekitar kita. Apakah mereka merasakan ancaman pengaktifan kembali Windstone?",
  ui_story_5032_50321001_32_dialog_content = "Serahkan Eclipsites ini padaku.",
  ui_story_5032_50321002_1_dialog_content = "Hanya... sedikit lagi...",
  ui_story_5032_50321002_2_dialog_content = "Pengaktifan kembali sistem sedang berlangsung...",
  ui_story_5032_50321002_3_dialog_content = "*Hack* Argh...!",
  ui_story_5032_50321002_4_dialog_content = "Mengapa Windstone menyerap lebih banyak Lumina?!",
  ui_story_5032_50321002_5_dialog_content = "Hentikan pengaktifan kembali, Elvis! Tubuh Anda tidak dapat menangani ketegangan semacam ini!",
  ui_story_5032_50321002_6_dialog_content = "Anda akan mati pada tingkat ini!",
  ui_story_5032_50321002_7_dialog_content = "Tidak ada ... tidak berhenti sekarang ...",
  ui_story_5032_50321002_8_dialog_content = "Tahan dulu! Aku akan memutuskan hubungan antara kamu dan Windstone!",
  ui_story_5032_50321002_9_dialog_content = "Hah!?",
  ui_story_5032_50321002_10_dialog_content = "Elvis, apakah kamu menolak?",
  ui_story_5032_50321002_11_dialog_content = "Tidak... Itu Batu Angin! Itu mengambil alih tautan yang saya buat jadi saya tidak bisa merusaknya!",
  ui_story_5032_50321002_12_dialog_content = "Tapi bagaimana ini bisa terjadi? Jawab aku, Elvis!",
  ui_story_5032_50321002_13_dialog_content = "Sepertinya tidak ada gunanya berbohong padamu lebih jauh.",
  ui_story_5032_50321002_14_dialog_content = "Yang benar adalah bahwa alasan yang disegel melayani dua fungsi.",
  ui_story_5032_50321002_15_dialog_content = "Salah satunya adalah mengizinkan Aurorian menggunakan Lumina untuk membuat koneksi dengan Windstone sehingga mereka dapat mengontrolnya.",
  ui_story_5032_50321002_16_dialog_content = "Yang lainnya adalah mengontrol kecepatan di mana Windstone mengekstrak Lumina... untuk mencegahnya membunuh Aurorian yang mengaktifkannya.",
  ui_story_5032_50321002_17_dialog_content = "Anda menyembunyikan fungsi sekunder lahan tertutup dari saya...",
  ui_story_5032_50321002_18_dialog_content = "Anda tahu bahwa kekuatan saya hanya bisa mensimulasikan fungsi pertama!",
  ui_story_5032_50321002_19_dialog_content = "Aku mencari tinggi dan rendah cara untuk mengaktifkan kembali Windstone... Yang tidak membutuhkan lahan tertutup... Tapi pada akhirnya...",
  ui_story_5032_50321002_20_dialog_content = "Windstone hanya diaktifkan sekali dalam sejarah tertulis. Pengetahuan tentang subjek itu agak terbatas.",
  ui_story_5032_50321002_21_dialog_content = "Satu-satunya pilihanku... adalah mengambil kesempatan...",
  ui_story_5032_50321002_22_dialog_content = "Bahkan jika itu berarti... mengorbankan diriku sendiri.",
  ui_story_5032_50321002_23_dialog_content = "Anda tahu itu akan berakhir seperti ini, bukan?!",
  ui_story_5032_50321002_24_dialog_content = "Maafkan aku... Jeno...",
  ui_story_5032_50321002_25_dialog_content = "Ini adalah... satu-satunya cara lain yang bisa kutemukan...",
  ui_story_5032_50321002_26_dialog_content = "Hanya dengan mengorbankan diriku sendiri dan menawarkan setiap ons terakhir Lumina di tubuhku... aku bisa menjamin pengaktifan kembali Windstone! *Uhuk uhuk*",
  ui_story_5032_50321002_27_dialog_content = "Bagaimana Anda bisa menipu saya seperti ini ?!",
  ui_story_5032_50321002_28_dialog_content = "Itu benar... Aku menipumu lagi.",
  ui_story_5032_50321002_29_dialog_content = "Kenapa... Kenapa aku terus melakukan ini padamu?",
  ui_story_5032_50321002_30_dialog_content = "Saya tidak pernah ingin menyembunyikan apa pun dari Anda ... Tumbuh dewasa adalah hal tersulit yang harus saya lakukan ...",
  ui_story_5032_50321002_31_dialog_content = "Heh... Tapi sekarang... Akhirnya aku bisa menebus kesalahanku...",
  ui_story_5032_50321002_32_dialog_content = "Ini adalah takdirku... begitu juga dengan nasib Modali.",
  ui_story_5032_50321002_33_dialog_content = "Dengan mengaktifkan kembali Windstone, semua Harbour City akan aman sekali lagi...",
  ui_story_5032_50321002_34_dialog_content = "*Batuk-batuk*",
  ui_story_5032_50321002_35_dialog_content = "Elvis...",
  ui_story_5032_50321002_36_dialog_content = "Apakah Anda semacam idiot ?!",
  ui_story_5032_50321002_37_dialog_content = "J-Jeno?!",
  ui_story_5032_50321002_38_dialog_content = "Tanggung jawab melindungi Harbour City bukan milik Anda dan milik Anda sendiri.",
  ui_story_5032_50321002_39_dialog_content = "Jangan lupa bahwa Harbour City dan Emerald... adalah rumahku juga!",
  ui_story_5032_50321002_40_dialog_content = "Anda bukan satu-satunya di atas panggung, jadi berhentilah berpikir bahwa sorotan hanya milik Anda!",
  ui_story_5032_50321002_41_dialog_content = "Tidak, berhenti! Saya tidak ingin menyeret Anda ke dalam ini!",
  ui_story_5032_50321002_42_dialog_content = "Putuskan koneksi Anda!",
  ui_story_5032_50321002_43_dialog_content = "Kita tidak bertemu selama bertahun-tahun... Tidak mudah untuk bertemu akhir-akhir ini, kau tahu...?",
  ui_story_5032_50321002_44_dialog_content = "Anda pikir saya akan membiarkan Anda pergi lagi dengan mudah?",
  ui_story_5032_50321002_45_dialog_content = "Meskipun saya selalu menjadi orang yang pasif dan tidak dewasa ...",
  ui_story_5032_50321002_46_dialog_content = "Saya bersumpah bahwa saya akan melindungi apa yang saya coba lindungi.",
  ui_story_5032_50321002_47_dialog_content = "Aku tidak akan kembali pada kata-kata saya lagi.",
  ui_story_5032_50321002_48_dialog_content = "Jeno...",
  ui_story_5032_50321002_49_dialog_content = "Masukan energi baru terdeteksi. Membuat koneksi...",
  ui_story_5032_50321002_50_dialog_content = "Sudah terlambat sekarang, Elvis. Anda dan saya berada di kapal tenggelam yang sama sekarang.",
  ui_story_5032_50321002_51_dialog_content = "Heh... Heheh... Betapa sukanya kamu melakukan hal seperti ini.",
  ui_story_5032_50321002_52_dialog_content = "Kamu bukan lagi anak kecil yang membutuhkan perlindunganku.",
  ui_story_5032_50321002_53_dialog_content = "Nah... Mari kita lihat trik sulap seperti apa yang kamu tawarkan.",
  ui_story_5032_50321002_54_dialog_content = "Ha... Untuk tindakan terakhirku... Aku akan mengubah kita berdua menjadi sumber kekuatan batu ini...",
  ui_story_5032_50321002_55_dialog_content = "<color=#e8d9bb>Sementara itu, di atas Emerald</color>",
  ui_story_5032_50321002_56_dialog_content = "Aahhhh!",
  ui_story_5032_50321002_57_dialog_content = "Mengapa ada begitu banyak Eclipsites di sini?!",
  ui_story_5032_50321002_58_dialog_content = "T-Ada lebih banyak dari mereka yang memanjat lambung kapal!",
  ui_story_5032_50321002_59_dialog_content = "Perairan penuh dengan Eclipsites! Aku terlalu muda untuk dimakan hidup-hidup!!",
  ui_story_5032_50321002_60_dialog_content = "Gahhhh!!!",
  ui_story_5032_50321002_61_dialog_content = "Fi!",
  ui_story_5032_50321002_62_dialog_content = "Rainbow!",
  ui_story_5032_50321002_63_dialog_content = "Lihat! Tidak ada Eclipsites di haluan kapal! Anda harus pergi ke sana dan melepaskan Geedo!",
  ui_story_5032_50321002_64_dialog_content = "Aku akan memotong jalan untukmu!",
  ui_story_5032_50321002_65_dialog_content = "Aku... Aku harus kuat! Demi Geedo!",
  ui_story_5032_50321002_66_dialog_content = "Graah! Groar!",
  ui_story_5032_50321002_67_dialog_content = "Minggir—!",
  ui_story_5032_50321002_68_dialog_content = "Kami berhasil mencapai haluan! Sekarang saya hanya perlu membuka botolnya!",
  ui_story_5032_50321002_69_dialog_content = "Ugh!",
  ui_story_5032_50321002_70_dialog_content = "Mengapa tutupnya disekrup begitu kencang?!",
  ui_story_5032_50321002_71_dialog_content = "Graaaaaah!",
  ui_story_5032_50321002_72_dialog_content = "Oh tidak! Salah satu dari mereka berhasil melewatinya!",
  ui_story_5032_50321002_73_dialog_content = "Hati-hati, Fia!",
  ui_story_5032_50321002_74_dialog_content = "Waaaah!!!",
  ui_story_5032_50321002_75_dialog_content = "Graaaaaa!",
  ui_story_5032_50321002_76_dialog_content = "Tidaaaak!!!",
  ui_story_5032_50321002_77_dialog_content = "Fi! Tunggu aku!!!",
  ui_story_5032_50321002_78_dialog_content = "Ah-!",
  ui_story_5032_50321002_79_dialog_content = "PlayerName! Apa yang kamu lakukan di sini juga?!",
  ui_story_5032_50321002_80_dialog_content = "Aku tergelincir!",
  ui_story_5032_50321002_81_dialog_content = "Tidak! Sekarang aku tidak akan pernah bisa memakan permen yang kusimpan di kamarku... Apakah ini akan berakhir untukku?!",
  ui_story_5032_50321002_82_dialog_content = "Saya juga tidak pernah menggunakan semua uang belanja yang saya peroleh dengan susah payah!",
  ui_story_5032_50321002_83_dialog_content = "Gan, gan, gan...",
  ui_story_5032_50321002_84_dialog_content = "(Aku... Aku tidak bisa bernapas...)",
  ui_story_5032_50321002_85_dialog_content = "<color=#e8d9bb>Duar—!</color>",
  ui_story_5032_50321002_86_dialog_content = "Di sekelilingku... Suara gemericik air...",
  ui_story_5032_50321002_87_dialog_content = "Aku bisa bernafas lagi... Mungkinkah aku... mati?",
  ui_story_5032_50321002_88_dialog_content = "Jangan bodoh, PlayerName! Kamu masih hidup, begitu juga aku!",
  ui_story_5032_50321002_89_dialog_content = "Buka mata Anda dan lihat sendiri! Geedo menyelamatkan kita!",
  ui_story_5032_50321002_90_dialog_content = "I-Ini sangat besar!!",
  ui_story_5032_50321002_91_dialog_content = "Saya tidak tahu Geedo bisa menjadi sebesar ini! Juga... Apakah Geedo terbang?!",
  ui_story_5032_50321002_92_dialog_content = "Bagaimanapun juga, Cloudwhale adalah binatang eksotis yang menakjubkan. Terbang tidak terlalu jauh dari pertanyaan!",
  ui_story_5032_50321002_93_dialog_content = "Harus kuakui, aku juga tidak menyangka Geedo bisa terbang...",
  ui_story_5032_50321002_94_dialog_content = "<color=#e8d9bb>Gemuruh…</color>",
  ui_story_5032_50321002_95_dialog_content = "Apa raungan tumpul tadi? Juga... Apakah saya, atau apakah Anda merasakan sesuatu yang gemetar?",
  ui_story_5032_50321002_96_dialog_content = "Uh-oh... Turun dan pegang erat-erat, PlayerName!",
  ui_story_5032_50321002_97_dialog_content = "Apa?!",
  ui_story_5032_50321002_98_dialog_content = "Hah?",
  ui_story_5032_50321002_99_dialog_content = "Ooooooh!",
  ui_story_5032_50321002_100_dialog_content = "Apakah itu... Apakah itu menyemburkan seperti ikan paus?!",
  ui_story_5032_50321002_101_dialog_content = "<color=#e8d9bb>Gruk!</color>",
  ui_story_5032_50321002_102_dialog_content = "Sungguh semburan air yang luar biasa! Rasanya seolah-olah kita berdiri di tengah hujan!",
  ui_story_5032_50321002_103_dialog_content = "Astaga! Graaaaaah!",
  ui_story_5032_50321002_104_dialog_content = "Graa... Graaah...",
  ui_story_5032_50321002_105_dialog_content = "Airnya... Sepertinya mempengaruhi Eclipsites!",
  ui_story_5032_50321002_106_dialog_content = "Apakah Fia selama ini benar?",
  ui_story_5032_50321101_1_dialog_content = "*Batuk* The Eclipsites... Kenapa gerakan mereka terlihat sangat lamban sekarang?",
  ui_story_5032_50321101_2_dialog_content = "Aliran Gelap tampaknya menipis juga ...",
  ui_story_5032_50321101_3_dialog_content = "Mungkinkah binatang besar di langit itu bertanggung jawab atas ini?",
  ui_story_5032_50321101_4_dialog_content = "Apakah itu... Paus Awan?",
  ui_story_5032_50321101_5_dialog_content = "Sekarang aku memikirkannya, gadis kecil itu berbicara tentang mencari satu sebelumnya... Fia, aku percaya?",
  ui_story_5032_50321101_6_dialog_content = "Dan selama ini, kupikir dia hanyalah anak kecil naif yang mengejar dongeng...",
  ui_story_5032_50321101_7_dialog_content = "Saya tidak pernah berpikir dia akan benar-benar menemukannya!",
  ui_story_5032_50321101_8_dialog_content = "Seekor Paus Awan?",
  ui_story_5032_50321101_9_dialog_content = "Ya... Jenis binatang ajaib yang sangat langka, yang sangat langka hingga menjadi legenda... Bahkan aku hanya pernah melihat gambarannya di buku.",
  ui_story_5032_50321101_10_dialog_content = "Meskipun tubuhnya menyerupai ikan paus, ia juga mampu terbang dan berada jauh di atas awan.",
  ui_story_5032_50321101_11_dialog_content = "Lumina yang kuat mampu menghalangi Eclipsites dan menghilangkan Darkflow yang paling tebal sekalipun.",
  ui_story_5032_50321101_12_dialog_content = "Di luar itu, ada sedikit pengetahuan berharga tentang Cloudwhales, mengingat betapa langkanya mereka.",
  ui_story_5032_50321101_13_dialog_content = "Aku tahu.",
  ui_story_5032_50321101_14_dialog_content = "Kamu masih suka membaca tentang legenda dan dongeng fantasi... *Batuk, Batuk*",
  ui_story_5032_50321101_15_dialog_content = "Setidaknya, sepertinya kita tidak perlu khawatir tentang gangguan dari Eclipsites terdekat untuk saat ini.",
  ui_story_5032_50321101_16_dialog_content = "Kau benar... Lagi pula, sepertinya Harbour City benar-benar diberkati oleh dewa.",
  ui_story_5032_50321101_17_dialog_content = "Kota ini tidak hanya memiliki orang bodoh untuk seorang laird yang bersedia mempertaruhkan nyawanya demi kota itu... tapi sekarang, kota itu memiliki perlindungan dari salah satu binatang ajaib paling langka di seluruh dunia.",
  ui_story_5032_50321101_18_dialog_content = "Hehe.. Tidak hanya itu..",
  ui_story_5032_50321101_19_dialog_content = "Kota ini juga memiliki seorang pesulap yang gila... Seseorang yang bersedia menemani laird kota dalam semua usahanya yang bodoh...",
  ui_story_5032_50321101_20_dialog_content = "Harbour City benar-benar beruntung... Dan begitu.. aku... *Batuk, batuk*",
  ui_story_5032_50321101_21_dialog_content = "*Batuk* Ugh!",
  ui_story_5032_50321101_22_dialog_content = "Haa... Apakah aku... pada batasku?",
  ui_story_5032_50321101_23_dialog_content = "Hanya berbaring di sini untuk saat ini. Cobalah untuk tidak berbicara. Anda perlu menyimpan kekuatan Anda.",
  ui_story_5032_50321101_24_dialog_content = "Karena kita tidak perlu khawatir tentang Eclipsites lagi, saya memiliki lebih banyak Lumina.",
  ui_story_5032_50321101_25_dialog_content = "Anda... Anda akan meningkatkan input Lumina Anda sendiri?",
  ui_story_5032_50321101_26_dialog_content = "Urgh... Merasa Lumina-ku terlepas seperti ini... Rasanya tidak enak.",
  ui_story_5032_50321101_27_dialog_content = "Inikah yang kau hadapi selama ini, Elvis?",
  ui_story_5032_50321101_28_dialog_content = "Tolong... Hentikan, Jeno! Jika Anda terus berjalan ... Anda akan mati juga!",
  ui_story_5032_50321101_29_dialog_content = "Ini hanya sedikit Lumina... Aku tidak akan membiarkanmu meninggalkanku lagi.",
  ui_story_5032_50321101_30_dialog_content = "Kali ini... Aku akan berdiri tepat di depanmu!",
  ui_story_5032_50321101_31_dialog_content = "*Batuk* Jeno...",
  ui_story_5032_50321101_32_dialog_content = "Ekstraksi energi selesai.",
  ui_story_5032_50321101_33_dialog_content = "Sistem siap untuk diaktifkan.",
  ui_story_5032_50321101_34_dialog_content = "Akhirnya Anda kenyang, ya?",
  ui_story_5032_50321101_35_dialog_content = "Siapa sangka batu sekecil itu bisa menampung Lumina sebanyak ini?",
  ui_story_5032_50321101_36_dialog_content = "*Uhuk-uhuk*",
  ui_story_5032_50321101_37_dialog_content = "Elvis! Apa kamu baik baik saja?",
  ui_story_5032_50321101_38_dialog_content = "*Terengah-engah* Jeno... Saat semuanya sudah beres... Tolong berikan Windstone itu kepada Patou menggantikanku.",
  ui_story_5032_50321101_39_dialog_content = "Aku sudah... sudah memberitahunya... apa yang harus dilakukan.",
  ui_story_5032_50321101_40_dialog_content = "Elvis...",
  ui_story_5032_50321101_41_dialog_content = "Berjanjilah padaku, Jeno... Berjanjilah padaku bahwa kau akan mengantarkan Windstone ke Patou.",
  ui_story_5032_50321101_42_dialog_content = "Anda dapat memberikannya sendiri setelah segel diaktifkan kembali.",
  ui_story_5032_50321101_43_dialog_content = "Tolong, Jeno... Tolong aku untuk terakhir kalinya... Aku merasa sangat lelah...",
  ui_story_5032_50321101_44_dialog_content = "Sejak hari aku meninggalkanmu... Aku selalu merasa... sangat lelah...",
  ui_story_5032_50321101_45_dialog_content = "Tolong... Biarkan aku istirahat sebentar, ya?",
  ui_story_5032_50321101_46_dialog_content = "...",
  ui_story_5032_50321101_47_dialog_content = "Aku mengerti.",
  ui_story_5032_50321101_48_dialog_content = "Terima kasih, Jeno.",
  ui_story_5032_50321101_49_dialog_content = "Terimakasih untuk semuanya.",
  ui_story_5032_50321101_50_dialog_content = "Batu Angin... Aktifkan.",
  ui_story_5032_50321101_51_dialog_content = "Perintah diakui.",
  ui_story_5032_50321101_52_dialog_content = "Apa cahaya itu? Ini sangat cerah!",
  ui_story_5032_50321101_53_dialog_content = "Itu ke arah kemana Laird Elvis pergi! Mungkinkah dia dalam bahaya?",
  ui_story_5032_50321101_54_dialog_content = "Lihat! The Eclipsites... Mereka mundur ke laut!",
  ui_story_5032_50321101_55_dialog_content = "Kamu benar! Bahkan Eclipsites tingkat tinggi pun mundur!",
  ui_story_5032_50321101_56_dialog_content = "Aliran Gelap menghilang! Aku merasa hidup kembali!!",
  ui_story_5032_50321101_57_dialog_content = "Itu pasti Laird Elvis! Dia pasti menemukan cara untuk mengalahkan Eclipsites!",
  ui_story_5032_50321101_58_dialog_content = "Ini pasti perbuatan Laird Elvis!",
  ui_story_5032_50321101_59_dialog_content = "Kau dengar itu, Elvis?",
  ui_story_5032_50321101_60_dialog_content = "Orang-orangmu menangis untukmu... Mereka merayakan kemenangan ini atas namamu.",
  ui_story_5032_50321101_61_dialog_content = "Anda melakukannya. Windstone dan segel telah diaktifkan kembali.",
  ui_story_5032_50321101_62_dialog_content = "Heheh... Aku senang mendengarnya.",
  ui_story_5032_50321101_63_dialog_content = "Anda juga mengatakan Anda akan membuat segalanya untuk saya sebelumnya, ingat?",
  ui_story_5032_50321101_64_dialog_content = "Setelah debu mengendap, saya berencana untuk mengumpulkan secara penuh... Jadi bersiaplah untuk itu.",
  ui_story_5032_50321101_65_dialog_content = "Kapal saya sangat membutuhkan perbaikan, dan Anda akan bertanggung jawab untuk membuatnya layak laut lagi.",
  ui_story_5032_50321101_66_dialog_content = "Saya mungkin seorang pesulap, tetapi saya berjanji untuk tidak menyesatkan Anda tentang biaya perbaikan. Sebenarnya, saya akan meminta Rainbow menyusun daftar terperinci untuk membuat semuanya sangat jelas. Yang perlu Anda lakukan hanyalah menyiapkan dompet Anda.",
  ui_story_5032_50321101_67_dialog_content = "Begitu... Itu seharusnya tidak menjadi masalah...",
  ui_story_5032_50321101_68_dialog_content = "Juga, karena kami tidak memiliki cara untuk melanjutkan tur kami, kami akan tinggal di Harbour City lebih lama lagi.",
  ui_story_5032_50321101_69_dialog_content = "Sementara itu, kita bisa mencoba membangun restoran seni yang biasa kita bicarakan.",
  ui_story_5032_50321101_70_dialog_content = "Siapa tahu? Mungkin itu bisa menjadi tempat kami untuk pertunjukan di masa depan?",
  ui_story_5032_50321101_71_dialog_content = "Selain itu, seseorang dengan statusmu seharusnya tidak kesulitan membangun restoran di sini...",
  ui_story_5032_50321101_72_dialog_content = "Jeno...",
  ui_story_5032_50321101_73_dialog_content = "Ya? Aku di sini, Elvis.",
  ui_story_5032_50321101_74_dialog_content = "Langit di atas Harbour City... cerah.",
  ui_story_5032_50321101_75_dialog_content = "Ini selalu... pemandangan favoritku.",
  ui_story_5032_50321101_76_dialog_content = "<size=30>Bisakah kamu... melukisnya untukku suatu hari nanti?</size>",
  ui_story_5032_50321101_77_dialog_content = "Tentu. Saya berjanji.",
  ui_story_5032_50321101_78_dialog_content = "Ingat lukisan yang Anda minta terakhir kali? Aku sudah menyelesaikannya sejak lama... Sudah digantung di kamarku selama ini.",
  ui_story_5032_50321101_79_dialog_content = "Tapi itu mungkin tidak persis seperti yang Anda inginkan. Lagi pula, saya harus bergantung sepenuhnya pada ingatan untuk melukisnya.",
  ui_story_5032_50321101_80_dialog_content = "Anda bisa melihat sendiri nanti. Jika Anda tidak menyukainya, saya selalu bisa melukis Anda yang lain.",
  ui_story_5032_50321101_81_dialog_content = "...",
  ui_story_5032_50321101_82_dialog_content = "... Elvis?",
  ui_story_5032_50321101_83_dialog_content = "...",
  ui_story_5032_50321101_84_dialog_content = "Cih... Kau sesuatu yang lain, kau tahu itu?",
  ui_story_5032_50321101_85_dialog_content = "Selalu buat janji yang tidak bisa ditepati...",
  ui_story_5032_50321101_86_dialog_content = "Kau pembohong, Elvis...",
  ui_story_5032_50321101_87_dialog_content = "Pembohong yang tidak berguna...",
  ui_story_5032_50321101_88_dialog_content = "<color=#e8d9bb>Lima Hari Kemudian</color>",
  ui_story_5032_50321101_89_dialog_content = "*Berdesah*",
  ui_story_5032_50321101_90_dialog_content = "Sepertinya Anda lupa pakaian Anda, PlayerName. Seseorang datang dan menurunkan mereka.",
  ui_story_5032_50321101_91_dialog_content = "K-Kamu benar, aku hampir lupa mengemasnya! Terima kasih, Vice!",
  ui_story_5032_50321101_92_dialog_content = "Keputusan Carleen untuk pulang sangat mengejutkan, jadi karena terburu-buru untuk mengemas semuanya, saya hampir melewatkan beberapa hal.",
  ui_story_5032_50321101_93_dialog_content = "*Berdesah*",
  ui_story_5032_50321101_94_dialog_content = "Mengapa Anda tidak melihat-lihat lagi dan memastikan Anda tidak melupakan hal lain? Carleen masih bertemu dengan pejabat kota, jadi kau punya waktu untuk pemeriksaan terakhir.",
  ui_story_5032_50321101_95_dialog_content = "Tentu, aku akan pergi melihatnya.",
  ui_story_5032_50321101_96_dialog_content = "*Berdesah*",
  ui_story_5032_50321101_97_dialog_content = "... Ada apa, Fia?",
  ui_story_5032_50321101_98_dialog_content = "Apakah ada sesuatu di pikiranmu, Fia? Kamu sudah mengerutkan kening sejak kita bangun pagi ini.",
  ui_story_5032_50321101_99_dialog_content = "Aku hanya memikirkan bagaimana Geedo meninggalkan kita begitu tiba-tiba...",
  ui_story_5032_50321101_100_dialog_content = "Bagaimana saya harus menjelaskan ini kepada tuan saya ?!",
  ui_story_5032_50321101_101_dialog_content = "lihat...",
  ui_story_5032_50321101_102_dialog_content = "Tuanmu seharusnya bisa merasakan kehadiran Geedo lagi, bukan begitu?",
  ui_story_5032_50321101_103_dialog_content = "Saya yakin dia menyadarinya saat Anda membebaskan Geedo dari botol.",
  ui_story_5032_50321101_104_dialog_content = "Anda tidak mengerti, Vice ... Jika saya tidak menunjukkan kepadanya bukti bahwa misi saya selesai, dia tidak akan membayar!",
  ui_story_5032_50321101_105_dialog_content = "Dia akan berpura-pura seolah-olah aku berbohong, dan semua hadiah yang dia janjikan padaku untuk pekerjaan yang dilakukan dengan baik... Dia akan membuang semuanya!",
  ui_story_5032_50321101_106_dialog_content = "Kedengarannya seperti hubungan yang adil dan setara bagiku, Fia.",
  ui_story_5032_50321101_107_dialog_content = "Itu cukup dari Anda, PlayerName!",
  ui_story_5032_50321101_108_dialog_content = "Tuan Fia memang terdengar sedikit berlebihan, bukan begitu?",
  ui_story_5032_50321101_109_dialog_content = "Apa yang harus kita lakukan, PlayerName? Pikir kita bisa membawa Fia bersama kita dan menerbangkannya pulang di Soroz?",
  ui_story_5032_50321101_110_dialog_content = "Dengan begitu, kita bisa bertindak sebagai saksinya.",
  ui_story_5032_50321101_111_dialog_content = "Terdengar bagus untukku!",
  ui_story_5032_50321101_112_dialog_content = "H-Hah? Betulkah?! Itu akan bagus!",
  ui_story_5032_50321101_113_dialog_content = "Terima kasih banyak, Vice! Kali ini, saya akan membuat tuan membayar setiap bagian dari hutangnya kepada saya! Muahahaha!",
  ui_story_5032_50321101_114_dialog_content = "Kalian bertiga tampaknya memiliki semangat yang cukup tinggi, kan?",
  ui_story_5032_50321101_115_dialog_content = "Ah! Apa aku baru saja mendengar suara Subli?",
  ui_story_5032_50321101_116_dialog_content = "Hiya!",
  ui_story_5032_50321101_117_dialog_content = "Rainbow memberi tahu kami bahwa Anda sedang menuju keluar, jadi kami ingin mengirim Anda sendiri!",
  ui_story_5032_50321101_118_dialog_content = "...",
  ui_story_5032_50321101_119_dialog_content = "Perjalanan yang aman, semuanya!",
  ui_story_5032_50321101_120_dialog_content = "Datang dan saksikan pertunjukan kami di lain waktu jika Anda memiliki kesempatan! Saya akan memberi Anda banyak kursi primo!",
  ui_story_5032_50321101_121_dialog_content = "Ha ha ha! Kami mungkin akan menerima tawaran itu!",
  ui_story_5032_50321101_122_dialog_content = "Hei... Aku tidak melihat Ciel dimanapun. Dia tidak ikut denganmu, Rainbow?",
  ui_story_5032_50321101_123_dialog_content = "Ciel menerima panggilan darurat dari Illumina kemarin. Dia pergi dengan sangat terburu-buru juga.",
  ui_story_5032_50321101_124_dialog_content = "Begitu... Ciel benar-benar sibuk, bukan? Mereka bahkan memanggilnya kembali dari liburannya...",
  ui_story_5032_50321101_125_dialog_content = "Kami seharusnya memulai perbaikan pada Emerald hari ini...",
  ui_story_5032_50321101_126_dialog_content = "Tapi Merylt praktis memohon satu kesempatan terakhir untuk melihat Caelestite, jadi itu sebabnya...",
  ui_story_5032_50321101_127_dialog_content = "Aduh!",
  ui_story_5032_50321101_128_dialog_content = "F-Frimet!",
  ui_story_5032_50321101_129_dialog_content = "Ha ha ha ha! Sepertinya Anda memiliki penggemar fanatik, PlayerName.",
  ui_story_5032_50321101_130_dialog_content = "Benar sekali!",
  ui_story_5032_50321101_131_dialog_content = "Jujur... Maksudku, apa yang hebat tentang PlayerName omong-omong?",
  ui_story_5032_50321101_132_dialog_content = "Bagaimana dengan saya? Saya juga banyak membantu, Anda tahu! Dan Kyllo juga membantu kalian menemukan kucing berekor tiga!",
  ui_story_5032_50321101_133_dialog_content = "Kamu benar sekali, Fia... Kyllo juga pantas mendapatkan rasa terima kasih kita!",
  ui_story_5032_50321101_134_dialog_content = "Bukan begitu, Kyl?",
  ui_story_5032_50321101_135_dialog_content = "Lihat!",
  ui_story_5032_50321101_136_dialog_content = "A-Apa?!",
  ui_story_5032_50321101_137_dialog_content = "Itu berhasil, Frimet! Aku akan menunjukkan betapa kuatnya aku!",
  ui_story_5032_50321101_138_dialog_content = "Astaga... Hanya itu yang diperlukan untuk membuatmu bersemangat?",
  ui_story_5032_50321101_139_dialog_content = "Hehehe, sepertinya Fia juga punya teman baru.",
  ui_story_5032_50321101_140_dialog_content = "Itu pasti terlihat seperti itu. Saya sangat senang untuk mereka!",
  ui_story_5032_50321101_141_dialog_content = "Frimet dan saudara perempuannya menghabiskan sebagian besar hari mereka berinteraksi dengan penonton... Mereka jarang memiliki kesempatan untuk berbicara dengan orang lain di luar kapasitas itu.",
  ui_story_5032_50321101_142_dialog_content = "Akibatnya, mereka tidak benar-benar memiliki teman seusia mereka.",
  ui_story_5032_50321101_143_dialog_content = "Mereka sangat beruntung telah bertemu seseorang seperti Fia...",
  ui_story_5032_50321101_144_dialog_content = "Begitu juga dengan kalian yang lain. Kami semua sangat beruntung memiliki teman seperti Anda!",
  ui_story_5032_50321101_145_dialog_content = "*Menangis* Rainbow...",
  ui_story_5032_50321101_146_dialog_content = "Kami yang beruntung bisa bertemu kalian semua, Rainbow!",
  ui_story_5032_50321101_147_dialog_content = "Heehee!",
  ui_story_5032_50321101_148_dialog_content = "Katakanlah, apakah ada di antara kalian yang melihat Carleen di sekitar?",
  ui_story_5032_50321101_149_dialog_content = "Carleen masih harus bertemu dengan anggota DPR Modali. Kami sudah menunggunya di sini untuk menyelesaikan bisnisnya.",
  ui_story_5032_50321101_150_dialog_content = "Lagi pula, begitu banyak yang telah terjadi... Aku yakin ada banyak hal yang membutuhkan perhatiannya saat ini.",
  ui_story_5032_50321101_151_dialog_content = "<size=30>Jadi beginilah kehidupan seorang putri, huh... Keren sekali!</size>",
  ui_story_5032_50321101_152_dialog_content = "Hmm? Apakah Anda mengatakan sesuatu?",
  ui_story_5032_50321101_153_dialog_content = "Ehehe... Kamu seharusnya tidak banyak bertanya pada seorang gadis, PlayerName!",
  ui_story_5032_50321101_154_dialog_content = "Pikirkan saja urusanmu sendiri, oke?!",
  ui_story_5032_50321101_155_dialog_content = "Wah!",
  ui_story_5032_50321101_156_dialog_content = "C-Hati-hati, Merylt!",
  ui_story_5032_50321101_157_dialog_content = "Serius, apa yang Anda pikir Anda lakukan, Subli?",
  ui_story_5032_50321101_158_dialog_content = "Hei, dia hanya mencoba membantu adiknya dengan caranya sendiri! Ha ha ha!",
  ui_story_5032_50321101_159_dialog_content = "Lakukan yang terbaik, Merylt!",
  ui_story_5032_50321101_160_dialog_content = "Eh? Rainbow-?",
  ui_story_5032_50321101_161_dialog_content = "SS-Maaf soal i-itu!",
  ui_story_5032_50321101_162_dialog_content = "Tidak apa-apa, Merylt. Satu-satunya alasan kamu menabrakku adalah karena Subli barusan mendorongmu.",
  ui_story_5032_50321101_163_dialog_content = "Itu tidak sakit sama sekali, jujur!",
  ui_story_5032_50321101_164_dialog_content = "...",
  ui_story_5032_50321101_165_dialog_content = "(Ini... Ini kesempatan terakhirku!)",
  ui_story_5032_50321101_166_dialog_content = "A-anu...",
  ui_story_5032_50321101_167_dialog_content = "Saya menulis surat kepada Anda, PlayerName.",
  ui_story_5032_50321101_168_dialog_content = "Hah? Sebuah surat?",
  ui_story_5032_50321101_169_dialog_content = "T-Tolong jangan buka sampai setelah kamu pergi!",
  ui_story_5032_50321101_170_dialog_content = "Tentu, tidak masalah... Terima kasih!",
  ui_story_5032_50321101_171_dialog_content = "A-Juga...",
  ui_story_5032_50321101_172_dialog_content = "Apakah ada sesuatu yang lain?",
  ui_story_5032_50321101_173_dialog_content = "J-Jika itu tidak terlalu merepotkan... Bolehkah aku...",
  ui_story_5032_50321101_174_dialog_content = "<size=30>B-Bolehkah aku...</size>",
  ui_story_5032_50321101_175_dialog_content = "Maaf, apa itu?",
  ui_story_5032_50321101_176_dialog_content = "<size=45>Bolehkah aku mengunjungimu di Eraveil suatu hari nanti?!</size>",
  ui_story_5032_50321101_177_dialog_content = "Wow! K-Kamu membuatku takut sekarang!",
  ui_story_5032_50321101_178_dialog_content = "aku minta maaf! Apa aku aneh menanyakan itu?",
  ui_story_5032_50321101_179_dialog_content = "Aku benar-benar mengerti jika itu tidak baik! Anda hanya bisa mengatakannya, dan saya tidak akan mengganggu Anda lagi!",
  ui_story_5032_50321101_180_dialog_content = "Maaf, aku tahu memintamu hanya akan membuat lebih banyak masalah...",
  ui_story_5032_50321101_181_dialog_content = "Tentu!",
  ui_story_5032_50321101_182_dialog_content = "Hah?",
  ui_story_5032_50321101_183_dialog_content = "Tentu saja, Anda bisa datang menemui saya kapan saja! Kita berteman, bukan begitu, Merylt?",
  ui_story_5032_50321101_184_dialog_content = "Jika Anda ingin mengunjungi Eraveil, pintunya selalu terbuka. Anda bahkan dapat membawa beberapa teman Anda jika Anda suka!",
  ui_story_5032_50321101_185_dialog_content = "Rekonstruksi telah berjalan dengan baik, jadi saya yakin ada banyak kamar untuk Anda tinggali.",
  ui_story_5032_50321101_186_dialog_content = "K-Teman...?",
  ui_story_5032_50321101_187_dialog_content = "... T-Terima kasih!",
  ui_story_5032_50321101_188_dialog_content = "Sekarang setelah Anda menyebutkannya, saya mungkin harus mampir ke Umbraton dalam perjalanan kembali.",
  ui_story_5032_50321101_189_dialog_content = "Jika kita ingin menyambut tamu, kita mungkin perlu menyiapkan makanan. Kami juga hampir kehabisan herbisida untuk gulma...",
  ui_story_5032_50321101_190_dialog_content = "Kami juga kehabisan sabun cuci dan segudang kebutuhan sehari-hari lainnya... Hmmm...",
  ui_story_5032_50321101_191_dialog_content = "Kami akan membutuhkan beberapa persediaan untuk membantu kami mengalahkan panas, juga...",
  ui_story_5032_50321101_192_dialog_content = "(Frimet, Subli, saya pikir ...)",
  ui_story_5032_50321101_193_dialog_content = "(Saya pikir saya tahu mengapa saya sangat menyukai Caelestite ini sekarang.)",
  ui_story_5032_50321101_194_dialog_content = "Frimet... Dia licin seperti belut dalam ember minyak!",
  ui_story_5032_50321101_195_dialog_content = "Lagipula, dia adalah pemain sirkus yang terlatih...",
  ui_story_5032_50321101_196_dialog_content = "Urgh... Aku tidak akan bersikap mudah padanya lain kali! Aku bersumpah!",
  ui_story_5032_50321101_197_dialog_content = "Lihat!",
  ui_story_5032_50321101_198_dialog_content = "Maaf telah membuat kalian semua menunggu.",
  ui_story_5032_50321101_199_dialog_content = "Sepertinya saya melewatkan banyak kesenangan.",
  ui_story_5032_50321101_200_dialog_content = "Carleen! Kamu kembali!",
  ui_story_5032_50321101_201_dialog_content = "Anda tidak ketinggalan banyak, hanya Frimet yang benar-benar membodohi Fia... Aduh!",
  ui_story_5032_50321101_202_dialog_content = "Itu benar-benar menyakitkan! Berhenti menginjak kakiku!",
  ui_story_5032_50321101_203_dialog_content = "Hmph! Itu akan mengajarimu untuk mengolok-olokku, PlayerName.",
  ui_story_5032_50321101_204_dialog_content = "Baiklah, semuanya, cukup untuk saat ini.",
  ui_story_5032_50321101_205_dialog_content = "Apakah semuanya sudah diurus di pihakmu, Carleen?",
  ui_story_5032_50321101_206_dialog_content = "*Sigh* Bisa dibilang begitu, ya.",
  ui_story_5032_50321101_207_dialog_content = "Saya tidak bisa mencapai kesepakatan dengan Loewe dan Matthieu tentang cara terbaik untuk melanjutkan. Frustrasi karena telah, mereka tidak lagi ingin merahasiakan semuanya.",
  ui_story_5032_50321101_208_dialog_content = "Mereka menerima rencana perjalanan saya pagi ini dan kembali ke Lumopolis.",
  ui_story_5032_50321101_209_dialog_content = "Ayah sangat tidak senang ketika saya sebelumnya menipu dia ... Saya masih harus mencari tahu apa yang akan saya katakan kepadanya ketika saya kembali.",
  ui_story_5032_50321101_210_dialog_content = "Itu benar... kau pada dasarnya menyembunyikan kebenaran dari Lord Schwartz demi Harbour City.",
  ui_story_5032_50321101_211_dialog_content = "Untungnya, Matthieu dan yang lainnya tidak tahu banyak tentang Windstone.",
  ui_story_5032_50321101_212_dialog_content = "Setidaknya, itu satu hal yang kurang perlu dikhawatirkan.",
  ui_story_5032_50321101_213_dialog_content = "Rumah Modali benar-benar kacau sekarang... Mereka masih perlu menunjuk laird baru juga.",
  ui_story_5032_50321101_214_dialog_content = "Jika tersiar kabar tentang Windstone, mereka tidak akan pernah bisa menangani banyak hal.",
  ui_story_5032_50321101_215_dialog_content = "Jadi...",
  ui_story_5032_50321101_216_dialog_content = "Apakah itu berarti Elvis masih belum menunjukkan tanda-tanda bangun?",
  ui_story_5032_50321101_217_dialog_content = "Memang. Saat ini, dia masih dalam keadaan koma yang dalam.",
  ui_story_5032_50321101_218_dialog_content = "Jika bukan karena Jeno membantunya menanggung beban untuk mengaktifkan kembali Windstone, Elvis pasti sudah mati.",
  ui_story_5032_50321101_219_dialog_content = "Namun, bahkan dokter terbaik pun tidak bisa membangunkannya dari koma seperti ini.",
  ui_story_5032_50321101_220_dialog_content = "*Sigh* Sangat sedih melihatnya seperti itu, dan setelah semua pertempuran yang dia lalui...",
  ui_story_5032_50321101_221_dialog_content = "Mungkin... ini takdir Elvis?",
  ui_story_5032_50321101_222_dialog_content = "Keinginan Elvis untuk melindungi rakyatnya menyebabkan bencana ini sejak awal.",
  ui_story_5032_50321101_223_dialog_content = "Jadi, satu-satunya cara untuk menyelamatkan rakyatnya dari kesalahannya sendiri adalah dengan mengorbankan dirinya sendiri.",
  ui_story_5032_50321101_224_dialog_content = "Di satu sisi, Anda dapat mengatakan bahwa dia mencapai apa yang dia mulai lakukan sejak awal.",
  ui_story_5032_50321101_225_dialog_content = "Seseorang seperti dia pasti sudah berdamai dengan ini sebagai hasil yang mungkin.",
  ui_story_5032_50321101_226_dialog_content = "...",
  ui_story_5032_50321101_227_dialog_content = "Luar biasa... Kamu selalu berhasil berbicara dengan sangat baik di saat yang paling penting, Fia.",
  ui_story_5032_50321101_228_dialog_content = "Mau tak mau aku lebih mengagumimu setelah mengatakan itu.",
  ui_story_5032_50321101_229_dialog_content = "Apa? Maksud Anda, Anda tidak bisa sampai pada kesimpulan sederhana seperti itu sendiri, PlayerName?",
  ui_story_5032_50321101_230_dialog_content = "Anda tidak akan bertahan sehari di masyarakat jika Anda tidak mulai memikirkan diri sendiri sedikit lagi, Anda tahu!",
  ui_story_5032_50321101_231_dialog_content = "Aku baru saja memberimu pujian! Jangan biarkan itu pergi ke kepala Anda!",
  ui_story_5032_50321101_232_dialog_content = "Pertahankan ini, dan saya mungkin berubah pikiran tentang membantu Anda menjelaskan berbagai hal kepada tuan Anda!",
  ui_story_5032_50321101_233_dialog_content = "A-Apa?! Tidak, tolong! Apapun selain itu!",
  ui_story_5032_50321101_234_dialog_content = "Anda sudah berjanji untuk membantu! Orang macam apa kamu jika kamu tidak menepati janjimu?!",
  ui_story_5032_50321101_235_dialog_content = "Fia memang membuat poin yang bagus, Anda tahu.",
  ui_story_5032_50321101_236_dialog_content = "Ini mungkin hasil yang paling diinginkan Elvis.",
  ui_story_5032_50321101_237_dialog_content = "Bagaimanapun, kedamaian akhirnya kembali ke Harbour City.",
  ui_story_5032_50321101_238_dialog_content = "Sangat menyedihkan bahwa terlepas dari semua kerja keras dan pengorbanannya, Sindrom Modali masih menjadi masalah.",
  ui_story_5032_50321101_239_dialog_content = "Sebenarnya, ini adalah salah satu hal yang tidak terlalu membutuhkan perhatian, setidaknya untuk saat ini.",
  ui_story_5032_50321101_240_dialog_content = "Jeno memberitahuku bahwa Windstone tampaknya telah menyerap Lumina Cloudwhale dalam jumlah besar selama pertempuran terakhir.",
  ui_story_5032_50321101_241_dialog_content = "Akibatnya, Windstone memprioritaskan penggunaan Lumina Cloudwhale yang lebih murni untuk melindungi Harbour City dari serangan Eclipsite.",
  ui_story_5032_50321101_242_dialog_content = "Betulkah? Itu luar biasa!",
  ui_story_5032_50321101_243_dialog_content = "Jika itu benar, maka pengorbanan Elvis sama sekali tidak sia-sia!",
  ui_story_5032_50321101_244_dialog_content = "Itu mengingatkan saya, saya belum melihat Jeno sama sekali akhir-akhir ini.",
  ui_story_5032_50321101_245_dialog_content = "Apakah dia baik baik saja?",
  ui_story_5032_50321101_246_dialog_content = "Kondisi Elvis telah menyebabkan dia tidak sedikit kesusahan... Dia bahkan kehilangan berat badan karena khawatir.",
  ui_story_5032_50321101_247_dialog_content = "Tetapi ketika saya melihatnya kemarin, dia tampaknya telah mendapatkan kembali ketenangannya yang biasa.",
  ui_story_5032_50321101_248_dialog_content = "Aku menemukannya!",
  ui_story_5032_50321101_249_dialog_content = "Saya pikir saya menemukan cara untuk membangunkannya lagi!",
  ui_story_5032_50321101_250_dialog_content = "Apa?",
  ui_story_5032_50321101_251_dialog_content = "Maafkan aku, Putri Carleen...",
  ui_story_5032_50321101_252_dialog_content = "Tapi aku harus pergi... Aku harus segera menemukannya!",
  ui_story_5032_50321101_253_dialog_content = "Jadi dia benar-benar menemukan cara untuk membangunkan Elvis dari komanya?",
  ui_story_5032_50321101_254_dialog_content = "Mungkin saja.",
  ui_story_5032_50321101_255_dialog_content = "Tetapi bahkan jika dia berhasil membangunkan Elvis, ini tidak akan menyelamatkannya dari penghakiman Lumopolis.",
  ui_story_5032_50321101_256_dialog_content = "Ironisnya, keadaan komanya adalah satu-satunya hal yang menjauhkannya dari hukumannya.",
  ui_story_5032_50321101_257_dialog_content = "Meski begitu, aku bisa memahami perasaan Jeno.",
  ui_story_5032_50321101_258_dialog_content = "Jika hal seperti itu terjadi pada Carleen, Vice, Fia, atau Kyllo...",
  ui_story_5032_50321101_259_dialog_content = "Saya yakin kita semua tidak akan berhenti mencari cara untuk menyelamatkan mereka.",
  ui_story_5032_50321101_260_dialog_content = "Anda membuat poin yang bagus juga!",
  ui_story_5032_50321101_261_dialog_content = "Bagaimanapun, kita semua adalah teman baik.",
  ui_story_5032_50321101_262_dialog_content = "Memang... kau benar, PlayerName.",
  ui_story_5032_50321101_263_dialog_content = "Bagaimanapun, ini mulai terlambat. Kita harus benar-benar pergi.",
  ui_story_5032_50321101_264_dialog_content = "Kami memiliki banyak perhentian untuk dilakukan. Umbraton, Lumopolis... dan rumah tuan Fia, juga.",
  ui_story_5032_50321101_265_dialog_content = "Kami memiliki perjalanan penuh di depan kami, ya?",
  ui_story_5032_50321101_266_dialog_content = "Yap, sekarang mari kita bergerak!",
  ui_story_5032_50321101_267_dialog_content = "Ayo kita pergi! Saya ingin membeli beberapa barang di Umbraton juga!",
  ui_story_5032_50321101_268_dialog_content = "PlayerName, kamu juga berjanji akan membelikanku baju renang buatan tangan!",
  ui_story_5032_50321101_269_dialog_content = "... Anda belum melupakannya setelah semuanya?!"
